INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 1, 1, 'Adam, Seth, Enosh;', 'en', 'NRSV-CE', 'From Adam to Abraham'),
(13, '1 Taw', '1 Chronicles', 1, 2, 'Kenan, Mahalalel, Jared;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 3, 'Enoch, Methuselah, Lamech;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 4, 'Noah, Shem, Ham, and Japheth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 5, 'The descendants of Japheth: Gomer, Magog, Madai, Javan, Tubal, Meshech, and Tiras.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 6, 'The descendants of Gomer: Ashkenaz, Diphath, and Togarmah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 7, 'The descendants of Javan: Elishah, Tarshish, Kittim, and Rodanim.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 8, 'The descendants of Ham: Cush, Egypt, Put, and Canaan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 9, 'The descendants of Cush: Seba, Havilah, Sabta, Raama, and Sabteca. The descendants of Raamah: Sheba and Dedan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 10, 'Cush became the father of Nimrod; he was the first to be a mighty one on the earth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 11, 'Egypt became the father of Ludim, Anamim, Lehabim, Naphtuhim,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 12, 'Pathrusim, Casluhim, and Caphtorim, from whom the Philistines come.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 13, 'Canaan became the father of Sidon his firstborn, and Heth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 14, 'and the Jebusites, the Amorites, the Girgashites,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 15, 'the Hivites, the Arkites, the Sinites,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 16, 'the Arvadites, the Zemarites, and the Hamathites.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 17, 'The descendants of Shem: Elam, Asshur, Arpachshad, Lud, Aram, Uz, Hul, Gether, and Meshech.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 18, 'Arpachshad became the father of Shelah; and Shelah became the father of Eber.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 19, 'To Eber were born two sons: the name of the one was Peleg (for in his days the earth was divided), and the name of his brother Joktan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 20, 'Joktan became the father of Almodad, Sheleph, Hazarmaveth, Jerah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 21, 'Hadoram, Uzal, Diklah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 22, 'Ebal, Abimael, Sheba,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 23, 'Ophir, Havilah, and Jobab; all these were the descendants of Joktan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 24, 'Shem, Arpachshad, Shelah;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 25, 'Eber, Peleg, Reu;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 26, 'Serug, Nahor, Terah;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 27, 'Abram, that is, Abraham.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 28, 'The sons of Abraham: Isaac and Ishmael.', 'en', 'NRSV-CE', 'From Abraham to Jacob'),
(13, '1 Taw', '1 Chronicles', 1, 29, 'These are their genealogies: the firstborn of Ishmael, Nebaioth; and Kedar, Adbeel, Mibsam,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 30, 'Mishma, Dumah, Massa, Hadad, Tema,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 31, 'Jetur, Naphish, and Kedemah. These are the sons of Ishmael.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 32, 'The sons of Keturah, Abraham"s concubine: she bore Zimran, Jokshan, Medan, Midian, Ishbak, and Shuah. The sons of Jokshan: Sheba and Dedan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 33, 'The sons of Midian: Ephah, Epher, Hanoch, Abida, and Eldaah. All these were the descendants of Keturah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 34, 'Abraham became the father of Isaac. The sons of Isaac: Esau and Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 35, 'The sons of Esau: Eliphaz, Reuel, Jeush, Jalam, and Korah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 36, 'The sons of Eliphaz: Teman, Omar, Zephi, Gatam, Kenaz, Timna, and Amalek.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 37, 'The sons of Reuel: Nahath, Zerah, Shammah, and Mizzah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 38, 'The sons of Seir: Lotan, Shobal, Zibeon, Anah, Dishon, Ezer, and Dishan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 39, 'The sons of Lotan: Hori and Homam; and Lotan"s sister was Timna.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 40, 'The sons of Shobal: Alian, Manahath, Ebal, Shephi, and Onam. The sons of Zibeon: Aiah and Anah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 41, 'The sons of Anah: Dishon. The sons of Dishon: Hamran, Eshban, Ithran, and Cheran.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 42, 'The sons of Ezer: Bilhan, Zaavan, and Jaakan. The sons of Dishan: Uz and Aran.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 43, 'These are the kings who reigned in the land of Edom before any king reigned over the Israelites: Bela son of Beor, whose city was called Dinhabah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 44, 'When Bela died, Jobab son of Zerah of Bozrah succeeded him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 45, 'When Jobab died, Husham of the land of the Temanites succeeded him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 46, 'When Husham died, Hadad son of Bedad, who defeated Midian in the country of Moab, succeeded him; and the name of his city was Avith.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 47, 'When Hadad died, Samlah of Masrekah succeeded him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 48, 'When Samlah died, Shaul of Rehoboth on the Euphrates succeeded him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 49, 'When Shaul died, Baal-hanan son of Achbor succeeded him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 50, 'When Baal-hanan died, Hadad succeeded him; the name of his city was Pai, and his wife"s name Mehetabel daughter of Matred, daughter of Me-zahab.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 1, 51, 'And Hadad died.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 2, 1, 'These are the sons of Israel: Reuben, Simeon, Levi, Judah, Issachar, Zebulun,', 'en', 'NRSV-CE', 'The Sons of Israel and the Descendants of Judah'),
(13, '1 Taw', '1 Chronicles', 2, 2, 'Dan, Joseph, Benjamin, Naphtali, Gad, and Asher.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 3, 'The sons of Judah: Er, Onan, and Shelah; these three the Canaanite woman Bath-shua bore to him. Now Er, Judah"s firstborn, was wicked in the sight of the LORD, and he put him to death.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 4, 'His daughter-in-law Tamar also bore him Perez and Zerah. Judah had five sons in all.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 5, 'The sons of Perez: Hezron and Hamul.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 6, 'The sons of Zerah: Zimri, Ethan, Heman, Calcol, and Dara, five in all.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 7, 'The sons of Carmi: Achar, the troubler of Israel, who transgressed in the matter of the devoted thing;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 8, 'and Ethan"s son was Azariah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 9, 'The sons of Hezron, who were born to him: Jerahmeel, Ram, and Chelubai.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 10, 'Ram became the father of Amminadab, and Amminadab became the father of Nahshon, prince of the sons of Judah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 11, 'Nahshon became the father of Salma, Salma of Boaz,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 12, 'Boaz of Obed, Obed of Jesse.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 13, 'Jesse became the father of Eliab his firstborn, Abinadab the second, Shimea the third,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 14, 'Nethanel the fourth, Raddai the fifth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 15, 'Ozem the sixth, David the seventh;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 16, 'and their sisters were Zeruiah and Abigail. The sons of Zeruiah: Abishai, Joab, and Asahel, three.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 17, 'Abigail bore Amasa, and the father of Amasa was Jether the Ishmaelite.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 18, 'Caleb son of Hezron had children by his wife Azubah, and by Jerioth; these were her sons: Jesher, Shobab, and Ardon.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 19, 'When Azubah died, Caleb married Ephrath, who bore him Hur.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 20, 'Hur became the father of Uri, and Uri became the father of Bezalel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 21, 'Afterward Hezron went in to the daughter of Machir father of Gilead, whom he married when he was sixty years old; and she bore him Segub;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 22, 'and Segub became the father of Jair, who had twenty-three towns in the land of Gilead.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 23, 'But Geshur and Aram took from them Havvoth-jair, Kenath and its villages, sixty towns. All these were descendants of Machir, father of Gilead.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 24, 'After the death of Hezron, in Caleb-ephrathah, Abijah wife of Hezron bore him Ashhur, father of Tekoa.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 25, 'The sons of Jerahmeel, the firstborn of Hezron: Ram his firstborn, Bunah, Oren, Ozem, and Ahijah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 26, 'Jerahmeel also had another wife, whose name was Atarah; she was the mother of Onam.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 27, 'The sons of Ram, the firstborn of Jerahmeel: Maaz, Jamin, and Eker.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 28, 'The sons of Onam: Shammai and Jada. The sons of Shammai: Nadab and Abishur.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 29, 'The name of Abishur"s wife was Abihail, and she bore him Ahban and Molid.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 30, 'The sons of Nadab: Seled and Appaim; and Seled died childless.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 31, 'The son of Appaim: Ishi. The son of Ishi: Sheshan. The son of Sheshan: Ahlai.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 32, 'The sons of Jada, Shammai"s brother: Jether and Jonathan; and Jether died childless.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 33, 'The sons of Jonathan: Peleth and Zaza. These were the descendants of Jerahmeel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 34, 'Now Sheshan had no sons, only daughters; but Sheshan had an Egyptian slave, whose name was Jarha.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 35, 'So Sheshan gave his daughter in marriage to his slave Jarha; and she bore him Attai.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 36, 'Attai became the father of Nathan, and Nathan of Zabad.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 37, 'Zabad became the father of Ephlal, and Ephlal of Obed.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 38, 'Obed became the father of Jehu, and Jehu of Azariah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 39, 'Azariah became the father of Helez, and Helez of Eleasah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 40, 'Eleasah became the father of Sismai, and Sismai of Shallum.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 41, 'Shallum became the father of Jekamiah, and Jekamiah of Elishama.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 42, 'The sons of Caleb brother of Jerahmeel: Mesha his firstborn, who was father of Ziph. The sons of Mareshah father of Hebron.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 43, 'The sons of Hebron: Korah, Tappuah, Rekem, and Shema.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 44, 'Shema became father of Raham, father of Jorkeam; and Rekem became the father of Shammai.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 45, 'The son of Shammai: Maon; and Maon was the father of Beth-zur.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 46, 'Ephah also, Caleb"s concubine, bore Haran, Moza, and Gazez; and Haran became the father of Gazez.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 47, 'The sons of Jahdai: Regem, Jotham, Geshan, Pelet, Ephah, and Shaaph.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 48, 'Maacah, Caleb"s concubine, bore Sheber and Tirhanah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 49, 'She also bore Shaaph father of Madmannah, Sheva father of Machbenah and father of Gibea; and the daughter of Caleb was Achsah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 2, 50, 'These were the descendants of Caleb.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 3, 1, 'These are the sons of David who were born to him in Hebron: the firstborn Amnon, by Ahinoam the Jezreelite; the second Daniel, by Abigail the Carmelite;', 'en', 'NRSV-CE', 'Descendants of David and Solomon'),
(13, '1 Taw', '1 Chronicles', 3, 2, 'the third Absalom, son of Maacah, daughter of King Talmai of Geshur; the fourth Adonijah, son of Haggith;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 3, 'the fifth Shephatiah, by Abital; the sixth Ithream, by his wife Eglah;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 4, 'six were born to him in Hebron, where he reigned for seven years and six months. And he reigned thirty-three years in Jerusalem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 5, 'These were born to him in Jerusalem: Shimea, Shobab, Nathan, and Solomon, four by Bath-shua, daughter of Ammiel;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 6, 'then Ibhar, Elishama, Eliphelet,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 7, 'Nogah, Nepheg, Japhia,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 8, 'Elishama, Eliada, and Eliphelet, nine.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 9, 'All these were David"s sons, besides the sons of the concubines; and Tamar was their sister.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 10, 'The descendants of Solomon: Rehoboam, Abijah his son, Asa his son, Jehoshaphat his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 11, 'Joram his son, Ahaziah his son, Joash his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 12, 'Amaziah his son, Azariah his son, Jotham his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 13, 'Ahaz his son, Hezekiah his son, Manasseh his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 14, 'Amon his son, Josiah his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 15, 'The sons of Josiah: Johanan the firstborn, the second Jehoiakim, the third Zedekiah, the fourth Shallum.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 16, 'The descendants of Jehoiakim: Jeconiah his son, Zedekiah his son;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 17, 'and the sons of Jeconiah, the captive: Shealtiel his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 18, 'Malchiram, Pedaiah, Shenazzar, Jekamiah, Hoshama, and Nedabiah;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 19, 'The sons of Pedaiah: Zerubbabel and Shimei; and the sons of Zerubbabel: Meshullam and Hananiah, and Shelomith was their sister;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 20, 'and Hashubah, Ohel, Berechiah, Hasadiah, and Jushab-hesed, five.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 21, 'The sons of Hananiah: Pelatiah and Jeshaiah, his son Rephaiah, his son Arnan, his son Obadiah, his son Shecaniah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 22, 'The son of Shecaniah: Shemaiah. And the sons of Shemaiah: Hattush, Igal, Bariah, Neariah, and Shaphat, six.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 23, 'The sons of Neariah: Elioenai, Hizkiah, and Azrikam, three.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 3, 24, 'The sons of Elioenai: Hodaviah, Eliashib, Pelaiah, Akkub, Johanan, Delaiah, and Anani, seven.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 4, 1, 'The sons of Judah: Perez, Hezron, Carmi, Hur, and Shobal.', 'en', 'NRSV-CE', 'Descendants of Judah'),
(13, '1 Taw', '1 Chronicles', 4, 2, 'Reaiah son of Shobal became the father of Jahath, and Jahath became the father of Ahumai and Lahad. These were the families of the Zorathites.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 3, 'These were the sons of Etam: Jezreel, Ishma, and Idbash; and the name of their sister was Hazzelelponi,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 4, 'and Penuel was the father of Gedor, and Ezer the father of Hushah. These were the sons of Hur, the firstborn of Ephrathah, the father of Bethlehem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 5, 'Ashhur father of Tekoa had two wives, Helah and Naarah;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 6, 'Naarah bore him Ahuzzam, Hepher, Temeni, and Haahashtari. These were the sons of Naarah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 7, 'The sons of Helah: Zereth, Izhar, and Ethnan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 8, 'Koz became the father of Anub, Zobebah, and the families of Aharhel son of Harum.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 9, 'Jabez was honored more than his brothers; and his mother named him Jabez, saying, "Because I bore him in pain."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 10, 'Jabez called on the God of Israel, saying, "Oh that you would bless me and enlarge my border, and that your hand might be with me, and that you would keep me from hurt and harm!" And God granted what he asked.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 11, 'Chelub the brother of Shuhah became the father of Mehir, who was the father of Eshton.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 12, 'Eshton became the father of Beth-rapha, Paseah, and Tehinnah the father of Ir-nahash. These are the men of Recah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 13, 'The sons of Kenaz: Othniel and Seraiah; and the sons of Othniel: Hathath and Meonothai.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 14, 'Meonothai became the father of Ophrah; and Seraiah became the father of Joab father of Ge-harashim, so-called because they were artisans.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 15, 'The sons of Caleb son of Jephunneh: Iru, Elah, and Naam; and the son of Elah: Kenaz.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 16, 'The sons of Jehallelel: Ziph, Ziphah, Tiria, and Asarel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 17, 'The sons of Ezrah: Jether, Mered, Epher, and Jalon. These are the sons of Bithiah, daughter of Pharaoh, whom Mered married; and she conceived and bore Miriam, Shammai, and Ishbah father of Eshtemoa.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 18, 'And his Judean wife bore Jered father of Gedor, Heber father of Soco, and Jekuthiel father of Zanoah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 19, 'The sons of the wife of Hodiah, the sister of Naham, were the fathers of Keilah the Garmite and Eshtemoa the Maacathite.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 20, 'The sons of Shimon: Amnon, Rinnah, Ben-hanan, and Tilon. The sons of Ishi: Zoheth and Ben-zoheth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 21, 'The sons of Shelah son of Judah: Er father of Lecah, Laadah father of Mareshah, and the families of the guild of linen workers at Beth-ashbea;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 22, 'and Jokim, and the men of Cozeba, and Joash, and Saraph, who married into Moab but returned to Lehem (now the records are ancient).', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 23, 'These were the potters and inhabitants of Netaim and Gederah; they lived there with the king in his service.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 24, 'The sons of Simeon: Nemuel, Jamin, Jarib, Zerah, Shaul;', 'en', 'NRSV-CE', 'Descendants of Simeon'),
(13, '1 Taw', '1 Chronicles', 4, 25, 'Shallum was his son, Mibsam his son, Mishma his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 26, 'The sons of Mishma: Hammuel his son, Zaccur his son, Shimei his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 27, 'Shimei had sixteen sons and six daughters; but his brothers did not have many children, nor did all their family multiply like the Judeans.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 28, 'They lived in Beer-sheba, Moladah, Hazar-shual,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 29, 'Bilhah, Ezem, Tolad,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 30, 'Bethuel, Hormah, Ziklag,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 31, 'Beth-marcaboth, Hazar-susim, Beth-biri, and Shaaraim. These were their towns until David became king.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 32, 'And their villages were Etam, Ain, Rimmon, Tochen, and Ashan, five towns,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 33, 'along with all their villages that were around these towns as far as Baal. These were their settlements. And they kept a genealogical record.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 34, 'Meshobab, Jamlech, Joshah son of Amaziah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 35, 'Joel, Jehu son of Joshibiah son of Seraiah son of Asiel,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 36, 'Elioenai, Jaakobah, Jeshohaiah, Asaiah, Adiel, Jesimiel, Benaiah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 37, 'Ziza son of Shiphi son of Allon son of Jedaiah son of Shimri son of Shemaiah--', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 38, 'these mentioned by name were leaders in their families, and their clans increased greatly.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 39, 'They journeyed to the entrance of Gedor, to the east side of the valley, to seek pasture for their flocks,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 40, 'where they found rich, good pasture, and the land was very broad, quiet, and peaceful; for the former inhabitants there belonged to Ham.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 41, 'These, registered by name, came in the days of King Hezekiah of Judah, and attacked their tents and the Meunim who were found there, and exterminated them to this day, and settled in their place, because there was pasture there for their flocks.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 42, 'And some of them, five hundred men of the Simeonites, went to Mount Seir, having as their leaders Pelatiah, Neariah, Rephaiah, and Uzziel, sons of Ishi;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 4, 43, 'they destroyed the remnant of the Amalekites that had escaped, and they have lived there to this day.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 5, 1, 'The sons of Reuben the firstborn of Israel. (He was the firstborn, but because he defiled his father"s bed his birthright was given to the sons of Joseph son of Israel, so that he is not enrolled in the genealogy according to the birthright;', 'en', 'NRSV-CE', 'Descendants of Reuben'),
(13, '1 Taw', '1 Chronicles', 5, 2, 'though Judah became prominent among his brothers and a ruler came from him, yet the birthright belonged to Joseph.)', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 3, 'The sons of Reuben, the firstborn of Israel: Hanoch, Pallu, Hezron, and Carmi.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 4, 'The sons of Joel: Shemaiah his son, Gog his son, Shimei his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 5, 'Micah his son, Reaiah his son, Baal his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 6, 'Beerah his son, whom King Tilgath-pilneser of Assyria carried away into exile; he was a chieftain of the Reubenites.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 7, 'And his kindred by their families, when the genealogy of their generations was reckoned: the chief, Jeiel, and Zechariah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 8, 'and Bela son of Azaz, son of Shema, son of Joel, who lived in Aroer, as far as Nebo and Baal-meon.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 9, 'He also lived to the east as far as the beginning of the desert this side of the Euphrates, because their cattle had multiplied in the land of Gilead.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 10, 'And in the days of Saul they made war on the Hagrites, who fell by their hand; and they lived in their tents throughout all the region east of Gilead.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 11, 'The sons of Gad lived beside them in the land of Bashan as far as Salecah:', 'en', 'NRSV-CE', 'Descendants of Gad'),
(13, '1 Taw', '1 Chronicles', 5, 12, 'Joel the chief, Shapham the second, Janai, and Shaphat in Bashan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 13, 'And their kindred according to their clans: Michael, Meshullam, Sheba, Jorai, Jacan, Zia, and Eber, seven.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 14, 'These were the sons of Abihail son of Huri, son of Jaroah, son of Gilead, son of Michael, son of Jeshishai, son of Jahdo, son of Buz;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 15, 'Ahi son of Abdiel, son of Guni, was chief in their clan;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 16, 'and they lived in Gilead, in Bashan and in its towns, and in all the pasture lands of Sharon to their limits.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 17, 'All of these were enrolled by genealogies in the days of King Jotham of Judah, and in the days of King Jeroboam of Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 18, 'The Reubenites, the Gadites, and the half-tribe of Manasseh had valiant warriors, who carried shield and sword, and drew the bow, expert in war, forty-four thousand seven hundred sixty, ready for service.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 19, 'They made war on the Hagrites, Jetur, Naphish, and Nodab;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 20, 'and when they received help against them, the Hagrites and all who were with them were given into their hands, for they cried to God in the battle, and he granted their entreaty because they trusted in him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 21, 'They captured their livestock: fifty thousand of their camels, two hundred fifty thousand sheep, two thousand donkeys, and one hundred thousand captives.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 22, 'Many fell slain, because the war was of God. And they lived in their territory until the exile.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 23, 'The members of the half-tribe of Manasseh lived in the land; they were very numerous from Bashan to Baal-hermon, Senir, and Mount Hermon.', 'en', 'NRSV-CE', 'The Half-Tribe of Manasseh'),
(13, '1 Taw', '1 Chronicles', 5, 24, 'These were the heads of their clans: Epher, Ishi, Eliel, Azriel, Jeremiah, Hodaviah, and Jahdiel, mighty warriors, famous men, heads of their clans.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 25, 'But they transgressed against the God of their ancestors, and prostituted themselves to the gods of the peoples of the land, whom God had destroyed before them.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 5, 26, 'So the God of Israel stirred up the spirit of King Pul of Assyria, the spirit of King Tilgath-pilneser of Assyria, and he carried them away, namely, the Reubenites, the Gadites, and the half-tribe of Manasseh, and brought them to Halah, Habor, Hara, and the river Gozan, to this day.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 6, 1, 'The sons of Levi: Gershom, Kohath, and Merari.', 'en', 'NRSV-CE', 'Descendants of Levi'),
(13, '1 Taw', '1 Chronicles', 6, 2, 'The sons of Kohath: Amram, Izhar, Hebron, and Uzziel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 3, 'The children of Amram: Aaron, Moses, and Miriam. The sons of Aaron: Nadab, Abihu, Eleazar, and Ithamar.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 4, 'Eleazar became the father of Phinehas, Phinehas of Abishua,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 5, 'Abishua of Bukki, Bukki of Uzzi,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 6, 'Uzzi of Zerahiah, Zerahiah of Meraioth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 7, 'Meraioth of Amariah, Amariah of Ahitub,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 8, 'Ahitub of Zadok, Zadok of Ahimaaz,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 9, 'Ahimaaz of Azariah, Azariah of Johanan,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 10, 'and Johanan of Azariah (it was he who served as priest in the house that Solomon built in Jerusalem).', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 11, 'Azariah became the father of Amariah, Amariah of Ahitub,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 12, 'Ahitub of Zadok, Zadok of Shallum,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 13, 'Shallum of Hilkiah, Hilkiah of Azariah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 14, 'Azariah of Seraiah, Seraiah of Jehozadak;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 15, 'and Jehozadak went into exile when the LORD sent Judah and Jerusalem into exile by the hand of Nebuchadnezzar.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 16, 'The sons of Levi: Gershom, Kohath, and Merari.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 17, 'These are the names of the sons of Gershom: Libni and Shimei.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 18, 'The sons of Kohath: Amram, Izhar, Hebron, and Uzziel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 19, 'The sons of Merari: Mahli and Mushi. These are the clans of the Levites according to their ancestry.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 20, 'Of Gershom: Libni his son, Jahath his son, Zimmah his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 21, 'Joah his son, Iddo his son, Zerah his son, Jeatherai his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 22, 'The sons of Kohath: Amminadab his son, Korah his son, Assir his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 23, 'Elkanah his son, Ebiasaph his son, Assir his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 24, 'Tahath his son, Uriel his son, Uzziah his son, and Shaul his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 25, 'The sons of Elkanah: Amasai and Ahimoth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 26, 'Elkanah his son, Zophai his son, Nahath his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 27, 'Eliab his son, Jeroham his son, Elkanah his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 28, 'The sons of Samuel: Joel his firstborn, the second Abijah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 29, 'The sons of Merari: Mahli, Libni his son, Shimei his son, Uzzah his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 30, 'Shimea his son, Haggiah his son, and Asaiah his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 31, 'These are the men whom David put in charge of the service of song in the house of the LORD, after the ark came to rest there.', 'en', 'NRSV-CE', 'Musicians Appointed by David'),
(13, '1 Taw', '1 Chronicles', 6, 32, 'They ministered with song before the tabernacle of the tent of meeting, until Solomon had built the house of the LORD in Jerusalem; and they performed their service in due order.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 33, 'These are the men who served; and their sons were: Of the Kohathites: Heman, the singer, son of Joel, son of Samuel,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 34, 'son of Elkanah, son of Jeroham, son of Eliel, son of Toah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 35, 'son of Zuph, son of Elkanah, son of Mahath, son of Amasai,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 36, 'son of Elkanah, son of Joel, son of Azariah, son of Zephaniah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 37, 'son of Tahath, son of Assir, son of Ebiasaph, son of Korah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 38, 'son of Izhar, son of Kohath, son of Levi, son of Israel;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 39, 'and his brother Asaph, who stood on his right, namely, Asaph son of Berechiah, son of Shimea,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 40, 'son of Michael, son of Baaseiah, son of Malchijah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 41, 'son of Ethni, son of Zerah, son of Adaiah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 42, 'son of Ethan, son of Zimmah, son of Shimei,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 43, 'son of Jahath, son of Gershom, son of Levi.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 44, 'On the left were their kindred the sons of Merari: Ethan son of Kishi, son of Abdi, son of Malluch,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 45, 'son of Hashabiah, son of Amaziah, son of Hilkiah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 46, 'son of Amzi, son of Bani, son of Shemer,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 47, 'son of Mahli, son of Mushi, son of Merari, son of Levi;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 48, 'and their kindred the Levites were appointed for all the service of the tabernacle of the house of God.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 49, 'But Aaron and his sons made offerings on the altar of burnt offering and on the altar of incense, doing all the work of the most holy place, to make atonement for Israel, according to all that Moses the servant of God had commanded.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 50, 'These are the sons of Aaron: Eleazar his son, Phinehas his son, Abishua his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 51, 'Bukki his son, Uzzi his son, Zerahiah his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 52, 'Meraioth his son, Amariah his son, Ahitub his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 53, 'Zadok his son, Ahimaaz his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 54, 'These are their dwelling places according to their settlements within their borders: to the sons of Aaron of the families of Kohathites--for the lot fell to them first--', 'en', 'NRSV-CE', 'Settlements of the Levites'),
(13, '1 Taw', '1 Chronicles', 6, 55, 'to them they gave Hebron in the land of Judah and its surrounding pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 56, 'but the fields of the city and its villages they gave to Caleb son of Jephunneh.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 57, 'To the sons of Aaron they gave the cities of refuge: Hebron, Libnah with its pasture lands, Jattir, Eshtemoa with its pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 58, 'Hilen with its pasture lands, Debir with its pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 59, 'Ashan with its pasture lands, and Beth-shemesh with its pasture lands.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 60, 'From the tribe of Benjamin, Geba with its pasture lands, Alemeth with its pasture lands, and Anathoth with its pasture lands. All their towns throughout their families were thirteen.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 61, 'To the rest of the Kohathites were given by lot out of the family of the tribe, out of the half-tribe, the half of Manasseh, ten towns.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 62, 'To the Gershomites according to their families were allotted thirteen towns out of the tribes of Issachar, Asher, Naphtali, and Manasseh in Bashan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 63, 'To the Merarites according to their families were allotted twelve towns out of the tribes of Reuben, Gad, and Zebulun.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 64, 'So the people of Israel gave the Levites the towns with their pasture lands.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 65, 'They also gave them by lot out of the tribes of Judah, Simeon, and Benjamin these towns that are mentioned by name.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 66, 'And some of the families of the sons of Kohath had towns of their territory out of the tribe of Ephraim.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 67, 'They were given the cities of refuge: Shechem with its pasture lands in the hill country of Ephraim, Gezer with its pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 68, 'Jokmeam with its pasture lands, Beth-horon with its pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 69, 'Aijalon with its pasture lands, Gath-rimmon with its pasture lands;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 70, 'and out of the half-tribe of Manasseh, Aner with its pasture lands, and Bileam with its pasture lands, for the rest of the families of the Kohathites.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 71, 'To the Gershomites: out of the half-tribe of Manasseh: Golan in Bashan with its pasture lands and Ashtaroth with its pasture lands;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 72, 'and out of the tribe of Issachar: Kedesh with its pasture lands, Daberath with its pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 73, 'Ramoth with its pasture lands, and Anem with its pasture lands;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 74, 'out of the tribe of Asher: Mashal with its pasture lands, Abdon with its pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 75, 'Hukok with its pasture lands, and Rehob with its pasture lands;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 76, 'and out of the tribe of Naphtali: Kedesh in Galilee with its pasture lands, Hammon with its pasture lands, and Kiriathaim with its pasture lands.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 77, 'To the rest of the Merarites out of the tribe of Zebulun: Rimmono with its pasture lands, Tabor with its pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 78, 'and across the Jordan from Jericho, on the east side of the Jordan, out of the tribe of Reuben: Bezer in the steppe with its pasture lands, Jahzah with its pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 79, 'Kedemoth with its pasture lands, and Mephaath with its pasture lands;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 80, 'and out of the tribe of Gad: Ramoth in Gilead with its pasture lands, Mahanaim with its pasture lands,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 6, 81, 'Heshbon with its pasture lands, and Jazer with its pasture lands.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 7, 1, 'The sons of Issachar: Tola, Puah, Jashub, and Shimron, four.', 'en', 'NRSV-CE', 'Descendants of Issachar'),
(13, '1 Taw', '1 Chronicles', 7, 2, 'The sons of Tola: Uzzi, Rephaiah, Jeriel, Jahmai, Ibsam, and Shemuel, heads of their ancestral houses, namely of Tola, mighty warriors of their generations, their number in the days of David being twenty-two thousand six hundred.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 3, 'The son of Uzzi: Izrahiah. And the sons of Izrahiah: Michael, Obadiah, Joel, and Isshiah, five, all of them chiefs;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 4, 'and along with them, by their generations, according to their ancestral houses, were units of the fighting force, thirty-six thousand, for they had many wives and sons.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 5, 'Their kindred belonging to all the families of Issachar were in all eighty-seven thousand mighty warriors, enrolled by genealogy.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 6, 'The sons of Benjamin: Bela, Becher, and Jediael, three.', 'en', 'NRSV-CE', 'Descendants of Benjamin'),
(13, '1 Taw', '1 Chronicles', 7, 7, 'The sons of Bela: Ezbon, Uzzi, Uzziel, Jerimoth, and Iri, five, heads of ancestral houses, mighty warriors; and their enrollment by genealogies was twenty-two thousand thirty-four.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 8, 'The sons of Becher: Zemirah, Joash, Eliezer, Elioenai, Omri, Jeremoth, Abijah, Anathoth, and Alemeth. All these were the sons of Becher;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 9, 'and their enrollment by genealogies, according to their generations, as heads of their ancestral houses, mighty warriors, was twenty thousand two hundred.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 10, 'The sons of Jediael: Bilhan. And the sons of Bilhan: Jeush, Benjamin, Ehud, Chenaanah, Zethan, Tarshish, and Ahishahar.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 11, 'All these were the sons of Jediael according to the heads of their ancestral houses, mighty warriors, seventeen thousand two hundred, ready for service in war.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 12, 'And Shuppim and Huppim were the sons of Ir, Hushim the son of Aher.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 13, 'The descendants of Naphtali: Jahziel, Guni, Jezer, and Shallum, the descendants of Bilhah.', 'en', 'NRSV-CE', 'Descendants of Naphtali'),
(13, '1 Taw', '1 Chronicles', 7, 14, 'The sons of Manasseh: Asriel, whom his Aramean concubine bore; she bore Machir the father of Gilead.', 'en', 'NRSV-CE', 'Descendants of Manasseh'),
(13, '1 Taw', '1 Chronicles', 7, 15, 'And Machir took a wife for Huppim and for Shuppim. The name of his sister was Maacah. And the name of the second was Zelophehad; and Zelophehad had daughters.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 16, 'Maacah the wife of Machir bore a son, and she named him Peresh; the name of his brother was Sheresh; and his sons were Ulam and Rekem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 17, 'The son of Ulam: Bedan. These were the sons of Gilead son of Machir, son of Manasseh.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 18, 'And his sister Hammolecheth bore Ishhod, Abiezer, and Mahlah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 19, 'The sons of Shemida were Ahian, Shechem, Likhi, and Aniam.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 20, 'The sons of Ephraim: Shuthelah, and Bered his son, Tahath his son, Eleadah his son, Tahath his son,', 'en', 'NRSV-CE', 'Descendants of Ephraim'),
(13, '1 Taw', '1 Chronicles', 7, 21, 'Zabad his son, Shuthelah his son, and Ezer and Elead. Now the people of Gath, who were born in the land, killed them, because they came down to raid their cattle.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 22, 'And their father Ephraim mourned many days, and his brothers came to comfort him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 23, 'Ephraim went in to his wife, and she conceived and bore a son; and he named him Beriah, because disaster had befallen his house.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 24, 'His daughter was Sheerah, who built both Lower and Upper Beth-horon, and Uzzen-sheerah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 25, 'Rephah was his son, Resheph his son, Telah his son, Tahan his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 26, 'Ladan his son, Ammihud his son, Elishama his son,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 27, 'Nun his son, Joshua his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 28, 'Their possessions and settlements were Bethel and its towns, and eastward Naaran, and westward Gezer and its towns, Shechem and its towns, as far as Ayyah and its towns;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 29, 'also along the borders of the Manassites, Beth-shean and its towns, Taanach and its towns, Megiddo and its towns, Dor and its towns. In these lived the sons of Joseph son of Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 30, 'The sons of Asher: Imnah, Ishvah, Ishvi, Beriah, and their sister Serah.', 'en', 'NRSV-CE', 'Descendants of Asher'),
(13, '1 Taw', '1 Chronicles', 7, 31, 'The sons of Beriah: Heber and Malchiel, who was the father of Birzaith.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 32, 'Heber became the father of Japhlet, Shomer, Hotham, and their sister Shua.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 33, 'The sons of Japhlet: Pasach, Bimhal, and Ashvath. These are the sons of Japhlet.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 34, 'The sons of Shemer: Ahi, Rohgah, Hubbah, and Aram.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 35, 'The sons of Helem his brother: Zophah, Imna, Shelesh, and Amal.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 36, 'The sons of Zophah: Suah, Harnepher, Shual, Beri, Imrah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 37, 'Bezer, Hod, Shamma, Shilshah, Ithran, and Beera.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 38, 'The sons of Jether: Jephunneh, Pispa, and Ara.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 39, 'The sons of Ulla: Arah, Hanniel, and Rizia.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 7, 40, 'All of these were men of Asher, heads of ancestral houses, select mighty warriors, chief of the princes. Their number enrolled by genealogies, for service in war, was twenty-six thousand men.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 8, 1, 'Benjamin became the father of Bela his firstborn, Ashbel the second, Aharah the third,', 'en', 'NRSV-CE', 'Descendants of Benjamin'),
(13, '1 Taw', '1 Chronicles', 8, 2, 'Nohah the fourth, and Rapha the fifth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 3, 'And Bela had sons: Addar, Gera, Abihud,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 4, 'Abishua, Naaman, Ahoah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 5, 'Gera, Shephuphan, and Huram.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 6, 'These are the sons of Ehud (they were heads of ancestral houses of the inhabitants of Geba, and they were carried into exile to Manahath):', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 7, 'Naaman, Ahijah, and Gera, that is, Heglam, who became the father of Uzza and Ahihud.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 8, 'And Shaharaim had sons in the country of Moab after he had sent away his wives Hushim and Baara.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 9, 'He had sons by his wife Hodesh: Jobab, Zibia, Mesha, Malcam,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 10, 'Jeuz, Sachia, and Mirmah. These were his sons, heads of ancestral houses.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 11, 'He also had sons by Hushim: Abitub and Elpaal.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 12, 'The sons of Elpaal: Eber, Misham, and Shemed, who built Ono and Lod with its towns,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 13, 'and Beriah and Shema (they were heads of ancestral houses of the inhabitants of Aijalon, who put to flight the inhabitants of Gath);', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 14, 'and Ahio, Shashak, and Jeremoth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 15, 'Zebadiah, Arad, Eder,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 16, 'Michael, Ishpah, and Joha were sons of Beriah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 17, 'Zebadiah, Meshullam, Hizki, Heber,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 18, 'Ishmerai, Izliah, and Jobab were the sons of Elpaal.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 19, 'Jakim, Zichri, Zabdi,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 20, 'Elienai, Zillethai, Eliel,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 21, 'Adaiah, Beraiah, and Shimrath were the sons of Shimei.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 22, 'Ishpan, Eber, Eliel,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 23, 'Abdon, Zichri, Hanan,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 24, 'Hananiah, Elam, Anthothijah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 25, 'Iphdeiah, and Penuel were the sons of Shashak.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 26, 'Shamsherai, Shehariah, Athaliah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 27, 'Jaareshiah, Elijah, and Zichri were the sons of Jeroham.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 28, 'These were the heads of ancestral houses, according to their generations, chiefs. These lived in Jerusalem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 29, 'Jeiel the father of Gibeon lived in Gibeon, and the name of his wife was Maacah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 30, 'His firstborn son: Abdon, then Zur, Kish, Baal, Nadab,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 31, 'Gedor, Ahio, Zecher,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 32, 'and Mikloth, who became the father of Shimeah. Now these also lived opposite their kindred in Jerusalem, with their kindred.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 33, 'Ner became the father of Kish, Kish of Saul, Saul of Jonathan, Malchishua, Abinadab, and Esh-baal;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 34, 'and the son of Jonathan was Merib-baal; and Merib-baal became the father of Micah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 35, 'The sons of Micah: Pithon, Melech, Tarea, and Ahaz.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 36, 'Ahaz became the father of Jehoaddah; and Jehoaddah became the father of Alemeth, Azmaveth, and Zimri; Zimri became the father of Moza.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 37, 'Moza became the father of Binea; Raphah was his son, Eleasah his son, Azel his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 38, 'Azel had six sons, and these are their names: Azrikam, Bocheru, Ishmael, Sheariah, Obadiah, and Hanan; all these were the sons of Azel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 39, 'The sons of his brother Eshek: Ulam his firstborn, Jeush the second, and Eliphelet the third.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 8, 40, 'The sons of Ulam were mighty warriors, archers, having many children and grandchildren, one hundred fifty. All these were Benjaminites.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 9, 1, 'So all Israel was enrolled by genealogies; and these are written in the Book of the Kings of Israel. And Judah was taken into exile in Babylon because of their unfaithfulness.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 2, 'Now the first to live again in their possessions in their towns were Israelites, priests, Levites, and temple servants.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 3, 'And some of the people of Judah, Benjamin, Ephraim, and Manasseh lived in Jerusalem:', 'en', 'NRSV-CE', 'Inhabitants of Jerusalem after the Exile'),
(13, '1 Taw', '1 Chronicles', 9, 4, 'Uthai son of Ammihud, son of Omri, son of Imri, son of Bani, from the sons of Perez son of Judah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 5, 'And of the Shilonites: Asaiah the firstborn, and his sons.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 6, 'Of the sons of Zerah: Jeuel and their kin, six hundred ninety.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 7, 'Of the Benjaminites: Sallu son of Meshullam, son of Hodaviah, son of Hassenuah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 8, 'Ibneiah son of Jeroham, Elah son of Uzzi, son of Michri, and Meshullam son of Shephatiah, son of Reuel, son of Ibnijah;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 9, 'and their kindred according to their generations, nine hundred fifty-six. All these were heads of families according to their ancestral houses.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 10, 'Of the priests: Jedaiah, Jehoiarib, Jachin,', 'en', 'NRSV-CE', 'Priestly Families'),
(13, '1 Taw', '1 Chronicles', 9, 11, 'and Azariah son of Hilkiah, son of Meshullam, son of Zadok, son of Meraioth, son of Ahitub, the chief officer of the house of God;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 12, 'and Adaiah son of Jeroham, son of Pashhur, son of Malchijah, and Maasai son of Adiel, son of Jahzerah, son of Meshullam, son of Meshillemith, son of Immer;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 13, 'besides their kindred, heads of their ancestral houses, one thousand seven hundred sixty, qualified for the work of the service of the house of God.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 14, 'Of the Levites: Shemaiah son of Hasshub, son of Azrikam, son of Hashabiah, of the sons of Merari;', 'en', 'NRSV-CE', 'Levitical Families'),
(13, '1 Taw', '1 Chronicles', 9, 15, 'and Bakbakkar, Heresh, Galal, and Mattaniah son of Mica, son of Zichri, son of Asaph;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 16, 'and Obadiah son of Shemaiah, son of Galal, son of Jeduthun, and Berechiah son of Asa, son of Elkanah, who lived in the villages of the Netophathites.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 17, 'The gatekeepers were: Shallum, Akkub, Talmon, Ahiman; and their kindred Shallum was the chief,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 18, 'stationed previously in the king"s gate on the east side. These were the gatekeepers of the camp of the Levites.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 19, 'Shallum son of Kore, son of Ebiasaph, son of Korah, and his kindred of his ancestral house, the Korahites, were in charge of the work of the service, guardians of the thresholds of the tent, as their ancestors had been in charge of the camp of the LORD, guardians of the entrance.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 20, 'And Phinehas son of Eleazar was chief over them in former times; the LORD was with him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 21, 'Zechariah son of Meshelemiah was gatekeeper at the entrance of the tent of meeting.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 22, 'All these, who were chosen as gatekeepers at the thresholds, were two hundred twelve. They were enrolled by genealogies in their villages. David and the seer Samuel established them in their office of trust.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 23, 'So they and their descendants were in charge of the gates of the house of the LORD, that is, the house of the tent, as guards.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 24, 'The gatekeepers were on the four sides, east, west, north, and south;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 25, 'and their kindred who were in their villages were obliged to come in every seven days, in turn, to be with them;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 26, 'for the four chief gatekeepers, who were Levites, were in charge of the chambers and the treasures of the house of God.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 27, 'And they would spend the night near the house of God; for on them lay the duty of watching, and they had charge of opening it every morning.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 28, 'Some of them had charge of the utensils of service, for they were required to count them when they were brought in and taken out.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 29, 'Others of them were appointed over the furniture, and over all the holy utensils, also over the choice flour, the wine, the oil, the incense, and the spices.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 30, 'Others, of the sons of the priests, prepared the mixing of the spices,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 31, 'and Mattithiah, one of the Levites, the firstborn of Shallum the Korahite, was in charge of making the flat cakes.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 32, 'Also some of their kindred of the Kohathites had charge of the rows of bread, to prepare them for each sabbath.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 33, 'Now these are the singers, the heads of ancestral houses of the Levites, living in the chambers of the temple free from other service, for they were on duty day and night.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 34, 'These were heads of ancestral houses of the Levites, according to their generations; these leaders lived in Jerusalem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 35, 'In Gibeon lived the father of Gibeon, Jeiel, and the name of his wife was Maacah.', 'en', 'NRSV-CE', 'The Family of King Saul'),
(13, '1 Taw', '1 Chronicles', 9, 36, 'His firstborn son was Abdon, then Zur, Kish, Baal, Ner, Nadab,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 37, 'Gedor, Ahio, Zechariah, and Mikloth;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 38, 'and Mikloth became the father of Shimeam; and these also lived opposite their kindred in Jerusalem, with their kindred.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 39, 'Ner became the father of Kish, Kish of Saul, Saul of Jonathan, Malchishua, Abinadab, and Esh-baal;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 40, 'and the son of Jonathan was Merib-baal; and Merib-baal became the father of Micah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 41, 'The sons of Micah: Pithon, Melech, Tahrea, and Ahaz;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 42, 'and Ahaz became the father of Jarah, and Jarah of Alemeth, Azmaveth, and Zimri; and Zimri became the father of Moza.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 43, 'Moza became the father of Binea; and Rephaiah was his son, Eleasah his son, Azel his son.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 9, 44, 'Azel had six sons, and these are their names: Azrikam, Bocheru, Ishmael, Sheariah, Obadiah, and Hanan; these were the sons of Azel.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 10, 1, 'Now the Philistines fought against Israel; and the men of Israel fled before the Philistines, and fell slain on Mount Gilboa.', 'en', 'NRSV-CE', 'Death of Saul and His Sons'),
(13, '1 Taw', '1 Chronicles', 10, 2, 'The Philistines overtook Saul and his sons; and the Philistines killed Jonathan and Abinadab and Malchishua, sons of Saul.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 3, 'The battle pressed hard on Saul; and the archers found him, and he was wounded by the archers.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 4, 'Then Saul said to his armor-bearer, "Draw your sword, and thrust me through with it, so that these uncircumcised may not come and make sport of me." But his armor-bearer was unwilling, for he was terrified. So Saul took his own sword and fell on it.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 5, 'When his armor-bearer saw that Saul was dead, he also fell on his sword and died.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 6, 'Thus Saul died; he and his three sons and all his house died together.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 7, 'When all the men of Israel who were in the valley saw that the army had fled and that Saul and his sons were dead, they abandoned their towns and fled; and the Philistines came and occupied them.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 8, 'The next day when the Philistines came to strip the dead, they found Saul and his sons fallen on Mount Gilboa.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 9, 'They stripped him and took his head and his armor, and sent messengers throughout the land of the Philistines to carry the good news to their idols and to the people.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 10, 'They put his armor in the temple of their gods, and fastened his head in the temple of Dagon.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 11, 'But when all Jabesh-gilead heard everything that the Philistines had done to Saul,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 12, 'all the valiant warriors got up and took away the body of Saul and the bodies of his sons, and brought them to Jabesh. Then they buried their bones under the oak in Jabesh, and fasted seven days.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 13, 'So Saul died for his unfaithfulness; he was unfaithful to the LORD in that he did not keep the command of the LORD; moreover, he had consulted a medium, seeking guidance,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 10, 14, 'and did not seek guidance from the LORD. Therefore the LORD put him to death and turned the kingdom over to David son of Jesse.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 11, 1, 'Then all Israel gathered together to David at Hebron and said, "See, we are your bone and flesh.', 'en', 'NRSV-CE', 'David Anointed King of All Israel'),
(13, '1 Taw', '1 Chronicles', 11, 2, 'For some time now, even while Saul was king, it was you who commanded the army of Israel. The LORD your God said to you: It is you who shall be shepherd of my people Israel, you who shall be ruler over my people Israel."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 3, 'So all the elders of Israel came to the king at Hebron, and David made a covenant with them at Hebron before the LORD. And they anointed David king over Israel, according to the word of the LORD by Samuel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 4, 'David and all Israel marched to Jerusalem, that is Jebus, where the Jebusites were, the inhabitants of the land.', 'en', 'NRSV-CE', 'Jerusalem Captured'),
(13, '1 Taw', '1 Chronicles', 11, 5, 'The inhabitants of Jebus said to David, "You will not come in here." Nevertheless David took the stronghold of Zion, now the city of David.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 6, 'David had said, "Whoever attacks the Jebusites first shall be chief and commander." And Joab son of Zeruiah went up first, so he became chief.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 7, 'David resided in the stronghold; therefore it was called the city of David.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 8, 'He built the city all around, from the Millo in complete circuit; and Joab repaired the rest of the city.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 9, 'And David became greater and greater, for the LORD of hosts was with him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 10, 'Now these are the chiefs of David"s warriors, who gave him strong support in his kingdom, together with all Israel, to make him king, according to the word of the LORD concerning Israel.', 'en', 'NRSV-CE', 'David"s Mighty Men and Their Exploits'),
(13, '1 Taw', '1 Chronicles', 11, 11, 'This is an account of David"s mighty warriors: Jashobeam, son of Hachmoni, was chief of the Three; he wielded his spear against three hundred whom he killed at one time.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 12, 'And next to him among the three warriors was Eleazar son of Dodo, the Ahohite.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 13, 'He was with David at Pas-dammim when the Philistines were gathered there for battle. There was a plot of ground full of barley. Now the people had fled from the Philistines,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 14, 'but he and David took their stand in the middle of the plot, defended it, and killed the Philistines; and the LORD saved them by a great victory.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 15, 'Three of the thirty chiefs went down to the rock to David at the cave of Adullam, while the army of Philistines was encamped in the valley of Rephaim.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 16, 'David was then in the stronghold; and the garrison of the Philistines was then at Bethlehem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 17, 'David said longingly, "O that someone would give me water to drink from the well of Bethlehem that is by the gate!"', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 18, 'Then the Three broke through the camp of the Philistines, and drew water from the well of Bethlehem that was by the gate, and they brought it to David. But David would not drink of it; he poured it out to the LORD,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 19, 'and said, "My God forbid that I should do this. Can I drink the blood of these men? For at the risk of their lives they brought it." Therefore he would not drink it. The three warriors did these things.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 20, 'Now Abishai, the brother of Joab, was chief of the Thirty. With his spear he fought against three hundred and killed them, and won a name beside the Three.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 21, 'He was the most renowned of the Thirty, and became their commander; but he did not attain to the Three.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 22, 'Benaiah son of Jehoiada was a valiant man of Kabzeel, a doer of great deeds; he struck down two sons of Ariel of Moab. He also went down and killed a lion in a pit on a day when snow had fallen.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 23, 'And he killed an Egyptian, a man of great stature, five cubits tall. The Egyptian had in his hand a spear like a weaver"s beam; but Benaiah went against him with a staff, snatched the spear out of the Egyptian"s hand, and killed him with his own spear.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 24, 'Such were the things Benaiah son of Jehoiada did, and he won a name beside the three warriors.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 25, 'He was renowned among the Thirty, but he did not attain to the Three. And David put him in charge of his bodyguard.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 26, 'The warriors of the armies were Asahel brother of Joab, Elhanan son of Dodo of Bethlehem,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 27, 'Shammoth of Harod, Helez the Pelonite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 28, 'Ira son of Ikkesh of Tekoa, Abiezer of Anathoth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 29, 'Sibbecai the Hushathite, Ilai the Ahohite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 30, 'Maharai of Netophah, Heled son of Baanah of Netophah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 31, 'Ithai son of Ribai of Gibeah of the Benjaminites, Benaiah of Pirathon,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 32, 'Hurai of the wadis of Gaash, Abiel the Arbathite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 33, 'Azmaveth of Baharum, Eliahba of Shaalbon,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 34, 'Hashem the Gizonite, Jonathan son of Shagee the Hararite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 35, 'Ahiam son of Sachar the Hararite, Eliphal son of Ur,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 36, 'Hepher the Mecherathite, Ahijah the Pelonite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 37, 'Hezro of Carmel, Naarai son of Ezbai,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 38, 'Joel the brother of Nathan, Mibhar son of Hagri,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 39, 'Zelek the Ammonite, Naharai of Beeroth, the armor-bearer of Joab son of Zeruiah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 40, 'Ira the Ithrite, Gareb the Ithrite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 41, 'Uriah the Hittite, Zabad son of Ahlai,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 42, 'Adina son of Shiza the Reubenite, a leader of the Reubenites, and thirty with him,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 43, 'Hanan son of Maacah, and Joshaphat the Mithnite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 44, 'Uzzia the Ashterathite, Shama and Jeiel sons of Hotham the Aroerite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 45, 'Jediael son of Shimri, and his brother Joha the Tizite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 46, 'Eliel the Mahavite, and Jeribai and Joshaviah sons of Elnaam, and Ithmah the Moabite,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 11, 47, 'Eliel, and Obed, and Jaasiel the Mezobaite.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 12, 1, 'The following are those who came to David at Ziklag, while he could not move about freely because of Saul son of Kish; they were among the mighty warriors who helped him in war.', 'en', 'NRSV-CE', 'David"s Followers in the Wilderness'),
(13, '1 Taw', '1 Chronicles', 12, 2, 'They were archers, and could shoot arrows and sling stones with either the right hand or the left; they were Benjaminites, Saul"s kindred.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 3, 'The chief was Ahiezer, then Joash, both sons of Shemaah of Gibeah; also Jeziel and Pelet sons of Azmaveth; Beracah, Jehu of Anathoth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 4, 'Ishmaiah of Gibeon, a warrior among the Thirty and a leader over the Thirty; Jeremiah, Jahaziel, Johanan, Jozabad of Gederah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 5, 'Eluzai, Jerimoth, Bealiah, Shemariah, Shephatiah the Haruphite;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 6, 'Elkanah, Isshiah, Azarel, Joezer, and Jashobeam, the Korahites;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 7, 'and Joelah and Zebadiah, sons of Jeroham of Gedor.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 8, 'From the Gadites there went over to David at the stronghold in the wilderness mighty and experienced warriors, expert with shield and spear, whose faces were like the faces of lions, and who were swift as gazelles on the mountains:', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 9, 'Ezer the chief, Obadiah second, Eliab third,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 10, 'Mishmannah fourth, Jeremiah fifth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 11, 'Attai sixth, Eliel seventh,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 12, 'Johanan eighth, Elzabad ninth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 13, 'Jeremiah tenth, Machbannai eleventh.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 14, 'These Gadites were officers of the army, the least equal to a hundred and the greatest to a thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 15, 'These are the men who crossed the Jordan in the first month, when it was overflowing all its banks, and put to flight all those in the valleys, to the east and to the west.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 16, 'Some Benjaminites and Judahites came to the stronghold to David.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 17, 'David went out to meet them and said to them, "If you have come to me in friendship, to help me, then my heart will be knit to you; but if you have come to betray me to my adversaries, though my hands have done no wrong, then may the God of our ancestors see and give judgment."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 12, 18, 'Then the spirit came upon Amasai, chief of the Thirty, and he said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 13, 1, 'David consulted with the commanders of the thousands and of the hundreds, with every leader.', 'en', 'NRSV-CE', 'The Ark Brought from Kiriath-jearim'),
(13, '1 Taw', '1 Chronicles', 13, 2, 'David said to the whole assembly of Israel, "If it seems good to you, and if it is the will of the LORD our God, let us send abroad to our kindred who remain in all the land of Israel, including the priests and Levites in the cities that have pasture lands, that they may come together to us.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 3, 'Then let us bring again the ark of our God to us; for we did not turn to it in the days of Saul."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 4, 'The whole assembly agreed to do so, for the thing pleased all the people.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 5, 'So David assembled all Israel from the Shihor of Egypt to Lebo-hamath, to bring the ark of God from Kiriath-jearim.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 6, 'And David and all Israel went up to Baalah, that is, to Kiriath-jearim, which belongs to Judah, to bring up from there the ark of God, the LORD, who is enthroned on the cherubim, which is called by his name.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 7, 'They carried the ark of God on a new cart, from the house of Abinadab, and Uzzah and Ahio were driving the cart.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 8, 'David and all Israel were dancing before God with all their might, with song and lyres and harps and tambourines and cymbals and trumpets.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 9, 'When they came to the threshing floor of Chidon, Uzzah put out his hand to hold the ark, for the oxen shook it.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 10, 'The anger of the LORD was kindled against Uzzah; he struck him down because he put out his hand to the ark; and he died there before God.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 11, 'David was angry because the LORD had burst out against Uzzah; so that place is called Perez-uzzah to this day.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 12, 'David was afraid of God that day; he said, "How can I bring the ark of God into my care?"', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 13, 'So David did not take the ark into his care into the city of David; he took it instead to the house of Obed-edom the Gittite.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 13, 14, 'The ark of God remained with the household of Obed-edom in his house three months, and the LORD blessed the household of Obed-edom and all that he had.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 14, 1, 'King Hiram of Tyre sent messengers to David, along with cedar logs, and masons and carpenters to build a house for him.', 'en', 'NRSV-CE', 'David Established at Jerusalem'),
(13, '1 Taw', '1 Chronicles', 14, 2, 'David then perceived that the LORD had established him as king over Israel, and that his kingdom was highly exalted for the sake of his people Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 3, 'David took more wives in Jerusalem, and David became the father of more sons and daughters.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 4, 'These are the names of the children whom he had in Jerusalem: Shammua, Shobab, and Nathan; Solomon,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 5, 'Ibhar, Elishua, and Elpelet;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 6, 'Nogah, Nepheg, and Japhia;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 7, 'Elishama, Beeliada, and Eliphelet.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 8, 'When the Philistines heard that David had been anointed king over all Israel, all the Philistines went up in search of David; and David heard of it and went out against them.', 'en', 'NRSV-CE', 'Defeat of the Philistines'),
(13, '1 Taw', '1 Chronicles', 14, 9, 'Now the Philistines had come and made a raid in the valley of Rephaim.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 10, 'David inquired of God, "Shall I go up against the Philistines? Will you give them into my hand?" The LORD said to him, "Go up, and I will give them into your hand."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 11, 'So he went up to Baal-perazim, and David defeated them there. David said, "God has burst out against my enemies by my hand, like a bursting flood." Therefore that place is called Baal-perazim.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 12, 'They abandoned their gods there, and at David"s command they were burned.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 13, 'Once again the Philistines made a raid in the valley.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 14, 'When David again inquired of God, God said to him, "You shall not go up after them; go around and come on them opposite the balsam trees.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 15, 'When you hear the sound of marching in the tops of the balsam trees, then go out to battle; for God has gone out before you to strike down the army of the Philistines."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 16, 'David did as God had commanded him, and they struck down the Philistine army from Gibeon to Gezer.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 14, 17, 'The fame of David went out into all lands, and the LORD brought the fear of him on all nations.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 15, 1, 'David built houses for himself in the city of David, and he prepared a place for the ark of God and pitched a tent for it.', 'en', 'NRSV-CE', 'The Ark Brought to Jerusalem'),
(13, '1 Taw', '1 Chronicles', 15, 2, 'Then David commanded that no one but the Levites were to carry the ark of God, for the LORD had chosen them to carry the ark of the LORD and to minister to him forever.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 3, 'David assembled all Israel in Jerusalem to bring up the ark of the LORD to its place, which he had prepared for it.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 4, 'Then David gathered together the descendants of Aaron and the Levites:', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 5, 'of the sons of Kohath, Uriel the chief, with one hundred twenty of his kindred;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 6, 'of the sons of Merari, Asaiah the chief, with two hundred twenty of his kindred;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 7, 'of the sons of Gershom, Joel the chief, with one hundred thirty of his kindred;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 8, 'of the sons of Elizaphan, Shemaiah the chief, with two hundred of his kindred;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 9, 'of the sons of Hebron, Eliel the chief, with eighty of his kindred;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 10, 'of the sons of Uzziel, Amminadab the chief, with one hundred twelve of his kindred.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 11, 'David summoned the priests Zadok and Abiathar, and the Levites Uriel, Asaiah, Joel, Shemaiah, Eliel, and Amminadab.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 12, 'He said to them, "You are the heads of families of the Levites; sanctify yourselves, you and your kindred, so that you may bring up the ark of the LORD, the God of Israel, to the place that I have prepared for it.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 13, 'Because you did not carry it the first time, the LORD our God burst out against us, because we did not give it proper care."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 14, 'So the priests and the Levites sanctified themselves to bring up the ark of the LORD, the God of Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 15, 'And the Levites carried the ark of God on their shoulders with the poles, as Moses had commanded according to the word of the LORD.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 16, 'David also commanded the chiefs of the Levites to appoint their kindred as the singers to play on musical instruments, on harps and lyres and cymbals, to raise loud sounds of joy.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 17, 'So the Levites appointed Heman son of Joel; and of his kindred Asaph son of Berechiah; and of the sons of Merari, their kindred, Ethan son of Kushaiah;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 18, 'and with them their kindred of the second order, Zechariah, Jaaziel, Shemiramoth, Jehiel, Unni, Eliab, Benaiah, Maaseiah, Mattithiah, Eliphelehu, and Mikneiah, and the gatekeepers Obed-edom and Jeiel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 19, 'The singers Heman, Asaph, and Ethan were to sound bronze cymbals;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 20, 'Zechariah, Aziel, Shemiramoth, Jehiel, Unni, Eliab, Maaseiah, and Benaiah were to play harps according to Alamoth;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 21, 'but Mattithiah, Eliphelehu, Mikneiah, Obed-edom, Jeiel, and Azaziah were to lead with lyres according to the Sheminith.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 22, 'Chenaniah, leader of the Levites in music, was to direct the music, for he understood it.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 23, 'Berechiah and Elkanah were to be gatekeepers for the ark.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 24, 'Shebaniah, Joshaphat, Nethanel, Amasai, Zechariah, Benaiah, and Eliezer, the priests, were to blow the trumpets before the ark of God. Obed-edom and Jehiah also were to be gatekeepers for the ark.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 25, 'So David and the elders of Israel, and the commanders of the thousands, went to bring up the ark of the covenant of the LORD from the house of Obed-edom with rejoicing.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 26, 'And because God helped the Levites who were carrying the ark of the covenant of the LORD, they sacrificed seven bulls and seven rams.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 27, 'David was clothed with a robe of fine linen, as also were all the Levites who were carrying the ark, and the singers, and Chenaniah the leader of the music of the singers; and David wore a linen ephod.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 28, 'So all Israel brought up the ark of the covenant of the LORD with shouting, to the sound of the horn, trumpets, and cymbals, and made loud music on harps and lyres.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 15, 29, 'As the ark of the covenant of the LORD came to the city of David, Michal daughter of Saul looked out of the window, and saw King David leaping and dancing; and she despised him in her heart.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 16, 1, 'They brought in the ark of God, and set it inside the tent that David had pitched for it; and they offered burnt offerings and offerings of well-being before God.', 'en', 'NRSV-CE', 'The Ark Placed in the Tent'),
(13, '1 Taw', '1 Chronicles', 16, 2, 'When David had finished offering the burnt offerings and the offerings of well-being, he blessed the people in the name of the LORD;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 16, 3, 'and he distributed to every person in Israel--man and woman alike--to each a loaf of bread, a portion of meat, and a cake of raisins.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 16, 4, 'He appointed certain of the Levites as ministers before the ark of the LORD, to invoke, to thank, and to praise the LORD, the God of Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 16, 5, 'Asaph was the chief, and second to him Zechariah, Jeiel, Shemiramoth, Jehiel, Mattithiah, Eliab, Benaiah, Obed-edom, and Jeiel, with harps and lyres; Asaph was to sound the cymbals,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 16, 6, 'and the priests Benaiah and Jahaziel were to blow trumpets regularly, before the ark of the covenant of God.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 16, 7, 'Then on that day David first appointed the singing of praises to the LORD by Asaph and his kindred.', 'en', 'NRSV-CE', 'David"s Psalm of Thanksgiving'),
(13, '1 Taw', '1 Chronicles', 16, 8, 'O give thanks to the LORD, call on his name,  
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 17, 1, 'Now when David settled in his house, David said to the prophet Nathan, "I am living in a house of cedar, but the ark of the covenant of the LORD is under a tent."', 'en', 'NRSV-CE', 'God"s Covenant with David'),
(13, '1 Taw', '1 Chronicles', 17, 2, 'Nathan said to David, "Do all that you have in mind, for God is with you."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 17, 3, 'But that same night the word of the LORD came to Nathan, saying:', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 17, 4, 'Go and tell my servant David: Thus says the LORD: You shall not build me a house to live in.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 17, 5, 'For I have not lived in a house since the day I brought out Israel to this very day, but I have lived in a tent and a tabernacle.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 17, 6, 'Wherever I have moved about among all Israel, did I ever speak a word with any of the judges of Israel, whom I commanded to shepherd my people, saying, Why have you not built me a house of cedar?', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 17, 7, 'Now therefore thus you shall say to my servant David: Thus says the LORD of hosts: I took you from the pasture, from following the sheep, to be ruler over my people Israel;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 17, 8, 'and I have been with you wherever you went, and have cut off all your enemies before you; and I will make for you a name, like the name of the great ones of the earth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 17, 9, 'I will appoint a place for my people Israel, and will plant them, so that they may live in their own place, and be disturbed no more; and evildoers shall wear them down no more, as they did formerly,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 17, 10, 'from the time that I appointed judges over my people Israel; and I will subdue all your enemies.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 18, 1, 'Some time afterward, David attacked the Philistines and subdued them; he took Gath and its villages from the Philistines.', 'en', 'NRSV-CE', 'David"s Kingdom Established and Extended'),
(13, '1 Taw', '1 Chronicles', 18, 2, 'He defeated Moab, and the Moabites became subject to David and brought tribute.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 3, 'David also struck down King Hadadezer of Zobah, toward Hamath, as he went to set up a monument at the river Euphrates.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 4, 'David took from him one thousand chariots, seven thousand cavalry, and twenty thousand foot soldiers. David hamstrung all the chariot horses, but left one hundred of them.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 5, 'When the Arameans of Damascus came to help King Hadadezer of Zobah, David killed twenty-two thousand Arameans.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 6, 'Then David put garrisons in Aram of Damascus; and the Arameans became subject to David, and brought tribute. The LORD gave victory to David wherever he went.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 7, 'David took the gold shields that were carried by the servants of Hadadezer, and brought them to Jerusalem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 8, 'From Tibhath and from Cun, cities of Hadadezer, David took a vast quantity of bronze; with it Solomon made the bronze sea and the pillars and the vessels of bronze.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 9, 'When King Tou of Hamath heard that David had defeated the whole army of King Hadadezer of Zobah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 10, 'he sent his son Hadoram to King David, to greet him and to congratulate him, because he had fought against Hadadezer and defeated him. Now Hadadezer had often been at war with Tou. He sent all sorts of articles of gold, of silver, and of bronze;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 11, 'these also King David dedicated to the LORD, together with the silver and gold that he had carried off from all the nations, from Edom, Moab, the Ammonites, the Philistines, and Amalek.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 12, 'Abishai son of Zeruiah killed eighteen thousand Edomites in the Valley of Salt.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 13, 'He put garrisons in Edom; and all the Edomites became subject to David. And the LORD gave victory to David wherever he went.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 14, 'So David reigned over all Israel; and he administered justice and equity to all his people.', 'en', 'NRSV-CE', 'David"s Administration'),
(13, '1 Taw', '1 Chronicles', 18, 15, 'Joab son of Zeruiah was over the army; Jehoshaphat son of Ahilud was recorder;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 16, 'Zadok son of Ahitub and Ahimelech son of Abiathar were priests; Shavsha was secretary;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 18, 17, 'Benaiah son of Jehoiada was over the Cherethites and the Pelethites; and David"s sons were the chief officials in the service of the king.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 19, 1, 'Some time afterward, King Nahash of the Ammonites died, and his son succeeded him.', 'en', 'NRSV-CE', 'Defeat of the Ammonites and Arameans'),
(13, '1 Taw', '1 Chronicles', 19, 2, 'David said, "I will deal loyally with Hanun son of Nahash, for his father dealt loyally with me." So David sent messengers to console him concerning his father. When David"s servants came to Hanun in the land of the Ammonites, to console him,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 3, 'the officials of the Ammonites said to Hanun, "Do you think, because David has sent consolers to you, that he is honoring your father? Have not his servants come to you to search and to overthrow and to spy out the land?"', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 4, 'So Hanun seized David"s servants, shaved them, cut off their garments in the middle at their hips, and sent them away;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 5, 'and they departed. When David was told about the men, he sent messengers to them, for they felt greatly humiliated. The king said, "Remain at Jericho until your beards have grown, and then return."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 6, 'When the Ammonites saw that they had made themselves odious to David, Hanun and the Ammonites sent a thousand talents of silver to hire chariots and cavalry from Mesopotamia, from Aram-maacah and from Zobah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 7, 'They hired thirty-two thousand chariots and the king of Maacah with his army, who came and camped before Medeba. And the Ammonites were mustered from their cities and came to battle.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 8, 'When David heard of it, he sent Joab and all the army of the warriors.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 9, 'The Ammonites came out and drew up in battle array at the entrance of the city, and the kings who had come were by themselves in the open country.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 10, 'When Joab saw that the line of battle was set against him both in front and in the rear, he chose some of the picked men of Israel and arrayed them against the Arameans;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 11, 'the rest of his troops he put in the charge of his brother Abishai, and they were arrayed against the Ammonites.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 12, 'He said, "If the Arameans are too strong for me, then you shall help me; but if the Ammonites are too strong for you, then I will help you.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 13, 'Be strong, and let us be courageous for our people and for the cities of our God; and may the LORD do what seems good to him."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 14, 'So Joab and the troops who were with him advanced toward the Arameans for battle; and they fled before him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 15, 'When the Ammonites saw that the Arameans fled, they likewise fled before Abishai, Joab"s brother, and entered the city. Then Joab came to Jerusalem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 16, 'But when the Arameans saw that they had been defeated by Israel, they sent messengers and brought out the Arameans who were beyond the Euphrates, with Shophach the commander of the army of Hadadezer at their head.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 17, 'When David was informed, he gathered all Israel together, crossed the Jordan, came to them, and drew up his forces against them. When David set the battle in array against the Arameans, they fought with him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 18, 'The Arameans fled before Israel; and David killed seven thousand Aramean charioteers and forty thousand foot soldiers, and also killed Shophach the commander of their army.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 19, 19, 'When the servants of Hadadezer saw that they had been defeated by Israel, they made peace with David, and became subject to him. So the Arameans were not willing to help the Ammonites any more.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 20, 1, 'In the spring of the year, the time when kings go out to battle, Joab led out the army, ravaged the country of the Ammonites, and came and besieged Rabbah. But David remained at Jerusalem. Joab attacked Rabbah, and overthrew it.', 'en', 'NRSV-CE', 'Siege and Capture of Rabbah'),
(13, '1 Taw', '1 Chronicles', 20, 2, 'David took the crown of Milcom from his head; he found that it weighed a talent of gold, and in it was a precious stone; and it was placed on David"s head. He also brought out the booty of the city, a very great amount.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 20, 3, 'He brought out the people who were in it, and set them to work with saws and iron picks and axes. Thus David did to all the cities of the Ammonites. Then David and all the people returned to Jerusalem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 20, 4, 'After this, war broke out with the Philistines at Gezer; then Sibbecai the Hushathite killed Sippai, who was one of the descendants of the giants; and the Philistines were subdued.', 'en', 'NRSV-CE', 'Exploits against the Philistines'),
(13, '1 Taw', '1 Chronicles', 20, 5, 'Again there was war with the Philistines; and Elhanan son of Jair killed Lahmi the brother of Goliath the Gittite, the shaft of whose spear was like a weaver"s beam.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 20, 6, 'Again there was war at Gath, where there was a man of great size, who had six fingers on each hand, and six toes on each foot, twenty-four in number; he also was descended from the giants.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 20, 7, 'When he taunted Israel, Jonathan son of Shimea, David"s brother, killed him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 20, 8, 'These were descended from the giants in Gath; they fell by the hand of David and his servants.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 21, 1, 'Satan stood up against Israel, and incited David to count the people of Israel.', 'en', 'NRSV-CE', 'The Census and Plague'),
(13, '1 Taw', '1 Chronicles', 21, 2, 'So David said to Joab and the commanders of the army, "Go, number Israel, from Beer-sheba to Dan, and bring me a report, so that I may know their number."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 3, 'But Joab said, "May the LORD increase the number of his people a hundredfold! Are they not, my lord the king, all of them my lord"s servants? Why then should my lord require this? Why should he bring guilt on Israel?"', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 4, 'But the king"s word prevailed against Joab. So Joab departed and went throughout all Israel, and came back to Jerusalem.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 5, 'Joab gave the total count of the people to David. In all Israel there were one million one hundred thousand men who drew the sword, and in Judah four hundred seventy thousand who drew the sword.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 6, 'But he did not include Levi and Benjamin in the numbering, for the king"s command was abhorrent to Joab.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 7, 'But God was displeased with this thing, and he struck Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 8, 'David said to God, "I have sinned greatly in that I have done this thing. But now, I pray you, take away the guilt of your servant; for I have done very foolishly."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 9, 'The LORD spoke to Gad, David"s seer, saying,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 10, '"Go and say to David, "Thus says the LORD: Three things I offer you; choose one of them, so that I may do it to you.""', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 11, 'So Gad came to David and said to him, "Thus says the LORD, "Take your choice:', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 12, 'either three years of famine; or three months of devastation by your foes, while the sword of your enemies overtakes you; or three days of the sword of the LORD, pestilence on the land, and the angel of the LORD destroying throughout all the territory of Israel." Now decide what answer I shall return to the one who sent me."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 13, 'Then David said to Gad, "I am in great distress; let me fall into the hand of the LORD, for his mercy is very great; but let me not fall into human hands."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 14, 'So the LORD sent a pestilence on Israel; and seventy thousand persons fell in Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 15, 'And God sent an angel to Jerusalem to destroy it; but when he was about to destroy it, the LORD took note and relented concerning the calamity; he said to the destroying angel, "Enough! Stay your hand." The angel of the LORD was then standing by the threshing floor of Ornan the Jebusite.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 16, 'David looked up and saw the angel of the LORD standing between earth and heaven, and in his hand a drawn sword stretched out over Jerusalem. Then David and the elders, clothed in sackcloth, fell on their faces.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 17, 'And David said to God, "Was it not I who gave the command to count the people? It is I who have sinned and done very wickedly. But these sheep, what have they done? Let your hand, I pray, O LORD my God, be against me and against my father"s house; but do not let your people be plagued!"', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 18, 'Then the angel of the LORD commanded Gad to tell David that he should go up and erect an altar to the LORD on the threshing floor of Ornan the Jebusite.', 'en', 'NRSV-CE', 'David"s Altar and Sacrifice'),
(13, '1 Taw', '1 Chronicles', 21, 19, 'So David went up following Gad"s instructions, which he had spoken in the name of the LORD.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 20, 'Ornan turned and saw the angel; and while his four sons who were with him hid themselves, Ornan continued to thresh wheat.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 21, 'As David came to Ornan, Ornan looked and saw David; he went out from the threshing floor, and did obeisance to David with his face to the ground.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 22, 'David said to Ornan, "Give me the site of the threshing floor that I may build on it an altar to the LORD--give it to me at its full price--so that the plague may be averted from the people."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 23, 'Then Ornan said to David, "Take it; and let my lord the king do what seems good to him; see, I present the oxen for burnt offerings, and the threshing sledges for the wood, and the wheat for a grain offering. I give it all."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 24, 'But King David said to Ornan, "No; I will buy them for the full price. I will not take for the LORD what is yours, nor offer burnt offerings that cost me nothing."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 25, 'So David paid Ornan six hundred shekels of gold by weight for the site.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 26, 'David built there an altar to the LORD and presented burnt offerings and offerings of well-being. He called upon the LORD, and he answered him with fire from heaven on the altar of burnt offering.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 27, 'Then the LORD commanded the angel, and he put his sword back into its sheath.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 28, 'At that time, when David saw that the LORD had answered him at the threshing floor of Ornan the Jebusite, he made his sacrifices there.', 'en', 'NRSV-CE', 'The Place Chosen for the Temple'),
(13, '1 Taw', '1 Chronicles', 21, 29, 'For the tabernacle of the LORD, which Moses had made in the wilderness, and the altar of burnt offering were at that time in the high place at Gibeon;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 21, 30, 'but David could not go before it to inquire of God, for he was afraid of the sword of the angel of the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 22, 1, 'Then David said, "Here shall be the house of the LORD God and here the altar of burnt offering for Israel."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 2, 'David gave orders to gather together the aliens who were residing in the land of Israel, and he set stonecutters to prepare dressed stones for building the house of God.', 'en', 'NRSV-CE', 'David Prepares to Build the Temple'),
(13, '1 Taw', '1 Chronicles', 22, 3, 'David also provided great stores of iron for nails for the doors of the gates and for clamps, as well as bronze in quantities beyond weighing,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 4, 'and cedar logs without number--for the Sidonians and Tyrians brought great quantities of cedar to David.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 5, 'For David said, "My son Solomon is young and inexperienced, and the house that is to be built for the LORD must be exceedingly magnificent, famous and glorified throughout all lands; I will therefore make preparation for it." So David provided materials in great quantity before his death.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 6, 'Then he called for his son Solomon and charged him to build a house for the LORD, the God of Israel.', 'en', 'NRSV-CE', 'David"s Charge to Solomon and the Leaders'),
(13, '1 Taw', '1 Chronicles', 22, 7, 'David said to Solomon, "My son, I had planned to build a house to the name of the LORD my God.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 8, 'But the word of the LORD came to me, saying, "You have shed much blood and have waged great wars; you shall not build a house to my name, because you have shed so much blood in my sight on the earth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 9, 'See, a son shall be born to you; he shall be a man of peace. I will give him peace from all his enemies on every side; for his name shall be Solomon, and I will give peace and quiet to Israel in his days.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 10, 'He shall build a house for my name. He shall be a son to me, and I will be a father to him, and I will establish his royal throne in Israel forever."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 11, 'Now, my son, the LORD be with you, so that you may succeed in building the house of the LORD your God, as he has spoken concerning you.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 12, 'Only, may the LORD grant you discretion and understanding, so that when he gives you charge over Israel you may keep the law of the LORD your God.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 13, 'Then you will prosper if you are careful to observe the statutes and the ordinances that the LORD commanded Moses for Israel. Be strong and of good courage. Do not be afraid or dismayed.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 14, 'With great pains I have provided for the house of the LORD one hundred thousand talents of gold, one million talents of silver, and bronze and iron beyond weighing, for there is so much of it; timber and stone too I have provided. To these you must add more.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 15, 'You have an abundance of workers: stonecutters, masons, carpenters, and all kinds of artisans without number, skilled in working', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 16, 'gold, silver, bronze, and iron. Now begin the work, and the LORD be with you."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 17, 'David also commanded all the leaders of Israel to help his son Solomon, saying,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 18, '"Is not the LORD your God with you? Has he not given you peace on every side? For he has delivered the inhabitants of the land into my hand; and the land is subdued before the LORD and his people.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 22, 19, 'Now set your mind and heart to seek the LORD your God. Go and build the sanctuary of the LORD God so that the ark of the covenant of the LORD and the holy vessels of God may be brought into a house built for the name of the LORD."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 23, 1, 'When David was old and full of days, he made his son Solomon king over Israel.', 'en', 'NRSV-CE', 'Families of the Levites and Their Functions'),
(13, '1 Taw', '1 Chronicles', 23, 2, 'David assembled all the leaders of Israel and the priests and the Levites.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 3, 'The Levites, thirty years old and upward, were counted, and the total was thirty-eight thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 4, '"Twenty-four thousand of these," David said, "shall have charge of the work in the house of the LORD, six thousand shall be officers and judges,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 5, 'four thousand gatekeepers, and four thousand shall offer praises to the LORD with the instruments that I have made for praise."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 6, 'And David organized them in divisions corresponding to the sons of Levi: Gershon, Kohath, and Merari.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 7, 'The sons of Gershon were Ladan and Shimei.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 8, 'The sons of Ladan: Jehiel the chief, Zetham, and Joel, three.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 9, 'The sons of Shimei: Shelomoth, Haziel, and Haran, three. These were the heads of families of Ladan.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 10, 'And the sons of Shimei: Jahath, Zina, Jeush, and Beriah. These four were the sons of Shimei.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 11, 'Jahath was the chief, and Zizah the second; but Jeush and Beriah did not have many sons, so they were enrolled as a single family.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 12, 'The sons of Kohath: Amram, Izhar, Hebron, and Uzziel, four.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 13, 'The sons of Amram: Aaron and Moses. Aaron was set apart to consecrate the most holy things, so that he and his sons forever should make offerings before the LORD, and minister to him and pronounce blessings in his name forever;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 14, 'but as for Moses the man of God, his sons were to be reckoned among the tribe of Levi.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 15, 'The sons of Moses: Gershom and Eliezer.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 16, 'The sons of Gershom: Shebuel the chief.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 17, 'The sons of Eliezer: Rehabiah the chief; Eliezer had no other sons, but the sons of Rehabiah were very numerous.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 18, 'The sons of Izhar: Shelomith the chief.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 19, 'The sons of Hebron: Jeriah the chief, Amariah the second, Jahaziel the third, and Jekameam the fourth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 20, 'The sons of Uzziel: Micah the chief and Isshiah the second.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 21, 'The sons of Merari: Mahli and Mushi. The sons of Mahli: Eleazar and Kish.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 22, 'Eleazar died having no sons, but only daughters; their kindred, the sons of Kish, married them.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 23, 'The sons of Mushi: Mahli, Eder, and Jeremoth, three.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 24, 'These were the sons of Levi by their ancestral houses, the heads of families as they were enrolled according to the number of the names of the individuals from twenty years old and upward who were to do the work for the service of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 25, 'For David said, "The LORD, the God of Israel, has given rest to his people; and he resides in Jerusalem forever.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 26, 'And so the Levites no longer need to carry the tabernacle or any of the things for its service"--', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 27, 'for according to the last words of David these were the number of the Levites from twenty years old and upward--', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 28, '"but their duty shall be to assist the descendants of Aaron for the service of the house of the LORD, having the care of the courts and the chambers, the cleansing of all that is holy, and any work for the service of the house of God;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 29, 'to assist also with the rows of bread, the choice flour for the grain offering, the wafers of unleavened bread, the baked offering, the offering mixed with oil, and all measures of quantity or size.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 30, 'And they shall stand every morning, thanking and praising the LORD, and likewise at evening,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 31, 'and whenever burnt offerings are offered to the LORD on sabbaths, new moons, and appointed festivals, according to the number required of them, regularly before the LORD.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 23, 32, 'Thus they shall keep charge of the tent of meeting and the sanctuary, and shall attend the descendants of Aaron, their kindred, for the service of the house of the LORD."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 24, 1, 'The divisions of the descendants of Aaron were these. The sons of Aaron: Nadab, Abihu, Eleazar, and Ithamar.', 'en', 'NRSV-CE', 'Divisions of the Priests'),
(13, '1 Taw', '1 Chronicles', 24, 2, 'But Nadab and Abihu died before their father, and had no sons; so Eleazar and Ithamar became the priests.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 3, 'Along with Zadok of the sons of Eleazar, and Ahimelech of the sons of Ithamar, David organized them according to the appointed duties in their service.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 4, 'Since more chief men were found among the sons of Eleazar than among the sons of Ithamar, they organized them under sixteen heads of ancestral houses of the sons of Eleazar, and eight of the sons of Ithamar.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 5, 'They organized them by lot, all alike, for there were officers of the sanctuary and officers of God among both the sons of Eleazar and the sons of Ithamar.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 6, 'The scribe Shemaiah son of Nethanel, a Levite, recorded them in the presence of the king, and the officers, and Zadok the priest, and Ahimelech son of Abiathar, and the heads of ancestral houses of the priests and of the Levites; one ancestral house being chosen for Eleazar and one chosen for Ithamar.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 7, 'The first lot fell to Jehoiarib, the second to Jedaiah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 8, 'the third to Harim, the fourth to Seorim,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 9, 'the fifth to Malchijah, the sixth to Mijamin,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 10, 'the seventh to Hakkoz, the eighth to Abijah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 11, 'the ninth to Jeshua, the tenth to Shecaniah,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 12, 'the eleventh to Eliashib, the twelfth to Jakim,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 13, 'the thirteenth to Huppah, the fourteenth to Jeshebeab,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 14, 'the fifteenth to Bilgah, the sixteenth to Immer,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 15, 'the seventeenth to Hezir, the eighteenth to Happizzez,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 16, 'the nineteenth to Pethahiah, the twentieth to Jehezkel,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 17, 'the twenty-first to Jachin, the twenty-second to Gamul,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 18, 'the twenty-third to Delaiah, the twenty-fourth to Maaziah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 19, 'These had as their appointed duty in their service to enter the house of the LORD according to the procedure established for them by their ancestor Aaron, as the LORD God of Israel had commanded him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 20, 'And of the rest of the sons of Levi: of the sons of Amram, Shubael; of the sons of Shubael, Jehdeiah.', 'en', 'NRSV-CE', 'Other Levites'),
(13, '1 Taw', '1 Chronicles', 24, 21, 'Of Rehabiah: of the sons of Rehabiah, Isshiah the chief.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 22, 'Of the Izharites, Shelomoth; of the sons of Shelomoth, Jahath.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 23, 'The sons of Hebron: Jeriah the chief, Amariah the second, Jahaziel the third, Jekameam the fourth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 24, 'The sons of Uzziel, Micah; of the sons of Micah, Shamir.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 25, 'The brother of Micah, Isshiah; of the sons of Isshiah, Zechariah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 26, 'The sons of Merari: Mahli and Mushi. The sons of Jaaziah: Beno.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 27, 'The sons of Merari: of Jaaziah, Beno, Shoham, Zaccur, and Ibri.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 28, 'Of Mahli: Eleazar, who had no sons.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 29, 'Of Kish, the sons of Kish: Jerahmeel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 30, 'The sons of Mushi: Mahli, Eder, and Jerimoth. These were the sons of the Levites according to their ancestral houses.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 24, 31, 'These also cast lots corresponding to their kindred, the descendants of Aaron, in the presence of King David, Zadok, Ahimelech, and the heads of ancestral houses of the priests and of the Levites, the chief as well as the youngest brother.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 25, 1, 'David and the officers of the army also set apart for the service the sons of Asaph, and of Heman, and of Jeduthun, who should prophesy with lyres, harps, and cymbals. The list of those who did the work and of their duties was:', 'en', 'NRSV-CE', 'The Temple Musicians'),
(13, '1 Taw', '1 Chronicles', 25, 2, 'Of the sons of Asaph: Zaccur, Joseph, Nethaniah, and Asarelah, sons of Asaph, under the direction of Asaph, who prophesied under the direction of the king.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 3, 'Of Jeduthun, the sons of Jeduthun: Gedaliah, Zeri, Jeshaiah, Shimei, Hashabiah, and Mattithiah, six, under the direction of their father Jeduthun, who prophesied with the lyre in thanksgiving and praise to the LORD.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 4, 'Of Heman, the sons of Heman: Bukkiah, Mattaniah, Uzziel, Shebuel, and Jerimoth, Hananiah, Hanani, Eliathah, Giddalti, and Romamti-ezer, Joshbekashah, Mallothi, Hothir, Mahazioth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 5, 'All these were the sons of Heman the king"s seer, according to the promise of God to exalt him; for God had given Heman fourteen sons and three daughters.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 6, 'They were all under the direction of their father for the music in the house of the LORD with cymbals, harps, and lyres for the service of the house of God. Asaph, Jeduthun, and Heman were under the order of the king.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 7, 'They and their kindred, who were trained in singing to the LORD, all of whom were skillful, numbered two hundred eighty-eight.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 8, 'And they cast lots for their duties, small and great, teacher and pupil alike.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 9, 'The first lot fell for Asaph to Joseph; the second to Gedaliah, to him and his brothers and his sons, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 10, 'the third to Zaccur, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 11, 'the fourth to Izri, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 12, 'the fifth to Nethaniah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 13, 'the sixth to Bukkiah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 14, 'the seventh to Jesarelah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 15, 'the eighth to Jeshaiah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 16, 'the ninth to Mattaniah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 17, 'the tenth to Shimei, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 18, 'the eleventh to Azarel, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 19, 'the twelfth to Hashabiah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 20, 'to the thirteenth, Shubael, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 21, 'to the fourteenth, Mattithiah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 22, 'to the fifteenth, to Jeremoth, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 23, 'to the sixteenth, to Hananiah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 24, 'to the seventeenth, to Joshbekashah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 25, 'to the eighteenth, to Hanani, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 26, 'to the nineteenth, to Mallothi, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 27, 'to the twentieth, to Eliathah, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 28, 'to the twenty-first, to Hothir, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 29, 'to the twenty-second, to Giddalti, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 30, 'to the twenty-third, to Mahazioth, his sons and his brothers, twelve;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 25, 31, 'to the twenty-fourth, to Romamti-ezer, his sons and his brothers, twelve.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 26, 1, 'As for the divisions of the gatekeepers: of the Korahites, Meshelemiah son of Kore, of the sons of Asaph.', 'en', 'NRSV-CE', 'The Gatekeepers'),
(13, '1 Taw', '1 Chronicles', 26, 2, 'Meshelemiah had sons: Zechariah the firstborn, Jediael the second, Zebadiah the third, Jathniel the fourth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 3, 'Elam the fifth, Jehohanan the sixth, Eliehoenai the seventh.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 4, 'Obed-edom had sons: Shemaiah the firstborn, Jehozabad the second, Joah the third, Sachar the fourth, Nethanel the fifth,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 5, 'Ammiel the sixth, Issachar the seventh, Peullethai the eighth; for God blessed him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 6, 'Also to his son Shemaiah sons were born who exercised authority in their ancestral houses, for they were men of great ability.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 7, 'The sons of Shemaiah: Othni, Rephael, Obed, and Elzabad, whose brothers were able men, Elihu and Semachiah.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 8, 'All these, sons of Obed-edom with their sons and brothers, were able men qualified for the service; sixty-two of Obed-edom.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 9, 'Meshelemiah had sons and brothers, able men, eighteen.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 10, 'Hosah, of the sons of Merari, had sons: Shimri the chief (for though he was not the firstborn, his father made him chief),', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 11, 'Hilkiah the second, Tebaliah the third, Zechariah the fourth: all the sons and brothers of Hosah totaled thirteen.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 12, 'These divisions of the gatekeepers, corresponding to their leaders, had duties, just as their kindred did, ministering in the house of the LORD;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 13, 'and they cast lots by ancestral houses, small and great alike, for their gates.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 14, 'The lot for the east fell to Shelemiah. They cast lots also for his son Zechariah, a prudent counselor, and his lot came out for the north.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 15, 'Obed-edom"s came out for the south, and to his sons was allotted the storehouse.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 16, 'For Shuppim and Hosah it came out for the west, at the gate of Shallecheth on the ascending road. Guard corresponded to guard.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 17, 'On the east there were six Levites each day, on the north four each day, on the south four each day, as well as two and two at the storehouse;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 18, 'and for the colonnade on the west there were four at the road and two at the colonnade.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 19, 'These were the divisions of the gatekeepers among the Korahites and the sons of Merari.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 20, 'And of the Levites, Ahijah had charge of the treasuries of the house of God and the treasuries of the dedicated gifts.', 'en', 'NRSV-CE', 'The Treasurers, Officers, and Judges'),
(13, '1 Taw', '1 Chronicles', 26, 21, 'The sons of Ladan, the sons of the Gershonites belonging to Ladan, the heads of families belonging to Ladan the Gershonite: Jehieli.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 22, 'The sons of Jehieli, Zetham and his brother Joel, were in charge of the treasuries of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 23, 'Of the Amramites, the Izharites, the Hebronites, and the Uzzielites:', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 24, 'Shebuel son of Gershom, son of Moses, was chief officer in charge of the treasuries.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 25, 'His brothers: from Eliezer were his son Rehabiah, his son Jeshaiah, his son Joram, his son Zichri, and his son Shelomoth.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 26, 'This Shelomoth and his brothers were in charge of all the treasuries of the dedicated gifts that King David, and the heads of families, and the officers of the thousands and the hundreds, and the commanders of the army, had dedicated.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 27, 'From booty won in battles they dedicated gifts for the maintenance of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 28, 'Also all that Samuel the seer, and Saul son of Kish, and Abner son of Ner, and Joab son of Zeruiah had dedicated--all dedicated gifts were in the care of Shelomoth and his brothers.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 29, 'Of the Izharites, Chenaniah and his sons were appointed to outside duties for Israel, as officers and judges.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 30, 'Of the Hebronites, Hashabiah and his brothers, one thousand seven hundred men of ability, had the oversight of Israel west of the Jordan for all the work of the LORD and for the service of the king.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 31, 'Of the Hebronites, Jerijah was chief of the Hebronites. (In the fortieth year of David"s reign search was made, of whatever genealogy or family, and men of great ability among them were found at Jazer in Gilead.)', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 26, 32, 'King David appointed him and his brothers, two thousand seven hundred men of ability, heads of families, to have the oversight of the Reubenites, the Gadites, and the half-tribe of the Manassites for everything pertaining to God and for the affairs of the king.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 27, 1, 'This is the list of the people of Israel, the heads of families, the commanders of the thousands and the hundreds, and their officers who served the king in all matters concerning the divisions that came and went, month after month throughout the year, each division numbering twenty-four thousand:', 'en', 'NRSV-CE', 'The Military Divisions'),
(13, '1 Taw', '1 Chronicles', 27, 2, 'Jashobeam son of Zabdiel was in charge of the first division in the first month; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 3, 'He was a descendant of Perez, and was chief of all the commanders of the army for the first month.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 4, 'Dodai the Ahohite was in charge of the division of the second month; Mikloth was the chief officer of his division. In his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 5, 'The third commander, for the third month, was Benaiah son of the priest Jehoiada, as chief; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 6, 'This is the Benaiah who was a mighty man of the Thirty and in command of the Thirty; his son Ammizabad was in charge of his division.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 7, 'Asahel brother of Joab was fourth, for the fourth month, and his son Zebadiah after him; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 8, 'The fifth commander, for the fifth month, was Shamhuth, the Izrahite; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 9, 'Sixth, for the sixth month, was Ira son of Ikkesh the Tekoite; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 10, 'Seventh, for the seventh month, was Helez the Pelonite, of the Ephraimites; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 11, 'Eighth, for the eighth month, was Sibbecai the Hushathite, of the Zerahites; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 12, 'Ninth, for the ninth month, was Abiezer of Anathoth, a Benjaminite; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 13, 'Tenth, for the tenth month, was Maharai of Netophah, of the Zerahites; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 14, 'Eleventh, for the eleventh month, was Benaiah of Pirathon, of the Ephraimites; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 15, 'Twelfth, for the twelfth month, was Heldai the Netophathite, of Othniel; in his division were twenty-four thousand.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 16, 'Over the tribes of Israel, for the Reubenites, Eliezer son of Zichri was chief officer; for the Simeonites, Shephatiah son of Maacah;', 'en', 'NRSV-CE', 'Leaders of Tribes'),
(13, '1 Taw', '1 Chronicles', 27, 17, 'for Levi, Hashabiah son of Kemuel; for Aaron, Zadok;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 18, 'for Judah, Elihu, one of David"s brothers; for Issachar, Omri son of Michael;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 19, 'for Zebulun, Ishmaiah son of Obadiah; for Naphtali, Jerimoth son of Azriel;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 20, 'for the Ephraimites, Hoshea son of Azaziah; for the half-tribe of Manasseh, Joel son of Pedaiah;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 21, 'for the half-tribe of Manasseh in Gilead, Iddo son of Zechariah; for Benjamin, Jaasiel son of Abner;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 22, 'for Dan, Azarel son of Jeroham. These were the leaders of the tribes of Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 23, 'David did not count those below twenty years of age, for the LORD had promised to make Israel as numerous as the stars of heaven.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 24, 'Joab son of Zeruiah began to count them, but did not finish; yet wrath came upon Israel for this, and the number was not entered into the account of the Annals of King David.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 25, 'Over the king"s treasuries was Azmaveth son of Adiel. Over the treasuries in the country, in the cities, in the villages and in the towers, was Jonathan son of Uzziah.', 'en', 'NRSV-CE', 'Other Civic Officials'),
(13, '1 Taw', '1 Chronicles', 27, 26, 'Over those who did the work of the field, tilling the soil, was Ezri son of Chelub.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 27, 'Over the vineyards was Shimei the Ramathite. Over the produce of the vineyards for the wine cellars was Zabdi the Shiphmite.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 28, 'Over the olive and sycamore trees in the Shephelah was Baal-hanan the Gederite. Over the stores of oil was Joash.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 29, 'Over the herds that pastured in Sharon was Shitrai the Sharonite. Over the herds in the valleys was Shaphat son of Adlai.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 30, 'Over the camels was Obil the Ishmaelite. Over the donkeys was Jehdeiah the Meronothite. Over the flocks was Jaziz the Hagrite.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 31, 'All these were stewards of King David"s property.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 32, 'Jonathan, David"s uncle, was a counselor, being a man of understanding and a scribe; Jehiel son of Hachmoni attended the king"s sons.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 33, 'Ahithophel was the king"s counselor, and Hushai the Archite was the king"s friend.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 27, 34, 'After Ahithophel came Jehoiada son of Benaiah, and Abiathar. Joab was commander of the king"s army.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 28, 1, 'David assembled at Jerusalem all the officials of Israel, the officials of the tribes, the officers of the divisions that served the king, the commanders of the thousands, the commanders of the hundreds, the stewards of all the property and cattle of the king and his sons, together with the palace officials, the mighty warriors, and all the warriors.', 'en', 'NRSV-CE', 'Solomon Instructed to Build the Temple'),
(13, '1 Taw', '1 Chronicles', 28, 2, 'Then King David rose to his feet and said: "Hear me, my brothers and my people. I had planned to build a house of rest for the ark of the covenant of the LORD, for the footstool of our God; and I made preparations for building.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 3, 'But God said to me, "You shall not build a house for my name, for you are a warrior and have shed blood."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 4, 'Yet the LORD God of Israel chose me from all my ancestral house to be king over Israel forever; for he chose Judah as leader, and in the house of Judah my father"s house, and among my father"s sons he took delight in making me king over all Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 5, 'And of all my sons, for the LORD has given me many, he has chosen my son Solomon to sit upon the throne of the kingdom of the LORD over Israel.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 6, 'He said to me, "It is your son Solomon who shall build my house and my courts, for I have chosen him to be a son to me, and I will be a father to him.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 7, 'I will establish his kingdom forever if he continues resolute in keeping my commandments and my ordinances, as he is today."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 8, 'Now therefore in the sight of all Israel, the assembly of the LORD, and in the hearing of our God, observe and search out all the commandments of the LORD your God; that you may possess this good land, and leave it for an inheritance to your children after you forever.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 9, '"And you, my son Solomon, know the God of your father, and serve him with single mind and willing heart; for the LORD searches every mind, and understands every plan and thought. If you seek him, he will be found by you; but if you forsake him, he will abandon you forever.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 10, 'Take heed now, for the LORD has chosen you to build a house as the sanctuary; be strong, and act."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 11, 'Then David gave his son Solomon the plan of the vestibule of the temple, and of its houses, its treasuries, its upper rooms, and its inner chambers, and of the room for the mercy seat;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 12, 'and the plan of all that he had in mind: for the courts of the house of the LORD, all the surrounding chambers, the treasuries of the house of God, and the treasuries for dedicated gifts;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 13, 'for the divisions of the priests and of the Levites, and all the work of the service in the house of the LORD; for all the vessels for the service in the house of the LORD,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 14, 'the weight of gold for all golden vessels for each service, the weight of silver vessels for each service,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 15, 'the weight of the golden lampstands and their lamps, the weight of gold for each lampstand and its lamps, the weight of silver for a lampstand and its lamps, according to the use of each in the service,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 16, 'the weight of gold for each table for the rows of bread, the silver for the silver tables,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 17, 'and pure gold for the forks, the basins, and the cups; for the golden bowls and the weight of each; for the silver bowls and the weight of each;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 18, 'for the altar of incense made of refined gold, and its weight; also his plan for the golden chariot of the cherubim that spread their wings and covered the ark of the covenant of the LORD.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 19, '"All this, in writing at the LORD"s direction, he made clear to me--the plan of all the works."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 20, 'David said further to his son Solomon, "Be strong and of good courage, and act. Do not be afraid or dismayed; for the LORD God, my God, is with you. He will not fail you or forsake you, until all the work for the service of the house of the LORD is finished.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 28, 21, 'Here are the divisions of the priests and the Levites for all the service of the house of God; and with you in all the work will be every volunteer who has skill for any kind of service; also the officers and all the people will be wholly at your command."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(13, '1 Taw', '1 Chronicles', 29, 1, 'King David said to the whole assembly, "My son Solomon, whom alone God has chosen, is young and inexperienced, and the work is great; for the temple will not be for mortals but for the LORD God.', 'en', 'NRSV-CE', 'Offerings for Building the Temple'),
(13, '1 Taw', '1 Chronicles', 29, 2, 'So I have provided for the house of my God, so far as I was able, the gold for the things of gold, the silver for the things of silver, and the bronze for the things of bronze, the iron for the things of iron, and wood for the things of wood, besides great quantities of onyx and stones for setting, antimony, colored stones, all sorts of precious stones, and marble in abundance.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 3, 'Moreover, in addition to all that I have provided for the holy house, I have a treasure of my own of gold and silver, and because of my devotion to the house of my God I give it to the house of my God:', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 4, 'three thousand talents of gold, of the gold of Ophir, and seven thousand talents of refined silver, for overlaying the walls of the house,', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 5, 'and for all the work to be done by artisans, gold for the things of gold and silver for the things of silver. Who then will offer willingly, consecrating themselves today to the LORD?"', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 6, 'Then the leaders of ancestral houses made their freewill offerings, as did also the leaders of the tribes, the commanders of the thousands and of the hundreds, and the officers over the king"s work.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 7, 'They gave for the service of the house of God five thousand talents and ten thousand darics of gold, ten thousand talents of silver, eighteen thousand talents of bronze, and one hundred thousand talents of iron.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 8, 'Whoever had precious stones gave them to the treasury of the house of the LORD, into the care of Jehiel the Gershonite.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 9, 'Then the people rejoiced because these had given willingly, for with single mind they had offered freely to the LORD; King David also rejoiced greatly.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 10, 'Then David blessed the LORD in the presence of all the assembly; David said: "Blessed are you, O LORD, the God of our ancestor Israel, forever and ever.', 'en', 'NRSV-CE', 'David"s Praise to God'),
(13, '1 Taw', '1 Chronicles', 29, 11, 'Yours, O LORD, are the greatness, the power, the glory, the victory, and the majesty; for all that is in the heavens and on the earth is yours; yours is the kingdom, O LORD, and you are exalted as head above all.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 12, 'Riches and honor come from you, and you rule over all. In your hand are power and might; and it is in your hand to make great and to give strength to all.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 13, 'And now, our God, we give thanks to you and praise your glorious name.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 14, '"But who am I, and what is my people, that we should be able to make this freewill offering? For all things come from you, and of your own have we given you.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 15, 'For we are aliens and transients before you, as were all our ancestors; our days on the earth are like a shadow, and there is no hope.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 16, 'O LORD our God, all this abundance that we have provided for building you a house for your holy name comes from your hand and is all your own.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 17, 'I know, my God, that you search the heart, and take pleasure in uprightness; in the uprightness of my heart I have freely offered all these things, and now I have seen your people, who are present here, offering freely and joyously to you.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 18, 'O LORD, the God of Abraham, Isaac, and Israel, our ancestors, keep forever such purposes and thoughts in the hearts of your people, and direct their hearts toward you.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 19, 'Grant to my son Solomon that with single mind he may keep your commandments, your decrees, and your statutes, performing all of them, and that he may build the temple for which I have made provision."', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 20, 'Then David said to the whole assembly, "Bless the LORD your God." And all the assembly blessed the LORD, the God of their ancestors, and bowed their heads and prostrated themselves before the LORD and the king.', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 21, 'On the next day they offered sacrifices and burnt offerings to the LORD, a thousand bulls, a thousand rams, and a thousand lambs, with their libations, and sacrifices in abundance for all Israel;', 'en', 'NRSV-CE', NULL),
(13, '1 Taw', '1 Chronicles', 29, 22, 'and they ate and drank before the LORD on that day with great joy.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 1, 1, 'Solomon son of David established himself in his kingdom; the LORD his God was with him and made him exceedingly great.', 'en', 'NRSV-CE', 'Solomon Requests Wisdom'),
(14, '2 Taw', '2 Chronicles', 1, 2, 'Solomon summoned all Israel, the commanders of the thousands and of the hundreds, the judges, and all the leaders of all Israel, the heads of families.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 3, 'Then Solomon, and the whole assembly with him, went to the high place that was at Gibeon; for God"s tent of meeting, which Moses the servant of the LORD had made in the wilderness, was there.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 4, '(But David had brought the ark of God up from Kiriath-jearim to the place that David had prepared for it; for he had pitched a tent for it in Jerusalem.)', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 5, 'Moreover the bronze altar that Bezalel son of Uri, son of Hur, had made, was there in front of the tabernacle of the LORD. And Solomon and the assembly inquired at it.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 6, 'Solomon went up there to the bronze altar before the LORD, which was at the tent of meeting, and offered a thousand burnt offerings on it.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 7, 'That night God appeared to Solomon, and said to him, "Ask what I should give you."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 8, 'Solomon said to God, "You have shown great and steadfast love to my father David, and have made me succeed him as king.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 9, 'O LORD God, let your promise to my father David now be fulfilled, for you have made me king over a people as numerous as the dust of the earth.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 10, 'Give me now wisdom and knowledge to go out and come in before this people, for who can rule this great people of yours?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 11, 'God answered Solomon, "Because this was in your heart, and you have not asked for possessions, wealth, honor, or the life of those who hate you, and have not even asked for long life, but have asked for wisdom and knowledge for yourself that you may rule my people over whom I have made you king,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 12, 'wisdom and knowledge are granted to you. I will also give you riches, possessions, and honor, such as none of the kings had who were before you, and none after you shall have the like."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 13, 'So Solomon came from the high place at Gibeon, from the tent of meeting, to Jerusalem. And he reigned over Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 14, 'Solomon gathered together chariots and horses; he had fourteen hundred chariots and twelve thousand horses, which he stationed in the chariot cities and with the king in Jerusalem.', 'en', 'NRSV-CE', 'Solomon"s Military and Commercial Activity'),
(14, '2 Taw', '2 Chronicles', 1, 15, 'The king made silver and gold as common in Jerusalem as stone, and he made cedar as plentiful as the sycamore of the Shephelah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 16, 'Solomon"s horses were imported from Egypt and Kue; the king"s traders received them from Kue at the prevailing price.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 1, 17, 'They imported from Egypt, and then exported, a chariot for six hundred shekels of silver, and a horse for one hundred fifty; so through them these were exported to all the kings of the Hittites and the kings of Aram.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 2, 1, 'Solomon decided to build a temple for the name of the LORD, and a royal palace for himself.', 'en', 'NRSV-CE', 'Preparations for Building the Temple'),
(14, '2 Taw', '2 Chronicles', 2, 2, 'Solomon conscripted seventy thousand laborers and eighty thousand stonecutters in the hill country, with three thousand six hundred to oversee them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 3, 'Solomon sent word to King Huram of Tyre: "Once you dealt with my father David and sent him cedar to build himself a house to live in.', 'en', 'NRSV-CE', 'Alliance with Huram of Tyre'),
(14, '2 Taw', '2 Chronicles', 2, 4, 'I am now about to build a house for the name of the LORD my God and dedicate it to him for offering fragrant incense before him, and for the regular offering of the rows of bread, and for burnt offerings morning and evening, on the sabbaths and the new moons and the appointed festivals of the LORD our God, as ordained forever for Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 5, 'The house that I am about to build will be great, for our God is greater than other gods.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 6, 'But who is able to build him a house, since heaven, even highest heaven, cannot contain him? Who am I to build a house for him, except as a place to make offerings before him?', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 7, 'So now send me an artisan skilled to work in gold, silver, bronze, and iron, and in purple, crimson, and blue fabrics, trained also in engraving, to join the skilled workers who are with me in Judah and Jerusalem, whom my father David provided.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 8, 'Send me also cedar, cypress, and algum timber from Lebanon, for I know that your servants are skilled in cutting Lebanon timber. My servants will work with your servants', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 9, 'to prepare timber for me in abundance, for the house I am about to build will be great and wonderful.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 10, 'I will provide for your servants, those who cut the timber, twenty thousand cors of crushed wheat, twenty thousand cors of barley, twenty thousand baths of wine, and twenty thousand baths of oil."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 11, 'Then King Huram of Tyre answered in a letter that he sent to Solomon, "Because the LORD loves his people he has made you king over them."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 12, 'Huram also said, "Blessed be the LORD God of Israel, who made heaven and earth, who has given King David a wise son, endowed with discretion and understanding, who will build a temple for the LORD, and a royal palace for himself.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 13, '"I have dispatched Huram-abi, a skilled artisan, endowed with understanding,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 14, 'the son of one of the Danite women, his father a Tyrian. He is trained to work in gold, silver, bronze, iron, stone, and wood, and in purple, blue, and crimson fabrics and fine linen, and to do all sorts of engraving and execute any design that may be assigned him, with your artisans, the artisans of my lord, your father David.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 15, 'Now, as for the wheat, barley, oil, and wine, of which my lord has spoken, let him send them to his servants.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 16, 'We will cut whatever timber you need from Lebanon, and bring it to you as rafts by sea to Joppa; you will take it up to Jerusalem."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 17, 'Then Solomon took a census of all the aliens who were residing in the land of Israel, after the census that his father David had taken; and there were found to be one hundred fifty-three thousand six hundred.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 2, 18, 'Seventy thousand of them he assigned as laborers, eighty thousand as stonecutters in the hill country, and three thousand six hundred as overseers to make the people work.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 3, 1, 'Solomon began to build the house of the LORD in Jerusalem on Mount Moriah, where the LORD had appeared to his father David, at the place that David had designated, on the threshing floor of Ornan the Jebusite.', 'en', 'NRSV-CE', 'Solomon Builds the Temple'),
(14, '2 Taw', '2 Chronicles', 3, 2, 'He began to build on the second day of the second month of the fourth year of his reign.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 3, 'These are Solomon"s measurements for building the house of God: the length, in cubits of the old standard, was sixty cubits, and the width twenty cubits.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 4, 'The vestibule in front of the nave of the house was twenty cubits long, across the width of the house; and its height was one hundred twenty cubits. He overlaid it on the inside with pure gold.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 5, 'The nave he lined with cypress, covered it with fine gold, and made palms and chains on it.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 6, 'He adorned the house with settings of precious stones. The gold was gold from Parvaim.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 7, 'So he lined the house with gold--its beams, its thresholds, its walls, and its doors; and he carved cherubim on the walls.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 8, 'He made the most holy place; its length, corresponding to the width of the house, was twenty cubits, and its width was twenty cubits; he overlaid it with six hundred talents of fine gold.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 9, 'The weight of the nails was fifty shekels of gold. He overlaid the upper chambers with gold.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 10, 'In the most holy place he made two carved cherubim and overlaid them with gold.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 11, 'The wings of the cherubim together extended twenty cubits: one wing of the one, five cubits long, touched the wall of the house, and its other wing, five cubits long, touched the wing of the other cherub;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 12, 'and of this cherub, one wing, five cubits long, touched the wall of the house, and the other wing, also five cubits long, was joined to the wing of the first cherub.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 13, 'The wings of these cherubim extended twenty cubits; the cherubim stood on their feet, facing the nave.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 14, 'And Solomon made the curtain of blue and purple and crimson fabrics and fine linen, and worked cherubim into it.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 15, 'In front of the house he made two pillars thirty-five cubits high, with a capital of five cubits on the top of each.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 16, 'He made encircling chains and put them on the tops of the pillars; and he made one hundred pomegranates, and put them on the chains.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 3, 17, 'He set up the pillars in front of the temple, one on the right, the other on the left; the one on the right he called Jachin, and the one on the left, Boaz.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 4, 1, 'He made an altar of bronze, twenty cubits long, twenty cubits wide, and ten cubits high.', 'en', 'NRSV-CE', 'Furnishings of the Temple'),
(14, '2 Taw', '2 Chronicles', 4, 2, 'Then he made the molten sea; it was round, ten cubits from rim to rim, and five cubits high. A line of thirty cubits would encircle it completely.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 3, 'Under it were panels all around, each of ten cubits, surrounding the sea; there were two rows of panels, cast when it was cast.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 4, 'It stood on twelve oxen, three facing north, three facing west, three facing south, and three facing east; the sea was set on them. The hindquarters of each were toward the inside.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 5, 'Its thickness was a handbreadth; its rim was made like the rim of a cup, like the flower of a lily; it held three thousand baths.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 6, 'He also made ten basins in which to wash, and set five on the right side, and five on the left. In these they were to rinse what was used for the burnt offering. The sea was for the priests to wash in.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 7, 'He made ten golden lampstands as prescribed, and set them in the temple, five on the south side and five on the north.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 8, 'He also made ten tables and placed them in the temple, five on the right side and five on the left. And he made one hundred basins of gold.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 9, 'He made the court of the priests, and the great court, and doors for the court; he overlaid their doors with bronze.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 10, 'He set the sea at the southeast corner of the house.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 11, 'And Huram made the pots, the shovels, and the basins. Thus Huram finished the work that he did for King Solomon on the house of God:', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 12, 'the two pillars, the bowls, and the two capitals on the top of the pillars; and the two latticeworks to cover the two bowls of the capitals that were on the top of the pillars;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 13, 'the four hundred pomegranates for the two latticeworks, two rows of pomegranates for each latticework, to cover the two bowls of the capitals that were on the pillars.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 14, 'He made the stands, the basins on the stands,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 15, 'the one sea, and the twelve oxen underneath it.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 16, 'The pots, the shovels, the forks, and all the equipment for these Huram-abi made of burnished bronze for King Solomon for the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 17, 'In the plain of the Jordan the king cast them, in the clay ground between Succoth and Zeredah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 18, 'Solomon made all these things in great quantities, so that the weight of the bronze was not determined.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 19, 'So Solomon made all the things that were in the house of God: the golden altar, the tables for the bread of the Presence,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 20, 'the lampstands and their lamps of pure gold to burn before the inner sanctuary, as prescribed;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 21, 'the flowers, the lamps, and the tongs, of purest gold;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 4, 22, 'the snuffers, basins, ladles, and firepans, of pure gold. As for the entrance to the temple: the inner doors to the most holy place and the doors of the nave of the temple were of gold.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 5, 1, 'Thus all the work that Solomon did for the house of the LORD was finished. Solomon brought in the things that his father David had dedicated, and stored the silver, the gold, and all the vessels in the treasuries of the house of God.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 2, 'Then Solomon assembled the elders of Israel and all the heads of the tribes, the leaders of the ancestral houses of the people of Israel, in Jerusalem, to bring up the ark of the covenant of the LORD out of the city of David, which is Zion.', 'en', 'NRSV-CE', 'The Ark Brought into the Temple'),
(14, '2 Taw', '2 Chronicles', 5, 3, 'And all the Israelites assembled before the king at the festival that is in the seventh month.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 4, 'And all the elders of Israel came, and the Levites carried the ark.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 5, 'So they brought up the ark, the tent of meeting, and all the holy vessels that were in the tent; the priests and the Levites brought them up.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 6, 'King Solomon and all the congregation of Israel, who had assembled before him, were before the ark, sacrificing so many sheep and oxen that they could not be numbered or counted.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 7, 'Then the priests brought the ark of the covenant of the LORD to its place, in the inner sanctuary of the house, in the most holy place, underneath the wings of the cherubim.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 8, 'For the cherubim spread out their wings over the place of the ark, so that the cherubim made a covering above the ark and its poles.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 9, 'The poles were so long that the ends of the poles were seen from the holy place in front of the inner sanctuary; but they could not be seen from outside; they are there to this day.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 10, 'There was nothing in the ark except the two tablets that Moses put there at Horeb, where the LORD made a covenant with the people of Israel after they came out of Egypt.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 11, 'Now when the priests came out of the holy place (for all the priests who were present had sanctified themselves, without regard to their divisions),', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 12, 'all the levitical singers, Asaph, Heman, and Jeduthun, their sons and kindred, arrayed in fine linen, with cymbals, harps, and lyres, stood east of the altar with one hundred twenty priests who were trumpeters.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 5, 13, 'It was the duty of the trumpeters and singers to make themselves heard in unison in praise and thanksgiving to the LORD, and when the song was raised, with trumpets and cymbals and other musical instruments, in praise to the LORD,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 6, 1, 'Then Solomon said, "The LORD has said that he would reside in thick darkness.', 'en', 'NRSV-CE', 'Dedication of the Temple'),
(14, '2 Taw', '2 Chronicles', 6, 2, 'I have built you an exalted house, a place for you to reside in forever."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 3, 'Then the king turned around and blessed all the assembly of Israel, while all the assembly of Israel stood.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 4, 'And he said, "Blessed be the LORD, the God of Israel, who with his hand has fulfilled what he promised with his mouth to my father David, saying,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 5, '"Since the day that I brought my people out of the land of Egypt, I have not chosen a city from any of the tribes of Israel in which to build a house, so that my name might be there, and I chose no one as ruler over my people Israel;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 6, 'but I have chosen Jerusalem in order that my name may be there, and I have chosen David to be over my people Israel."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 7, 'My father David had it in mind to build a house for the name of the LORD, the God of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 8, 'But the LORD said to my father David, "You did well to consider building a house for my name;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 9, 'nevertheless you shall not build the house, but your son who shall be born to you shall build the house for my name."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 10, 'Now the LORD has fulfilled his promise that he made; for I have succeeded my father David, and sit on the throne of Israel, as the LORD promised, and have built the house for the name of the LORD, the God of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 11, 'There I have set the ark, in which is the covenant of the LORD that he made with the people of Israel."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 12, 'Then Solomon stood before the altar of the LORD in the presence of the whole assembly of Israel, and spread out his hands.', 'en', 'NRSV-CE', 'Solomon"s Prayer of Dedication'),
(14, '2 Taw', '2 Chronicles', 6, 13, 'Solomon had made a bronze platform five cubits long, five cubits wide, and three cubits high, and had set it in the court; and he stood on it. Then he knelt on his knees in the presence of the whole assembly of Israel, and spread out his hands toward heaven.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 14, 'He said, "O LORD, God of Israel, there is no God like you, in heaven or on earth, keeping covenant in steadfast love with your servants who walk before you with all their heart--', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 15, 'you who have kept for your servant, my father David, what you promised to him. Indeed, you promised with your mouth and this day have fulfilled with your hand.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 16, 'Therefore, O LORD, God of Israel, keep for your servant, my father David, that which you promised him, saying, "There shall never fail you a successor before me to sit on the throne of Israel, if only your children keep to their way, to walk in my law as you have walked before me."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 17, 'Therefore, O LORD, God of Israel, let your word be confirmed, which you promised to your servant David.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 18, '"But will God indeed reside with mortals on earth? Even heaven and the highest heaven cannot contain you, how much less this house that I have built!', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 19, 'Regard your servant"s prayer and his plea, O LORD my God, heeding the cry and the prayer that your servant prays to you.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 20, 'May your eyes be open day and night toward this house, the place where you promised to set your name, and may you heed the prayer that your servant prays toward this place.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 21, 'And hear the plea of your servant and of your people Israel, when they pray toward this place; may you hear from heaven your dwelling place; hear and forgive.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 22, '"If someone sins against another and is required to take an oath and comes and swears before your altar in this house,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 23, 'may you hear from heaven, and act, and judge your servants, repaying the guilty by bringing their conduct on their own head, and vindicating those who are in the right by rewarding them in accordance with their righteousness.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 24, '"When your people Israel, having sinned against you, are defeated before an enemy but turn again to you, confess your name, pray and plead with you in this house,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 25, 'may you hear from heaven, and forgive the sin of your people Israel, and bring them again to the land that you gave to them and to their ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 26, '"When heaven is shut up and there is no rain because they have sinned against you, and then they pray toward this place, confess your name, and turn from their sin, because you punish them,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 27, 'may you hear in heaven, forgive the sin of your servants, your people Israel, when you teach them the good way in which they should walk; and send down rain upon your land, which you have given to your people as an inheritance.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 28, '"If there is famine in the land, if there is plague, blight, mildew, locust, or caterpillar; if their enemies besiege them in any of the settlements of the lands; whatever suffering, whatever sickness there is;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 29, 'whatever prayer, whatever plea from any individual or from all your people Israel, all knowing their own suffering and their own sorrows so that they stretch out their hands toward this house;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 30, 'may you hear from heaven, your dwelling place, forgive, and render to all whose heart you know, according to all their ways, for only you know the human heart.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 31, 'Thus may they fear you and walk in your ways all the days that they live in the land that you gave to our ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 32, '"Likewise when foreigners, who are not of your people Israel, come from a distant land because of your great name, and your mighty hand, and your outstretched arm, when they come and pray toward this house,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 33, 'may you hear from heaven your dwelling place, and do whatever the foreigners ask of you, in order that all the peoples of the earth may know your name and fear you, as do your people Israel, and that they may know that your name has been invoked on this house that I have built.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 34, '"If your people go out to battle against their enemies, by whatever way you shall send them, and they pray to you toward this city that you have chosen and the house that I have built for your name,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 35, 'then hear from heaven their prayer and their plea, and maintain their cause.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 36, '"If they sin against you--for there is no one who does not sin--and you are angry with them and give them to an enemy, so that they are carried away captive to a land far or near;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 37, 'then if they come to their senses in the land to which they have been taken captive, and repent, and plead with you in the land of their captivity, saying, "We have sinned, and have done wrong; we have acted wickedly";', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 38, 'if they repent with all their heart and soul in the land of their captivity, to which they were taken captive, and pray toward their land, which you gave to their ancestors, the city that you have chosen, and the house that I have built for your name,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 39, 'then hear from heaven your dwelling place their prayer and their pleas, maintain their cause and forgive your people who have sinned against you.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 40, 'Now, O my God, let your eyes be open and your ears attentive to prayer from this place.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 6, 41, '"Now rise up, O LORD God, and go to your resting place,  
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 7, 1, 'When Solomon had ended his prayer, fire came down from heaven and consumed the burnt offering and the sacrifices; and the glory of the LORD filled the temple.', 'en', 'NRSV-CE', 'Solomon Dedicates the Temple'),
(14, '2 Taw', '2 Chronicles', 7, 2, 'The priests could not enter the house of the LORD, because the glory of the LORD filled the LORD"s house.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 7, 3, 'When all the people of Israel saw the fire come down and the glory of the LORD on the temple, they bowed down on the pavement with their faces to the ground, and worshiped and gave thanks to the LORD, saying,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 8, 1, 'At the end of twenty years, during which Solomon had built the house of the LORD and his own house,', 'en', 'NRSV-CE', 'Various Activities of Solomon'),
(14, '2 Taw', '2 Chronicles', 8, 2, 'Solomon rebuilt the cities that Huram had given to him, and settled the people of Israel in them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 3, 'Solomon went to Hamath-zobah, and captured it.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 4, 'He built Tadmor in the wilderness and all the storage towns that he built in Hamath.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 5, 'He also built Upper Beth-horon and Lower Beth-horon, fortified cities, with walls, gates, and bars,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 6, 'and Baalath, as well as all Solomon"s storage towns, and all the towns for his chariots, the towns for his cavalry, and whatever Solomon desired to build, in Jerusalem, in Lebanon, and in all the land of his dominion.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 7, 'All the people who were left of the Hittites, the Amorites, the Perizzites, the Hivites, and the Jebusites, who were not of Israel,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 8, 'from their descendants who were still left in the land, whom the people of Israel had not destroyed--these Solomon conscripted for forced labor, as is still the case today.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 9, 'But of the people of Israel Solomon made no slaves for his work; they were soldiers, and his officers, the commanders of his chariotry and cavalry.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 10, 'These were the chief officers of King Solomon, two hundred fifty of them, who exercised authority over the people.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 11, 'Solomon brought Pharaoh"s daughter from the city of David to the house that he had built for her, for he said, "My wife shall not live in the house of King David of Israel, for the places to which the ark of the LORD has come are holy."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 12, 'Then Solomon offered up burnt offerings to the LORD on the altar of the LORD that he had built in front of the vestibule,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 13, 'as the duty of each day required, offering according to the commandment of Moses for the sabbaths, the new moons, and the three annual festivals--the festival of unleavened bread, the festival of weeks, and the festival of booths.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 14, 'According to the ordinance of his father David, he appointed the divisions of the priests for their service, and the Levites for their offices of praise and ministry alongside the priests as the duty of each day required, and the gatekeepers in their divisions for the several gates; for so David the man of God had commanded.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 15, 'They did not turn away from what the king had commanded the priests and Levites regarding anything at all, or regarding the treasuries.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 16, 'Thus all the work of Solomon was accomplished from the day the foundation of the house of the LORD was laid until the house of the LORD was finished completely.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 17, 'Then Solomon went to Ezion-geber and Eloth on the shore of the sea, in the land of Edom.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 8, 18, 'Huram sent him, in the care of his servants, ships and servants familiar with the sea. They went to Ophir, together with the servants of Solomon, and imported from there four hundred fifty talents of gold and brought it to King Solomon.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 9, 1, 'When the queen of Sheba heard of the fame of Solomon, she came to Jerusalem to test him with hard questions, having a very great retinue and camels bearing spices and very much gold and precious stones. When she came to Solomon, she discussed with him all that was on her mind.', 'en', 'NRSV-CE', 'Visit of the Queen of Sheba'),
(14, '2 Taw', '2 Chronicles', 9, 2, 'Solomon answered all her questions; there was nothing hidden from Solomon that he could not explain to her.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 3, 'When the queen of Sheba had observed the wisdom of Solomon, the house that he had built,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 4, 'the food of his table, the seating of his officials, and the attendance of his servants, and their clothing, his valets, and their clothing, and his burnt offerings that he offered at the house of the LORD, there was no more spirit left in her.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 5, 'So she said to the king, "The report was true that I heard in my own land of your accomplishments and of your wisdom,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 6, 'but I did not believe the reports until I came and my own eyes saw it. Not even half of the greatness of your wisdom had been told to me; you far surpass the report that I had heard.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 7, 'Happy are your people! Happy are these your servants, who continually attend you and hear your wisdom!', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 8, 'Blessed be the LORD your God, who has delighted in you and set you on his throne as king for the LORD your God. Because your God loved Israel and would establish them forever, he has made you king over them, that you may execute justice and righteousness."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 9, 'Then she gave the king one hundred twenty talents of gold, a very great quantity of spices, and precious stones: there were no spices such as those that the queen of Sheba gave to King Solomon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 10, 'Moreover the servants of Huram and the servants of Solomon who brought gold from Ophir brought algum wood and precious stones.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 11, 'From the algum wood, the king made steps for the house of the LORD and for the king"s house, lyres also and harps for the singers; there never was seen the like of them before in the land of Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 12, 'Meanwhile King Solomon granted the queen of Sheba every desire that she expressed, well beyond what she had brought to the king. Then she returned to her own land, with her servants.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 13, 'The weight of gold that came to Solomon in one year was six hundred sixty-six talents of gold,', 'en', 'NRSV-CE', 'Solomon"s Great Wealth'),
(14, '2 Taw', '2 Chronicles', 9, 14, 'besides that which the traders and merchants brought; and all the kings of Arabia and the governors of the land brought gold and silver to Solomon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 15, 'King Solomon made two hundred large shields of beaten gold; six hundred shekels of beaten gold went into each large shield.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 16, 'He made three hundred shields of beaten gold; three hundred shekels of gold went into each shield; and the king put them in the House of the Forest of Lebanon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 17, 'The king also made a great ivory throne, and overlaid it with pure gold.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 18, 'The throne had six steps and a footstool of gold, which were attached to the throne, and on each side of the seat were arm rests and two lions standing beside the arm rests,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 19, 'while twelve lions were standing, one on each end of a step on the six steps. The like of it was never made in any kingdom.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 20, 'All King Solomon"s drinking vessels were of gold, and all the vessels of the House of the Forest of Lebanon were of pure gold; silver was not considered as anything in the days of Solomon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 21, 'For the king"s ships went to Tarshish with the servants of Huram; once every three years the ships of Tarshish used to come bringing gold, silver, ivory, apes, and peacocks.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 22, 'Thus King Solomon excelled all the kings of the earth in riches and in wisdom.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 23, 'All the kings of the earth sought the presence of Solomon to hear his wisdom, which God had put into his mind.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 24, 'Every one of them brought a present, objects of silver and gold, garments, weaponry, spices, horses, and mules, so much year by year.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 25, 'Solomon had four thousand stalls for horses and chariots, and twelve thousand horses, which he stationed in the chariot cities and with the king in Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 26, 'He ruled over all the kings from the Euphrates to the land of the Philistines, and to the border of Egypt.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 27, 'The king made silver as common in Jerusalem as stone, and cedar as plentiful as the sycamore of the Shephelah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 28, 'Horses were imported for Solomon from Egypt and from all lands.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 29, 'Now the rest of the acts of Solomon, from first to last, are they not written in the history of the prophet Nathan, and in the prophecy of Ahijah the Shilonite, and in the visions of the seer Iddo concerning Jeroboam son of Nebat?', 'en', 'NRSV-CE', 'Death of Solomon'),
(14, '2 Taw', '2 Chronicles', 9, 30, 'Solomon reigned in Jerusalem over all Israel forty years.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 9, 31, 'Solomon slept with his ancestors and was buried in the city of his father David; and his son Rehoboam succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 10, 1, 'Rehoboam went to Shechem, for all Israel had come to Shechem to make him king.', 'en', 'NRSV-CE', 'The Revolt against Rehoboam'),
(14, '2 Taw', '2 Chronicles', 10, 2, 'When Jeroboam son of Nebat heard of it (for he was in Egypt, where he had fled from King Solomon), then Jeroboam returned from Egypt.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 3, 'They sent and called him; and Jeroboam and all Israel came and said to Rehoboam,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 4, '"Your father made our yoke heavy. Now therefore lighten the hard service of your father and his heavy yoke that he placed on us, and we will serve you."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 5, 'He said to them, "Come to me again in three days." So the people went away.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 6, 'Then King Rehoboam took counsel with the older men who had attended his father Solomon while he was still alive, saying, "How do you advise me to answer this people?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 7, 'They answered him, "If you will be kind to this people and please them, and speak good words to them, then they will be your servants forever."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 8, 'But he rejected the advice that the older men gave him, and consulted the young men who had grown up with him and now attended him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 9, 'He said to them, "What do you advise that we answer this people who have said to me, "Lighten the yoke that your father put on us"?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 10, 'The young men who had grown up with him said to him, "Thus should you speak to the people who said to you, "Your father made our yoke heavy, but you must lighten it for us"; tell them, "My little finger is thicker than my father"s loins.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 11, 'Now, whereas my father laid on you a heavy yoke, I will add to your yoke. My father disciplined you with whips, but I will discipline you with scorpions.""', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 12, 'So Jeroboam and all the people came to Rehoboam the third day, as the king had said, "Come to me again the third day."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 13, 'The king answered them harshly. King Rehoboam rejected the advice of the older men;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 14, 'he spoke to them in accordance with the advice of the young men, "My father made your yoke heavy, but I will add to it; my father disciplined you with whips, but I will discipline you with scorpions."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 15, 'So the king did not listen to the people, because it was a turn of affairs brought about by God so that the LORD might fulfill his word, which he had spoken by Ahijah the Shilonite to Jeroboam son of Nebat.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 10, 16, 'When all Israel saw that the king would not listen to them, the people answered the king,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 11, 1, 'When Rehoboam came to Jerusalem, he assembled one hundred eighty thousand chosen troops of the house of Judah and Benjamin to fight against Israel, to restore the kingdom to Rehoboam.', 'en', 'NRSV-CE', 'Judah and Benjamin Fortified'),
(14, '2 Taw', '2 Chronicles', 11, 2, 'But the word of the LORD came to Shemaiah the man of God:', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 3, 'Say to King Rehoboam of Judah, son of Solomon, and to all Israel in Judah and Benjamin,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 4, '"Thus says the LORD: You shall not go up or fight against your kindred. Let everyone return home, for this thing is from me." So they heeded the word of the LORD and turned back from the expedition against Jeroboam.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 5, 'Rehoboam resided in Jerusalem, and he built cities for defense in Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 6, 'He built up Bethlehem, Etam, Tekoa,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 7, 'Beth-zur, Soco, Adullam,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 8, 'Gath, Mareshah, Ziph,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 9, 'Adoraim, Lachish, Azekah,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 10, 'Zorah, Aijalon, and Hebron, fortified cities that are in Judah and in Benjamin.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 11, 'He made the fortresses strong, and put commanders in them, and stores of food, oil, and wine.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 12, 'He also put large shields and spears in all the cities, and made them very strong. So he held Judah and Benjamin.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 13, 'The priests and the Levites who were in all Israel presented themselves to him from all their territories.', 'en', 'NRSV-CE', 'Priests and Levites Support Rehoboam'),
(14, '2 Taw', '2 Chronicles', 11, 14, 'The Levites had left their common lands and their holdings and had come to Judah and Jerusalem, because Jeroboam and his sons had prevented them from serving as priests of the LORD,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 15, 'and had appointed his own priests for the high places, and for the goat-demons, and for the calves that he had made.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 16, 'Those who had set their hearts to seek the LORD God of Israel came after them from all the tribes of Israel to Jerusalem to sacrifice to the LORD, the God of their ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 17, 'They strengthened the kingdom of Judah, and for three years they made Rehoboam son of Solomon secure, for they walked for three years in the way of David and Solomon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 18, 'Rehoboam took as his wife Mahalath daughter of Jerimoth son of David, and of Abihail daughter of Eliab son of Jesse.', 'en', 'NRSV-CE', 'Rehoboam"s Marriages'),
(14, '2 Taw', '2 Chronicles', 11, 19, 'She bore him sons: Jeush, Shemariah, and Zaham.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 20, 'After her he took Maacah daughter of Absalom, who bore him Abijah, Attai, Ziza, and Shelomith.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 21, 'Rehoboam loved Maacah daughter of Absalom more than all his other wives and concubines (he took eighteen wives and sixty concubines, and became the father of twenty-eight sons and sixty daughters).', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 22, 'Rehoboam appointed Abijah son of Maacah as chief prince among his brothers, for he intended to make him king.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 11, 23, 'He dealt wisely, and distributed some of his sons through all the districts of Judah and Benjamin, in all the fortified cities; he gave them abundant provisions, and found many wives for them.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 12, 1, 'When the rule of Rehoboam was established and he grew strong, he abandoned the law of the LORD, he and all Israel with him.', 'en', 'NRSV-CE', 'Egypt Attacks Judah'),
(14, '2 Taw', '2 Chronicles', 12, 2, 'In the fifth year of King Rehoboam, because they had been unfaithful to the LORD, King Shishak of Egypt came up against Jerusalem', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 3, 'with twelve hundred chariots and sixty thousand cavalry. A countless army came with him from Egypt--Libyans, Sukkiim, and Ethiopians.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 4, 'He took the fortified cities of Judah and came as far as Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 5, 'Then the prophet Shemaiah came to Rehoboam and to the officers of Judah, who had gathered at Jerusalem because of Shishak, and said to them, "Thus says the LORD: You abandoned me, so I have abandoned you to the hand of Shishak."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 6, 'Then the officers of Israel and the king humbled themselves and said, "The LORD is in the right."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 7, 'When the LORD saw that they humbled themselves, the word of the LORD came to Shemaiah, saying: "They have humbled themselves; I will not destroy them, but I will grant them some deliverance, and my wrath shall not be poured out on Jerusalem by the hand of Shishak.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 8, 'Nevertheless they shall be his servants, so that they may know the difference between serving me and serving the kingdoms of other lands."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 9, 'So King Shishak of Egypt came up against Jerusalem; he took away the treasures of the house of the LORD and the treasures of the king"s house; he took everything. He also took away the shields of gold that Solomon had made;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 10, 'but King Rehoboam made in place of them shields of bronze, and committed them to the hands of the officers of the guard, who kept the door of the king"s house.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 11, 'Whenever the king went into the house of the LORD, the guard would come along bearing them, and would then bring them back to the guardroom.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 12, 'Because he humbled himself the wrath of the LORD turned from him, so as not to destroy them completely; moreover, conditions were good in Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 13, 'So King Rehoboam established himself in Jerusalem and reigned. Rehoboam was forty-one years old when he began to reign; he reigned seventeen years in Jerusalem, the city that the LORD had chosen out of all the tribes of Israel to put his name there. His mother"s name was Naamah the Ammonite.', 'en', 'NRSV-CE', 'Death of Rehoboam'),
(14, '2 Taw', '2 Chronicles', 12, 14, 'He did evil, for he did not set his heart to seek the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 15, 'Now the acts of Rehoboam, from first to last, are they not written in the records of the prophet Shemaiah and of the seer Iddo, recorded by genealogy? There were continual wars between Rehoboam and Jeroboam.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 12, 16, 'Rehoboam slept with his ancestors and was buried in the city of David; and his son Abijah succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 13, 1, 'In the eighteenth year of King Jeroboam, Abijah began to reign over Judah.', 'en', 'NRSV-CE', 'Abijah Reigns over Judah'),
(14, '2 Taw', '2 Chronicles', 13, 2, 'He reigned for three years in Jerusalem. His mother"s name was Micaiah daughter of Uriel of Gibeah.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 14, 1, 'So Abijah slept with his ancestors, and they buried him in the city of David. His son Asa succeeded him. In his days the land had rest for ten years.', 'en', 'NRSV-CE', 'Asa Reigns'),
(14, '2 Taw', '2 Chronicles', 14, 2, 'Asa did what was good and right in the sight of the LORD his God.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 3, 'He took away the foreign altars and the high places, broke down the pillars, hewed down the sacred poles,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 4, 'and commanded Judah to seek the LORD, the God of their ancestors, and to keep the law and the commandment.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 5, 'He also removed from all the cities of Judah the high places and the incense altars. And the kingdom had rest under him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 6, 'He built fortified cities in Judah while the land had rest. He had no war in those years, for the LORD gave him peace.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 7, 'He said to Judah, "Let us build these cities, and surround them with walls and towers, gates and bars; the land is still ours because we have sought the LORD our God; we have sought him, and he has given us peace on every side." So they built and prospered.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 8, 'Asa had an army of three hundred thousand from Judah, armed with large shields and spears, and two hundred eighty thousand troops from Benjamin who carried shields and drew bows; all these were mighty warriors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 9, 'Zerah the Ethiopian came out against them with an army of a million men and three hundred chariots, and came as far as Mareshah.', 'en', 'NRSV-CE', 'Ethiopian Invasion Repulsed'),
(14, '2 Taw', '2 Chronicles', 14, 10, 'Asa went out to meet him, and they drew up their lines of battle in the valley of Zephathah at Mareshah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 11, 'Asa cried to the LORD his God, "O LORD, there is no difference for you between helping the mighty and the weak. Help us, O LORD our God, for we rely on you, and in your name we have come against this multitude. O LORD, you are our God; let no mortal prevail against you."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 12, 'So the LORD defeated the Ethiopians before Asa and before Judah, and the Ethiopians fled.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 13, 'Asa and the army with him pursued them as far as Gerar, and the Ethiopians fell until no one remained alive; for they were broken before the LORD and his army. The people of Judah carried away a great quantity of booty.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 14, 'They defeated all the cities around Gerar, for the fear of the LORD was on them. They plundered all the cities; for there was much plunder in them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 14, 15, 'They also attacked the tents of those who had livestock, and carried away sheep and goats in abundance, and camels. Then they returned to Jerusalem.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 15, 1, 'The spirit of God came upon Azariah son of Oded.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 2, 'He went out to meet Asa and said to him, "Hear me, Asa, and all Judah and Benjamin: The LORD is with you, while you are with him. If you seek him, he will be found by you, but if you abandon him, he will abandon you.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 3, 'For a long time Israel was without the true God, and without a teaching priest, and without law;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 4, 'but when in their distress they turned to the LORD, the God of Israel, and sought him, he was found by them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 5, 'In those times it was not safe for anyone to go or come, for great disturbances afflicted all the inhabitants of the lands.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 6, 'They were broken in pieces, nation against nation and city against city, for God troubled them with every sort of distress.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 7, 'But you, take courage! Do not let your hands be weak, for your work shall be rewarded."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 8, 'When Asa heard these words, the prophecy of Azariah son of Oded, he took courage, and put away the abominable idols from all the land of Judah and Benjamin and from the towns that he had taken in the hill country of Ephraim. He repaired the altar of the LORD that was in front of the vestibule of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 9, 'He gathered all Judah and Benjamin, and those from Ephraim, Manasseh, and Simeon who were residing as aliens with them, for great numbers had deserted to him from Israel when they saw that the LORD his God was with him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 10, 'They were gathered at Jerusalem in the third month of the fifteenth year of the reign of Asa.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 11, 'They sacrificed to the LORD on that day, from the booty that they had brought, seven hundred oxen and seven thousand sheep.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 12, 'They entered into a covenant to seek the LORD, the God of their ancestors, with all their heart and with all their soul.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 13, 'Whoever would not seek the LORD, the God of Israel, should be put to death, whether young or old, man or woman.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 14, 'They took an oath to the LORD with a loud voice, and with shouting, and with trumpets, and with horns.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 15, 'All Judah rejoiced over the oath; for they had sworn with all their heart, and had sought him with their whole desire, and he was found by them, and the LORD gave them rest all around.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 16, 'King Asa even removed his mother Maacah from being queen mother because she had made an abominable image for Asherah. Asa cut down her image, crushed it, and burned it at the Wadi Kidron.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 17, 'But the high places were not taken out of Israel. Nevertheless the heart of Asa was true all his days.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 18, 'He brought into the house of God the votive gifts of his father and his own votive gifts--silver, gold, and utensils.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 15, 19, 'And there was no more war until the thirty-fifth year of the reign of Asa.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 16, 1, 'In the thirty-sixth year of the reign of Asa, King Baasha of Israel went up against Judah, and built Ramah, to prevent anyone from going out or coming into the territory of King Asa of Judah.', 'en', 'NRSV-CE', 'Alliance with Aram Condemned'),
(14, '2 Taw', '2 Chronicles', 16, 2, 'Then Asa took silver and gold from the treasures of the house of the LORD and the king"s house, and sent them to King Ben-hadad of Aram, who resided in Damascus, saying,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 3, '"Let there be an alliance between me and you, like that between my father and your father; I am sending to you silver and gold; go, break your alliance with King Baasha of Israel, so that he may withdraw from me."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 4, 'Ben-hadad listened to King Asa, and sent the commanders of his armies against the cities of Israel. They conquered Ijon, Dan, Abel-maim, and all the store-cities of Naphtali.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 5, 'When Baasha heard of it, he stopped building Ramah, and let his work cease.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 6, 'Then King Asa brought all Judah, and they carried away the stones of Ramah and its timber, with which Baasha had been building, and with them he built up Geba and Mizpah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 7, 'At that time the seer Hanani came to King Asa of Judah, and said to him, "Because you relied on the king of Aram, and did not rely on the LORD your God, the army of the king of Aram has escaped you.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 8, 'Were not the Ethiopians and the Libyans a huge army with exceedingly many chariots and cavalry? Yet because you relied on the LORD, he gave them into your hand.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 9, 'For the eyes of the LORD range throughout the entire earth, to strengthen those whose heart is true to him. You have done foolishly in this; for from now on you will have wars."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 10, 'Then Asa was angry with the seer, and put him in the stocks, in prison, for he was in a rage with him because of this. And Asa inflicted cruelties on some of the people at the same time.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 11, 'The acts of Asa, from first to last, are written in the Book of the Kings of Judah and Israel.', 'en', 'NRSV-CE', 'Asa"s Disease and Death'),
(14, '2 Taw', '2 Chronicles', 16, 12, 'In the thirty-ninth year of his reign Asa was diseased in his feet, and his disease became severe; yet even in his disease he did not seek the LORD, but sought help from physicians.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 13, 'Then Asa slept with his ancestors, dying in the forty-first year of his reign.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 16, 14, 'They buried him in the tomb that he had hewn out for himself in the city of David. They laid him on a bier that had been filled with various kinds of spices prepared by the perfumer"s art; and they made a very great fire in his honor.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 17, 1, 'His son Jehoshaphat succeeded him, and strengthened himself against Israel.', 'en', 'NRSV-CE', 'Jehoshaphat"s Reign'),
(14, '2 Taw', '2 Chronicles', 17, 2, 'He placed forces in all the fortified cities of Judah, and set garrisons in the land of Judah, and in the cities of Ephraim that his father Asa had taken.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 3, 'The LORD was with Jehoshaphat, because he walked in the earlier ways of his father; he did not seek the Baals,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 4, 'but sought the God of his father and walked in his commandments, and not according to the ways of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 5, 'Therefore the LORD established the kingdom in his hand. All Judah brought tribute to Jehoshaphat, and he had great riches and honor.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 6, 'His heart was courageous in the ways of the LORD; and furthermore he removed the high places and the sacred poles from Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 7, 'In the third year of his reign he sent his officials, Ben-hail, Obadiah, Zechariah, Nethanel, and Micaiah, to teach in the cities of Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 8, 'With them were the Levites, Shemaiah, Nethaniah, Zebadiah, Asahel, Shemiramoth, Jehonathan, Adonijah, Tobijah, and Tob-adonijah; and with these Levites, the priests Elishama and Jehoram.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 9, 'They taught in Judah, having the book of the law of the LORD with them; they went around through all the cities of Judah and taught among the people.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 10, 'The fear of the LORD fell on all the kingdoms of the lands around Judah, and they did not make war against Jehoshaphat.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 11, 'Some of the Philistines brought Jehoshaphat presents, and silver for tribute; and the Arabs also brought him seven thousand seven hundred rams and seven thousand seven hundred male goats.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 12, 'Jehoshaphat grew steadily greater. He built fortresses and storage cities in Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 13, 'He carried out great works in the cities of Judah. He had soldiers, mighty warriors, in Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 14, 'This was the muster of them by ancestral houses: Of Judah, the commanders of the thousands: Adnah the commander, with three hundred thousand mighty warriors,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 15, 'and next to him Jehohanan the commander, with two hundred eighty thousand,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 16, 'and next to him Amasiah son of Zichri, a volunteer for the service of the LORD, with two hundred thousand mighty warriors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 17, 'Of Benjamin: Eliada, a mighty warrior, with two hundred thousand armed with bow and shield,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 18, 'and next to him Jehozabad with one hundred eighty thousand armed for war.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 17, 19, 'These were in the service of the king, besides those whom the king had placed in the fortified cities throughout all Judah.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 18, 1, 'Now Jehoshaphat had great riches and honor; and he made a marriage alliance with Ahab.', 'en', 'NRSV-CE', 'Micaiah Predicts Failure'),
(14, '2 Taw', '2 Chronicles', 18, 2, 'After some years he went down to Ahab in Samaria. Ahab slaughtered an abundance of sheep and oxen for him and for the people who were with him, and induced him to go up against Ramoth-gilead.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 3, 'King Ahab of Israel said to King Jehoshaphat of Judah, "Will you go with me to Ramoth-gilead?" He answered him, "I am with you, my people are your people. We will be with you in the war."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 4, 'But Jehoshaphat also said to the king of Israel, "Inquire first for the word of the LORD."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 5, 'Then the king of Israel gathered the prophets together, four hundred of them, and said to them, "Shall we go to battle against Ramoth-gilead, or shall I refrain?" They said, "Go up; for God will give it into the hand of the king."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 6, 'But Jehoshaphat said, "Is there no other prophet of the LORD here of whom we may inquire?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 7, 'The king of Israel said to Jehoshaphat, "There is still one other by whom we may inquire of the LORD, Micaiah son of Imlah; but I hate him, for he never prophesies anything favorable about me, but only disaster." Jehoshaphat said, "Let the king not say such a thing."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 8, 'Then the king of Israel summoned an officer and said, "Bring quickly Micaiah son of Imlah."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 9, 'Now the king of Israel and King Jehoshaphat of Judah were sitting on their thrones, arrayed in their robes; and they were sitting at the threshing floor at the entrance of the gate of Samaria; and all the prophets were prophesying before them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 10, 'Zedekiah son of Chenaanah made for himself horns of iron, and he said, "Thus says the LORD: With these you shall gore the Arameans until they are destroyed."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 11, 'All the prophets were prophesying the same and saying, "Go up to Ramoth-gilead and triumph; the LORD will give it into the hand of the king."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 12, 'The messenger who had gone to summon Micaiah said to him, "Look, the words of the prophets with one accord are favorable to the king; let your word be like the word of one of them, and speak favorably."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 13, 'But Micaiah said, "As the LORD lives, whatever my God says, that I will speak."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 14, 'When he had come to the king, the king said to him, "Micaiah, shall we go to Ramoth-gilead to battle, or shall I refrain?" He answered, "Go up and triumph; they will be given into your hand."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 15, 'But the king said to him, "How many times must I make you swear to tell me nothing but the truth in the name of the LORD?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 16, 'Then Micaiah said, "I saw all Israel scattered on the mountains, like sheep without a shepherd; and the LORD said, "These have no master; let each one go home in peace.""', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 17, 'The king of Israel said to Jehoshaphat, "Did I not tell you that he would not prophesy anything favorable about me, but only disaster?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 18, 'Then Micaiah said, "Therefore hear the word of the LORD: I saw the LORD sitting on his throne, with all the host of heaven standing to the right and to the left of him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 19, 'And the LORD said, "Who will entice King Ahab of Israel, so that he may go up and fall at Ramoth-gilead?" Then one said one thing, and another said another,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 20, 'until a spirit came forward and stood before the LORD, saying, "I will entice him." The LORD asked him, "How?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 21, 'He replied, "I will go out and be a lying spirit in the mouth of all his prophets." Then the LORD said, "You are to entice him, and you shall succeed; go out and do it."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 22, 'So you see, the LORD has put a lying spirit in the mouth of these your prophets; the LORD has decreed disaster for you."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 23, 'Then Zedekiah son of Chenaanah came up to Micaiah, slapped him on the cheek, and said, "Which way did the spirit of the LORD pass from me to speak to you?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 24, 'Micaiah replied, "You will find out on that day when you go in to hide in an inner chamber."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 25, 'The king of Israel then ordered, "Take Micaiah, and return him to Amon the governor of the city and to Joash the king"s son;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 26, 'and say, "Thus says the king: Put this fellow in prison, and feed him on reduced rations of bread and water until I return in peace.""', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 27, 'Micaiah said, "If you return in peace, the LORD has not spoken by me." And he said, "Hear, you peoples, all of you!"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 28, 'So the king of Israel and King Jehoshaphat of Judah went up to Ramoth-gilead.', 'en', 'NRSV-CE', 'Defeat and Death of Ahab'),
(14, '2 Taw', '2 Chronicles', 18, 29, 'The king of Israel said to Jehoshaphat, "I will disguise myself and go into battle, but you wear your robes." So the king of Israel disguised himself, and they went into battle.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 30, 'Now the king of Aram had commanded the captains of his chariots, "Fight with no one small or great, but only with the king of Israel."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 31, 'When the captains of the chariots saw Jehoshaphat, they said, "It is the king of Israel." So they turned to fight against him; and Jehoshaphat cried out, and the LORD helped him. God drew them away from him,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 32, 'for when the captains of the chariots saw that it was not the king of Israel, they turned back from pursuing him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 33, 'But a certain man drew his bow and unknowingly struck the king of Israel between the scale armor and the breastplate; so he said to the driver of his chariot, "Turn around, and carry me out of the battle, for I am wounded."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 18, 34, 'The battle grew hot that day, and the king of Israel propped himself up in his chariot facing the Arameans until evening; then at sunset he died.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 19, 1, 'King Jehoshaphat of Judah returned in safety to his house in Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 19, 2, 'Jehu son of Hanani the seer went out to meet him and said to King Jehoshaphat, "Should you help the wicked and love those who hate the LORD? Because of this, wrath has gone out against you from the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 19, 3, 'Nevertheless, some good is found in you, for you destroyed the sacred poles out of the land, and have set your heart to seek God."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 19, 4, 'Jehoshaphat resided at Jerusalem; then he went out again among the people, from Beer-sheba to the hill country of Ephraim, and brought them back to the LORD, the God of their ancestors.', 'en', 'NRSV-CE', 'The Reforms of Jehoshaphat'),
(14, '2 Taw', '2 Chronicles', 19, 5, 'He appointed judges in the land in all the fortified cities of Judah, city by city,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 19, 6, 'and said to the judges, "Consider what you are doing, for you judge not on behalf of human beings but on the LORD"s behalf; he is with you in giving judgment.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 19, 7, 'Now, let the fear of the LORD be upon you; take care what you do, for there is no perversion of justice with the LORD our God, or partiality, or taking of bribes."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 19, 8, 'Moreover in Jerusalem Jehoshaphat appointed certain Levites and priests and heads of families of Israel, to give judgment for the LORD and to decide disputed cases. They had their seat at Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 19, 9, 'He charged them: "This is how you shall act: in the fear of the LORD, in faithfulness, and with your whole heart;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 19, 10, 'whenever a case comes to you from your kindred who live in their cities, concerning bloodshed, law or commandment, statutes or ordinances, then you shall instruct them, so that they may not incur guilt before the LORD and wrath may not come on you and your kindred. Do so, and you will not incur guilt.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 19, 11, 'See, Amariah the chief priest is over you in all matters of the LORD; and Zebadiah son of Ishmael, the governor of the house of Judah, in all the king"s matters; and the Levites will serve you as officers. Deal courageously, and may the LORD be with the good!"', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 20, 1, 'After this the Moabites and Ammonites, and with them some of the Meunites, came against Jehoshaphat for battle.', 'en', 'NRSV-CE', 'Invasion from the East'),
(14, '2 Taw', '2 Chronicles', 20, 2, 'Messengers came and told Jehoshaphat, "A great multitude is coming against you from Edom, from beyond the sea; already they are at Hazazon-tamar" (that is, En-gedi).', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 3, 'Jehoshaphat was afraid; he set himself to seek the LORD, and proclaimed a fast throughout all Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 4, 'Judah assembled to seek help from the LORD; from all the towns of Judah they came to seek the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 5, 'Jehoshaphat stood in the assembly of Judah and Jerusalem, in the house of the LORD, before the new court,', 'en', 'NRSV-CE', 'Jehoshaphat"s Prayer and Victory'),
(14, '2 Taw', '2 Chronicles', 20, 6, 'and said, "O LORD, God of our ancestors, are you not God in heaven? Do you not rule over all the kingdoms of the nations? In your hand are power and might, so that no one is able to withstand you.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 7, 'Did you not, O our God, drive out the inhabitants of this land before your people Israel, and give it forever to the descendants of your friend Abraham?', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 8, 'They have lived in it, and in it have built you a sanctuary for your name, saying,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 9, '"If disaster comes upon us, the sword, judgment, or pestilence, or famine, we will stand before this house, and before you, for your name is in this house, and cry to you in our distress, and you will hear and save."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 10, 'See now, the people of Ammon, Moab, and Mount Seir, whom you would not let Israel invade when they came from the land of Egypt, and whom they avoided and did not destroy--', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 11, 'they reward us by coming to drive us out of your possession that you have given us to inherit.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 12, 'O our God, will you not execute judgment upon them? For we are powerless against this great multitude that is coming against us. We do not know what to do, but our eyes are on you."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 13, 'Meanwhile all Judah stood before the LORD, with their little ones, their wives, and their children.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 14, 'Then the spirit of the LORD came upon Jahaziel son of Zechariah, son of Benaiah, son of Jeiel, son of Mattaniah, a Levite of the sons of Asaph, in the middle of the assembly.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 15, 'He said, "Listen, all Judah and inhabitants of Jerusalem, and King Jehoshaphat: Thus says the LORD to you: "Do not fear or be dismayed at this great multitude; for the battle is not yours but God"s.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 16, 'Tomorrow go down against them; they will come up by the ascent of Ziz; you will find them at the end of the valley, before the wilderness of Jeruel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 17, 'This battle is not for you to fight; take your position, stand still, and see the victory of the LORD on your behalf, O Judah and Jerusalem." Do not fear or be dismayed; tomorrow go out against them, and the LORD will be with you."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 18, 'Then Jehoshaphat bowed down with his face to the ground, and all Judah and the inhabitants of Jerusalem fell down before the LORD, worshiping the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 19, 'And the Levites, of the Kohathites and the Korahites, stood up to praise the LORD, the God of Israel, with a very loud voice.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 20, 'They rose early in the morning and went out into the wilderness of Tekoa; and as they went out, Jehoshaphat stood and said, "Listen to me, O Judah and inhabitants of Jerusalem! Believe in the LORD your God and you will be established; believe his prophets."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 20, 21, 'When he had taken counsel with the people, he appointed those who were to sing to the LORD and praise him in holy splendor, as they went before the army, saying,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 21, 1, 'Jehoshaphat slept with his ancestors and was buried with his ancestors in the city of David; his son Jehoram succeeded him.', 'en', 'NRSV-CE', 'Jehoram"s Reign'),
(14, '2 Taw', '2 Chronicles', 21, 2, 'He had brothers, the sons of Jehoshaphat: Azariah, Jehiel, Zechariah, Azariah, Michael, and Shephatiah; all these were the sons of King Jehoshaphat of Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 3, 'Their father gave them many gifts, of silver, gold, and valuable possessions, together with fortified cities in Judah; but he gave the kingdom to Jehoram, because he was the firstborn.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 4, 'When Jehoram had ascended the throne of his father and was established, he put all his brothers to the sword, and also some of the officials of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 5, 'Jehoram was thirty-two years old when he began to reign; he reigned eight years in Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 6, 'He walked in the way of the kings of Israel, as the house of Ahab had done; for the daughter of Ahab was his wife. He did what was evil in the sight of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 7, 'Yet the LORD would not destroy the house of David because of the covenant that he had made with David, and since he had promised to give a lamp to him and to his descendants forever.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 8, 'In his days Edom revolted against the rule of Judah and set up a king of their own.', 'en', 'NRSV-CE', 'Revolt of Edom'),
(14, '2 Taw', '2 Chronicles', 21, 9, 'Then Jehoram crossed over with his commanders and all his chariots. He set out by night and attacked the Edomites, who had surrounded him and his chariot commanders.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 10, 'So Edom has been in revolt against the rule of Judah to this day. At that time Libnah also revolted against his rule, because he had forsaken the LORD, the God of his ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 11, 'Moreover he made high places in the hill country of Judah, and led the inhabitants of Jerusalem into unfaithfulness, and made Judah go astray.', 'en', 'NRSV-CE', 'Elijah"s Letter'),
(14, '2 Taw', '2 Chronicles', 21, 12, 'A letter came to him from the prophet Elijah, saying: "Thus says the LORD, the God of your father David: Because you have not walked in the ways of your father Jehoshaphat or in the ways of King Asa of Judah,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 13, 'but have walked in the way of the kings of Israel, and have led Judah and the inhabitants of Jerusalem into unfaithfulness, as the house of Ahab led Israel into unfaithfulness, and because you also have killed your brothers, members of your father"s house, who were better than yourself,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 14, 'see, the LORD will bring a great plague on your people, your children, your wives, and all your possessions,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 15, 'and you yourself will have a severe sickness with a disease of your bowels, until your bowels come out, day after day, because of the disease."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 16, 'The LORD aroused against Jehoram the anger of the Philistines and of the Arabs who are near the Ethiopians.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 17, 'They came up against Judah, invaded it, and carried away all the possessions they found that belonged to the king"s house, along with his sons and his wives, so that no son was left to him except Jehoahaz, his youngest son.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 18, 'After all this the LORD struck him in his bowels with an incurable disease.', 'en', 'NRSV-CE', 'Disease and Death of Jehoram'),
(14, '2 Taw', '2 Chronicles', 21, 19, 'In course of time, at the end of two years, his bowels came out because of the disease, and he died in great agony. His people made no fire in his honor, like the fires made for his ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 21, 20, 'He was thirty-two years old when he began to reign; he reigned eight years in Jerusalem. He departed with no one"s regret. They buried him in the city of David, but not in the tombs of the kings.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 22, 1, 'The inhabitants of Jerusalem made his youngest son Ahaziah king as his successor; for the troops who came with the Arabs to the camp had killed all the older sons. So Ahaziah son of Jehoram reigned as king of Judah.', 'en', 'NRSV-CE', 'Ahaziah"s Reign'),
(14, '2 Taw', '2 Chronicles', 22, 2, 'Ahaziah was forty-two years old when he began to reign; he reigned one year in Jerusalem. His mother"s name was Athaliah, a granddaughter of Omri.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 22, 3, 'He also walked in the ways of the house of Ahab, for his mother was his counselor in doing wickedly.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 22, 4, 'He did what was evil in the sight of the LORD, as the house of Ahab had done; for after the death of his father they were his counselors, to his ruin.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 22, 5, 'He even followed their advice, and went with Jehoram son of King Ahab of Israel to make war against King Hazael of Aram at Ramoth-gilead. The Arameans wounded Joram,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 22, 6, 'and he returned to be healed in Jezreel of the wounds that he had received at Ramah, when he fought King Hazael of Aram. And Ahaziah son of King Jehoram of Judah went down to see Joram son of Ahab in Jezreel, because he was sick.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 22, 7, 'But it was ordained by God that the downfall of Ahaziah should come about through his going to visit Joram. For when he came there he went out with Jehoram to meet Jehu son of Nimshi, whom the LORD had anointed to destroy the house of Ahab.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 22, 8, 'When Jehu was executing judgment on the house of Ahab, he met the officials of Judah and the sons of Ahaziah"s brothers, who attended Ahaziah, and he killed them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 22, 9, 'He searched for Ahaziah, who was captured while hiding in Samaria and was brought to Jehu, and put to death. They buried him, for they said, "He is the grandson of Jehoshaphat, who sought the LORD with all his heart." And the house of Ahaziah had no one able to rule the kingdom.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 22, 10, 'Now when Athaliah, Ahaziah"s mother, saw that her son was dead, she set about to destroy all the royal family of the house of Judah.', 'en', 'NRSV-CE', 'Athaliah Seizes the Throne'),
(14, '2 Taw', '2 Chronicles', 22, 11, 'But Jehoshabeath, the king"s daughter, took Joash son of Ahaziah, and stole him away from among the king"s children who were about to be killed; she put him and his nurse in a bedroom. Thus Jehoshabeath, daughter of King Jehoram and wife of the priest Jehoiada--because she was a sister of Ahaziah--hid him from Athaliah, so that she did not kill him;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 22, 12, 'he remained with them six years, hidden in the house of God, while Athaliah reigned over the land.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 23, 1, 'But in the seventh year Jehoiada took courage, and entered into a compact with the commanders of the hundreds, Azariah son of Jeroham, Ishmael son of Jehohanan, Azariah son of Obed, Maaseiah son of Adaiah, and Elishaphat son of Zichri.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 2, 'They went around through Judah and gathered the Levites from all the towns of Judah, and the heads of families of Israel, and they came to Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 3, 'Then the whole assembly made a covenant with the king in the house of God. Jehoiada said to them, "Here is the king"s son! Let him reign, as the LORD promised concerning the sons of David.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 4, 'This is what you are to do: one-third of you, priests and Levites, who come on duty on the sabbath, shall be gatekeepers,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 5, 'one-third shall be at the king"s house, and one-third at the Gate of the Foundation; and all the people shall be in the courts of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 6, 'Do not let anyone enter the house of the LORD except the priests and ministering Levites; they may enter, for they are holy, but all the other people shall observe the instructions of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 7, 'The Levites shall surround the king, each with his weapons in his hand; and whoever enters the house shall be killed. Stay with the king in his comings and goings."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 8, 'The Levites and all Judah did according to all that the priest Jehoiada commanded; each brought his men, who were to come on duty on the sabbath, with those who were to go off duty on the sabbath; for the priest Jehoiada did not dismiss the divisions.', 'en', 'NRSV-CE', 'Joash Crowned King'),
(14, '2 Taw', '2 Chronicles', 23, 9, 'The priest Jehoiada delivered to the captains the spears and the large and small shields that had been King David"s, which were in the house of God;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 10, 'and he set all the people as a guard for the king, everyone with weapon in hand, from the south side of the house to the north side of the house, around the altar and the house.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 11, 'Then he brought out the king"s son, put the crown on him, and gave him the covenant; they proclaimed him king, and Jehoiada and his sons anointed him; and they shouted, "Long live the king!"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 12, 'When Athaliah heard the noise of the people running and praising the king, she went into the house of the LORD to the people;', 'en', 'NRSV-CE', 'Athaliah Murdered'),
(14, '2 Taw', '2 Chronicles', 23, 13, 'and when she looked, there was the king standing by his pillar at the entrance, and the captains and the trumpeters beside the king, and all the people of the land rejoicing and blowing trumpets, and the singers with their musical instruments leading in the celebration. Athaliah tore her clothes, and cried, "Treason! Treason!"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 14, 'Then the priest Jehoiada brought out the captains who were set over the army, saying to them, "Bring her out between the ranks; anyone who follows her is to be put to the sword." For the priest said, "Do not put her to death in the house of the LORD."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 15, 'So they laid hands on her; she went into the entrance of the Horse Gate of the king"s house, and there they put her to death.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 16, 'Jehoiada made a covenant between himself and all the people and the king that they should be the LORD"s people.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 17, 'Then all the people went to the house of Baal, and tore it down; his altars and his images they broke in pieces, and they killed Mattan, the priest of Baal, in front of the altars.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 18, 'Jehoiada assigned the care of the house of the LORD to the levitical priests whom David had organized to be in charge of the house of the LORD, to offer burnt offerings to the LORD, as it is written in the law of Moses, with rejoicing and with singing, according to the order of David.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 19, 'He stationed the gatekeepers at the gates of the house of the LORD so that no one should enter who was in any way unclean.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 20, 'And he took the captains, the nobles, the governors of the people, and all the people of the land, and they brought the king down from the house of the LORD, marching through the upper gate to the king"s house. They set the king on the royal throne.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 23, 21, 'So all the people of the land rejoiced, and the city was quiet after Athaliah had been killed with the sword.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 24, 1, 'Joash was seven years old when he began to reign; he reigned forty years in Jerusalem; his mother"s name was Zibiah of Beer-sheba.', 'en', 'NRSV-CE', 'Joash Repairs the Temple'),
(14, '2 Taw', '2 Chronicles', 24, 2, 'Joash did what was right in the sight of the LORD all the days of the priest Jehoiada.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 3, 'Jehoiada got two wives for him, and he became the father of sons and daughters.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 4, 'Some time afterward Joash decided to restore the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 5, 'He assembled the priests and the Levites and said to them, "Go out to the cities of Judah and gather money from all Israel to repair the house of your God, year by year; and see that you act quickly." But the Levites did not act quickly.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 6, 'So the king summoned Jehoiada the chief, and said to him, "Why have you not required the Levites to bring in from Judah and Jerusalem the tax levied by Moses, the servant of the LORD, on the congregation of Israel for the tent of the covenant?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 7, 'For the children of Athaliah, that wicked woman, had broken into the house of God, and had even used all the dedicated things of the house of the LORD for the Baals.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 8, 'So the king gave command, and they made a chest, and set it outside the gate of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 9, 'A proclamation was made throughout Judah and Jerusalem to bring in for the LORD the tax that Moses the servant of God laid on Israel in the wilderness.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 10, 'All the leaders and all the people rejoiced and brought their tax and dropped it into the chest until it was full.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 11, 'Whenever the chest was brought to the king"s officers by the Levites, when they saw that there was a large amount of money in it, the king"s secretary and the officer of the chief priest would come and empty the chest and take it and return it to its place. So they did day after day, and collected money in abundance.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 12, 'The king and Jehoiada gave it to those who had charge of the work of the house of the LORD, and they hired masons and carpenters to restore the house of the LORD, and also workers in iron and bronze to repair the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 13, 'So those who were engaged in the work labored, and the repairing went forward at their hands, and they restored the house of God to its proper condition and strengthened it.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 14, 'When they had finished, they brought the rest of the money to the king and Jehoiada, and with it were made utensils for the house of the LORD, utensils for the service and for the burnt offerings, and ladles, and vessels of gold and silver. They offered burnt offerings in the house of the LORD regularly all the days of Jehoiada.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 15, 'But Jehoiada grew old and full of days, and died; he was one hundred thirty years old at his death.', 'en', 'NRSV-CE', 'Apostasy of Joash'),
(14, '2 Taw', '2 Chronicles', 24, 16, 'And they buried him in the city of David among the kings, because he had done good in Israel, and for God and his house.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 17, 'Now after the death of Jehoiada the officials of Judah came and did obeisance to the king; then the king listened to them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 18, 'They abandoned the house of the LORD, the God of their ancestors, and served the sacred poles and the idols. And wrath came upon Judah and Jerusalem for this guilt of theirs.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 19, 'Yet he sent prophets among them to bring them back to the LORD; they testified against them, but they would not listen.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 20, 'Then the spirit of God took possession of Zechariah son of the priest Jehoiada; he stood above the people and said to them, "Thus says God: Why do you transgress the commandments of the LORD, so that you cannot prosper? Because you have forsaken the LORD, he has also forsaken you."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 21, 'But they conspired against him, and by command of the king they stoned him to death in the court of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 22, 'King Joash did not remember the kindness that Jehoiada, Zechariah"s father, had shown him, but killed his son. As he was dying, he said, "May the LORD see and avenge!"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 23, 'At the end of the year the army of Aram came up against Joash. They came to Judah and Jerusalem, and destroyed all the officials of the people from among them, and sent all the booty they took to the king of Damascus.', 'en', 'NRSV-CE', 'Death of Joash'),
(14, '2 Taw', '2 Chronicles', 24, 24, 'Although the army of Aram had come with few men, the LORD delivered into their hand a very great army, because they had abandoned the LORD, the God of their ancestors. Thus they executed judgment on Joash.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 25, 'When they had withdrawn, leaving him severely wounded, his servants conspired against him because of the blood of the son of the priest Jehoiada, and they killed him on his bed. So he died; and they buried him in the city of David, but they did not bury him in the tombs of the kings.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 26, 'Those who conspired against him were Zabad son of Shimeath the Ammonite, and Jehozabad son of Shimrith the Moabite.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 24, 27, 'Accounts of his sons, and of the many oracles against him, and of the rebuilding of the house of God are written in the Commentary on the Book of the Kings. And his son Amaziah succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 25, 1, 'Amaziah was twenty-five years old when he began to reign, and he reigned twenty-nine years in Jerusalem. His mother"s name was Jehoaddan of Jerusalem.', 'en', 'NRSV-CE', 'Reign of Amaziah'),
(14, '2 Taw', '2 Chronicles', 25, 2, 'He did what was right in the sight of the LORD, yet not with a true heart.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 3, 'As soon as the royal power was firmly in his hand he killed his servants who had murdered his father the king.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 4, 'But he did not put their children to death, according to what is written in the law, in the book of Moses, where the LORD commanded, "The parents shall not be put to death for the children, or the children be put to death for the parents; but all shall be put to death for their own sins."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 5, 'Amaziah assembled the people of Judah, and set them by ancestral houses under commanders of the thousands and of the hundreds for all Judah and Benjamin. He mustered those twenty years old and upward, and found that they were three hundred thousand picked troops fit for war, able to handle spear and shield.', 'en', 'NRSV-CE', 'Slaughter of the Edomites'),
(14, '2 Taw', '2 Chronicles', 25, 6, 'He also hired one hundred thousand mighty warriors from Israel for one hundred talents of silver.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 7, 'But a man of God came to him and said, "O king, do not let the army of Israel go with you, for the LORD is not with Israel--all these Ephraimites.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 8, 'Rather, go by yourself and act; be strong in battle, or God will fling you down before the enemy; for God has power to help or to overthrow."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 9, 'Amaziah said to the man of God, "But what shall we do about the hundred talents that I have given to the army of Israel?" The man of God answered, "The LORD is able to give you much more than this."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 10, 'Then Amaziah discharged the army that had come to him from Ephraim, letting them go home again. But they became very angry with Judah, and returned home in fierce anger.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 11, 'Amaziah took courage, and led out his people; he went to the Valley of Salt, and struck down ten thousand men of Seir.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 12, 'The people of Judah captured another ten thousand alive, took them to the top of Sela, and threw them down from the top of Sela, so that all of them were dashed to pieces.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 13, 'But the men of the army whom Amaziah sent back, not letting them go with him to battle, fell on the cities of Judah from Samaria to Beth-horon; they killed three thousand people in them, and took much booty.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 14, 'Now after Amaziah came from the slaughter of the Edomites, he brought the gods of the people of Seir, set them up as his gods, and worshiped them, making offerings to them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 15, 'The LORD was angry with Amaziah and sent to him a prophet, who said to him, "Why have you resorted to a people"s gods who could not deliver their own people from your hand?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 16, 'But as he was speaking the king said to him, "Have we made you a royal counselor? Stop! Why should you be put to death?" So the prophet stopped, but said, "I know that God has determined to destroy you, because you have done this and have not listened to my advice."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 17, 'Then King Amaziah of Judah took counsel and sent to King Joash son of Jehoahaz son of Jehu of Israel, saying, "Come, let us look one another in the face."', 'en', 'NRSV-CE', 'Israel Defeats Judah'),
(14, '2 Taw', '2 Chronicles', 25, 18, 'King Joash of Israel sent word to King Amaziah of Judah, "A thornbush on Lebanon sent to a cedar on Lebanon, saying, "Give your daughter to my son for a wife"; but a wild animal of Lebanon passed by and trampled down the thornbush.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 19, 'You say, "See, I have defeated Edom," and your heart has lifted you up in boastfulness. Now stay at home; why should you provoke trouble so that you fall, you and Judah with you?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 20, 'But Amaziah would not listen--it was God"s doing, in order to hand them over, because they had sought the gods of Edom.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 21, 'So King Joash of Israel went up; he and King Amaziah of Judah faced one another in battle at Beth-shemesh, which belongs to Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 22, 'Judah was defeated by Israel; everyone fled home.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 23, 'King Joash of Israel captured King Amaziah of Judah, son of Joash, son of Ahaziah, at Beth-shemesh; he brought him to Jerusalem, and broke down the wall of Jerusalem from the Ephraim Gate to the Corner Gate, a distance of four hundred cubits.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 24, 'He seized all the gold and silver, and all the vessels that were found in the house of God, and Obed-edom with them; he seized also the treasuries of the king"s house, also hostages; then he returned to Samaria.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 25, 'King Amaziah son of Joash of Judah, lived fifteen years after the death of King Joash son of Jehoahaz of Israel.', 'en', 'NRSV-CE', 'Death of Amaziah'),
(14, '2 Taw', '2 Chronicles', 25, 26, 'Now the rest of the deeds of Amaziah, from first to last, are they not written in the Book of the Kings of Judah and Israel?', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 27, 'From the time that Amaziah turned away from the LORD they made a conspiracy against him in Jerusalem, and he fled to Lachish. But they sent after him to Lachish, and killed him there.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 25, 28, 'They brought him back on horses; he was buried with his ancestors in the city of David.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 26, 1, 'Then all the people of Judah took Uzziah, who was sixteen years old, and made him king to succeed his father Amaziah.', 'en', 'NRSV-CE', 'Reign of Uzziah'),
(14, '2 Taw', '2 Chronicles', 26, 2, 'He rebuilt Eloth and restored it to Judah, after the king slept with his ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 3, 'Uzziah was sixteen years old when he began to reign, and he reigned fifty-two years in Jerusalem. His mother"s name was Jecoliah of Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 4, 'He did what was right in the sight of the LORD, just as his father Amaziah had done.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 5, 'He set himself to seek God in the days of Zechariah, who instructed him in the fear of God; and as long as he sought the LORD, God made him prosper.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 6, 'He went out and made war against the Philistines, and broke down the wall of Gath and the wall of Jabneh and the wall of Ashdod; he built cities in the territory of Ashdod and elsewhere among the Philistines.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 7, 'God helped him against the Philistines, against the Arabs who lived in Gur-baal, and against the Meunites.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 8, 'The Ammonites paid tribute to Uzziah, and his fame spread even to the border of Egypt, for he became very strong.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 9, 'Moreover Uzziah built towers in Jerusalem at the Corner Gate, at the Valley Gate, and at the Angle, and fortified them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 10, 'He built towers in the wilderness and hewed out many cisterns, for he had large herds, both in the Shephelah and in the plain, and he had farmers and vinedressers in the hills and in the fertile lands, for he loved the soil.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 11, 'Moreover Uzziah had an army of soldiers, fit for war, in divisions according to the numbers in the muster made by the secretary Jeiel and the officer Maaseiah, under the direction of Hananiah, one of the king"s commanders.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 12, 'The whole number of the heads of ancestral houses of mighty warriors was two thousand six hundred.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 13, 'Under their command was an army of three hundred seven thousand five hundred, who could make war with mighty power, to help the king against the enemy.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 14, 'Uzziah provided for all the army the shields, spears, helmets, coats of mail, bows, and stones for slinging.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 15, 'In Jerusalem he set up machines, invented by skilled workers, on the towers and the corners for shooting arrows and large stones. And his fame spread far, for he was marvelously helped until he became strong.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 16, 'But when he had become strong he grew proud, to his destruction. For he was false to the LORD his God, and entered the temple of the LORD to make offering on the altar of incense.', 'en', 'NRSV-CE', 'Pride and Apostasy'),
(14, '2 Taw', '2 Chronicles', 26, 17, 'But the priest Azariah went in after him, with eighty priests of the LORD who were men of valor;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 18, 'they withstood King Uzziah, and said to him, "It is not for you, Uzziah, to make offering to the LORD, but for the priests the descendants of Aaron, who are consecrated to make offering. Go out of the sanctuary; for you have done wrong, and it will bring you no honor from the LORD God."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 19, 'Then Uzziah was angry. Now he had a censer in his hand to make offering, and when he became angry with the priests a leprous disease broke out on his forehead, in the presence of the priests in the house of the LORD, by the altar of incense.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 20, 'When the chief priest Azariah, and all the priests, looked at him, he was leprous in his forehead. They hurried him out, and he himself hurried to get out, because the LORD had struck him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 21, 'King Uzziah was leprous to the day of his death, and being leprous lived in a separate house, for he was excluded from the house of the LORD. His son Jotham was in charge of the palace of the king, governing the people of the land.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 22, 'Now the rest of the acts of Uzziah, from first to last, the prophet Isaiah son of Amoz wrote.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 26, 23, 'Uzziah slept with his ancestors; they buried him near his ancestors in the burial field that belonged to the kings, for they said, "He is leprous." His son Jotham succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 27, 1, 'Jotham was twenty-five years old when he began to reign; he reigned sixteen years in Jerusalem. His mother"s name was Jerushah daughter of Zadok.', 'en', 'NRSV-CE', 'Reign of Jotham'),
(14, '2 Taw', '2 Chronicles', 27, 2, 'He did what was right in the sight of the LORD just as his father Uzziah had done--only he did not invade the temple of the LORD. But the people still followed corrupt practices.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 27, 3, 'He built the upper gate of the house of the LORD, and did extensive building on the wall of Ophel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 27, 4, 'Moreover he built cities in the hill country of Judah, and forts and towers on the wooded hills.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 27, 5, 'He fought with the king of the Ammonites and prevailed against them. The Ammonites gave him that year one hundred talents of silver, ten thousand cors of wheat and ten thousand of barley. The Ammonites paid him the same amount in the second and the third years.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 27, 6, 'So Jotham became strong because he ordered his ways before the LORD his God.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 27, 7, 'Now the rest of the acts of Jotham, and all his wars and his ways, are written in the Book of the Kings of Israel and Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 27, 8, 'He was twenty-five years old when he began to reign; he reigned sixteen years in Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 27, 9, 'Jotham slept with his ancestors, and they buried him in the city of David; and his son Ahaz succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 28, 1, 'Ahaz was twenty years old when he began to reign; he reigned sixteen years in Jerusalem. He did not do what was right in the sight of the LORD, as his ancestor David had done,', 'en', 'NRSV-CE', 'Reign of Ahaz'),
(14, '2 Taw', '2 Chronicles', 28, 2, 'but he walked in the ways of the kings of Israel. He even made cast images for the Baals;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 3, 'and he made offerings in the valley of the son of Hinnom, and made his sons pass through fire, according to the abominable practices of the nations whom the LORD drove out before the people of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 4, 'He sacrificed and made offerings on the high places, on the hills, and under every green tree.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 5, 'Therefore the LORD his God gave him into the hand of the king of Aram, who defeated him and took captive a great number of his people and brought them to Damascus. He was also given into the hand of the king of Israel, who defeated him with great slaughter.', 'en', 'NRSV-CE', 'Aram and Israel Defeat Judah'),
(14, '2 Taw', '2 Chronicles', 28, 6, 'Pekah son of Remaliah killed one hundred twenty thousand in Judah in one day, all of them valiant warriors, because they had abandoned the LORD, the God of their ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 7, 'And Zichri, a mighty warrior of Ephraim, killed the king"s son Maaseiah, Azrikam the commander of the palace, and Elkanah the next in authority to the king.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 8, 'The people of Israel took captive two hundred thousand of their kin, women, sons, and daughters; they also took much booty from them and brought the booty to Samaria.', 'en', 'NRSV-CE', 'Intervention of Oded'),
(14, '2 Taw', '2 Chronicles', 28, 9, 'But a prophet of the LORD was there, whose name was Oded; he went out to meet the army that came to Samaria, and said to them, "Because the LORD, the God of your ancestors, was angry with Judah, he gave them into your hand, but you have killed them in a rage that has reached up to heaven.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 10, 'Now you intend to subjugate the people of Judah and Jerusalem, male and female, as your slaves. But what have you except sins against the LORD your God?', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 11, 'Now hear me, and send back the captives whom you have taken from your kindred, for the fierce wrath of the LORD is upon you."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 12, 'Moreover, certain chiefs of the Ephraimites, Azariah son of Johanan, Berechiah son of Meshillemoth, Jehizkiah son of Shallum, and Amasa son of Hadlai, stood up against those who were coming from the war,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 13, 'and said to them, "You shall not bring the captives in here, for you propose to bring on us guilt against the LORD in addition to our present sins and guilt. For our guilt is already great, and there is fierce wrath against Israel."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 14, 'So the warriors left the captives and the booty before the officials and all the assembly.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 15, 'Then those who were mentioned by name got up and took the captives, and with the booty they clothed all that were naked among them; they clothed them, gave them sandals, provided them with food and drink, and anointed them; and carrying all the feeble among them on donkeys, they brought them to their kindred at Jericho, the city of palm trees. Then they returned to Samaria.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 16, 'At that time King Ahaz sent to the king of Assyria for help.', 'en', 'NRSV-CE', 'Assyria Refuses to Help Judah'),
(14, '2 Taw', '2 Chronicles', 28, 17, 'For the Edomites had again invaded and defeated Judah, and carried away captives.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 18, 'And the Philistines had made raids on the cities in the Shephelah and the Negeb of Judah, and had taken Beth-shemesh, Aijalon, Gederoth, Soco with its villages, Timnah with its villages, and Gimzo with its villages; and they settled there.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 19, 'For the LORD brought Judah low because of King Ahaz of Israel, for he had behaved without restraint in Judah and had been faithless to the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 20, 'So King Tilgath-pilneser of Assyria came against him, and oppressed him instead of strengthening him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 21, 'For Ahaz plundered the house of the LORD and the houses of the king and of the officials, and gave tribute to the king of Assyria; but it did not help him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 22, 'In the time of his distress he became yet more faithless to the LORD--this same King Ahaz.', 'en', 'NRSV-CE', 'Apostasy and Death of Ahaz'),
(14, '2 Taw', '2 Chronicles', 28, 23, 'For he sacrificed to the gods of Damascus, which had defeated him, and said, "Because the gods of the kings of Aram helped them, I will sacrifice to them so that they may help me." But they were the ruin of him, and of all Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 24, 'Ahaz gathered together the utensils of the house of God, and cut in pieces the utensils of the house of God. He shut up the doors of the house of the LORD and made himself altars in every corner of Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 25, 'In every city of Judah he made high places to make offerings to other gods, provoking to anger the LORD, the God of his ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 26, 'Now the rest of his acts and all his ways, from first to last, are written in the Book of the Kings of Judah and Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 28, 27, 'Ahaz slept with his ancestors, and they buried him in the city, in Jerusalem; but they did not bring him into the tombs of the kings of Israel. His son Hezekiah succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 29, 1, 'Hezekiah began to reign when he was twenty-five years old; he reigned twenty-nine years in Jerusalem. His mother"s name was Abijah daughter of Zechariah.', 'en', 'NRSV-CE', 'Reign of Hezekiah'),
(14, '2 Taw', '2 Chronicles', 29, 2, 'He did what was right in the sight of the LORD, just as his ancestor David had done.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 3, 'In the first year of his reign, in the first month, he opened the doors of the house of the LORD and repaired them.', 'en', 'NRSV-CE', 'The Temple Cleansed'),
(14, '2 Taw', '2 Chronicles', 29, 4, 'He brought in the priests and the Levites and assembled them in the square on the east.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 5, 'He said to them, "Listen to me, Levites! Sanctify yourselves, and sanctify the house of the LORD, the God of your ancestors, and carry out the filth from the holy place.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 6, 'For our ancestors have been unfaithful and have done what was evil in the sight of the LORD our God; they have forsaken him, and have turned away their faces from the dwelling of the LORD, and turned their backs.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 7, 'They also shut the doors of the vestibule and put out the lamps, and have not offered incense or made burnt offerings in the holy place to the God of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 8, 'Therefore the wrath of the LORD came upon Judah and Jerusalem, and he has made them an object of horror, of astonishment, and of hissing, as you see with your own eyes.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 9, 'Our fathers have fallen by the sword and our sons and our daughters and our wives are in captivity for this.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 10, 'Now it is in my heart to make a covenant with the LORD, the God of Israel, so that his fierce anger may turn away from us.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 11, 'My sons, do not now be negligent, for the LORD has chosen you to stand in his presence to minister to him, and to be his ministers and make offerings to him."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 12, 'Then the Levites arose, Mahath son of Amasai, and Joel son of Azariah, of the sons of the Kohathites; and of the sons of Merari, Kish son of Abdi, and Azariah son of Jehallelel; and of the Gershonites, Joah son of Zimmah, and Eden son of Joah;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 13, 'and of the sons of Elizaphan, Shimri and Jeuel; and of the sons of Asaph, Zechariah and Mattaniah;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 14, 'and of the sons of Heman, Jehuel and Shimei; and of the sons of Jeduthun, Shemaiah and Uzziel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 15, 'They gathered their brothers, sanctified themselves, and went in as the king had commanded, by the words of the LORD, to cleanse the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 16, 'The priests went into the inner part of the house of the LORD to cleanse it, and they brought out all the unclean things that they found in the temple of the LORD into the court of the house of the LORD; and the Levites took them and carried them out to the Wadi Kidron.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 17, 'They began to sanctify on the first day of the first month, and on the eighth day of the month they came to the vestibule of the LORD; then for eight days they sanctified the house of the LORD, and on the sixteenth day of the first month they finished.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 18, 'Then they went inside to King Hezekiah and said, "We have cleansed all the house of the LORD, the altar of burnt offering and all its utensils, and the table for the rows of bread and all its utensils.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 19, 'All the utensils that King Ahaz repudiated during his reign when he was faithless, we have made ready and sanctified; see, they are in front of the altar of the LORD."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 20, 'Then King Hezekiah rose early, assembled the officials of the city, and went up to the house of the LORD.', 'en', 'NRSV-CE', 'Temple Worship Restored'),
(14, '2 Taw', '2 Chronicles', 29, 21, 'They brought seven bulls, seven rams, seven lambs, and seven male goats for a sin offering for the kingdom and for the sanctuary and for Judah. He commanded the priests the descendants of Aaron to offer them on the altar of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 22, 'So they slaughtered the bulls, and the priests received the blood and dashed it against the altar; they slaughtered the rams and their blood was dashed against the altar; they also slaughtered the lambs and their blood was dashed against the altar.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 23, 'Then the male goats for the sin offering were brought to the king and the assembly; they laid their hands on them,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 24, 'and the priests slaughtered them and made a sin offering with their blood at the altar, to make atonement for all Israel. For the king commanded that the burnt offering and the sin offering should be made for all Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 25, 'He stationed the Levites in the house of the LORD with cymbals, harps, and lyres, according to the commandment of David and of Gad the king"s seer and of the prophet Nathan, for the commandment was from the LORD through his prophets.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 26, 'The Levites stood with the instruments of David, and the priests with the trumpets.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 27, 'Then Hezekiah commanded that the burnt offering be offered on the altar. When the burnt offering began, the song to the LORD began also, and the trumpets, accompanied by the instruments of King David of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 28, 'The whole assembly worshiped, the singers sang, and the trumpeters sounded; all this continued until the burnt offering was finished.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 29, 'When the offering was finished, the king and all who were present with him bowed down and worshiped.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 30, 'King Hezekiah and the officials commanded the Levites to sing praises to the LORD with the words of David and of the seer Asaph. They sang praises with gladness, and they bowed down and worshiped.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 31, 'Then Hezekiah said, "You have now consecrated yourselves to the LORD; come near, bring sacrifices and thank offerings to the house of the LORD." The assembly brought sacrifices and thank offerings; and all who were of a willing heart brought burnt offerings.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 32, 'The number of the burnt offerings that the assembly brought was seventy bulls, one hundred rams, and two hundred lambs; all these were for a burnt offering to the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 33, 'The consecrated offerings were six hundred bulls and three thousand sheep.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 34, 'But the priests were too few and could not skin all the burnt offerings, so, until other priests had sanctified themselves, their kindred, the Levites, helped them until the work was finished--for the Levites were more conscientious than the priests in sanctifying themselves.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 35, 'Besides the great number of burnt offerings there was the fat of the offerings of well-being, and there were the drink offerings for the burnt offerings. Thus the service of the house of the LORD was restored.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 29, 36, 'And Hezekiah and all the people rejoiced because of what God had done for the people; for the thing had come about suddenly.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 30, 1, 'Hezekiah sent word to all Israel and Judah, and wrote letters also to Ephraim and Manasseh, that they should come to the house of the LORD at Jerusalem, to keep the passover to the LORD the God of Israel.', 'en', 'NRSV-CE', 'The Great Passover'),
(14, '2 Taw', '2 Chronicles', 30, 2, 'For the king and his officials and all the assembly in Jerusalem had taken counsel to keep the passover in the second month', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 3, '(for they could not keep it at its proper time because the priests had not sanctified themselves in sufficient number, nor had the people assembled in Jerusalem).', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 4, 'The plan seemed right to the king and all the assembly.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 5, 'So they decreed to make a proclamation throughout all Israel, from Beer-sheba to Dan, that the people should come and keep the passover to the LORD the God of Israel, at Jerusalem; for they had not kept it in great numbers as prescribed.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 6, 'So couriers went throughout all Israel and Judah with letters from the king and his officials, as the king had commanded, saying, "O people of Israel, return to the LORD, the God of Abraham, Isaac, and Israel, so that he may turn again to the remnant of you who have escaped from the hand of the kings of Assyria.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 7, 'Do not be like your ancestors and your kindred, who were faithless to the LORD God of their ancestors, so that he made them a desolation, as you see.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 8, 'Do not now be stiff-necked as your ancestors were, but yield yourselves to the LORD and come to his sanctuary, which he has sanctified forever, and serve the LORD your God, so that his fierce anger may turn away from you.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 9, 'For as you return to the LORD, your kindred and your children will find compassion with their captors, and return to this land. For the LORD your God is gracious and merciful, and will not turn away his face from you, if you return to him."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 10, 'So the couriers went from city to city through the country of Ephraim and Manasseh, and as far as Zebulun; but they laughed them to scorn, and mocked them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 11, 'Only a few from Asher, Manasseh, and Zebulun humbled themselves and came to Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 12, 'The hand of God was also on Judah to give them one heart to do what the king and the officials commanded by the word of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 13, 'Many people came together in Jerusalem to keep the festival of unleavened bread in the second month, a very large assembly.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 14, 'They set to work and removed the altars that were in Jerusalem, and all the altars for offering incense they took away and threw into the Wadi Kidron.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 15, 'They slaughtered the passover lamb on the fourteenth day of the second month. The priests and the Levites were ashamed, and they sanctified themselves and brought burnt offerings into the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 16, 'They took their accustomed posts according to the law of Moses the man of God; the priests dashed the blood that they received from the hands of the Levites.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 17, 'For there were many in the assembly who had not sanctified themselves; therefore the Levites had to slaughter the passover lamb for everyone who was not clean, to make it holy to the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 18, 'For a multitude of the people, many of them from Ephraim, Manasseh, Issachar, and Zebulun, had not cleansed themselves, yet they ate the passover otherwise than as prescribed. But Hezekiah prayed for them, saying, "The good LORD pardon all', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 19, 'who set their hearts to seek God, the LORD the God of their ancestors, even though not in accordance with the sanctuary"s rules of cleanness."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 20, 'The LORD heard Hezekiah, and healed the people.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 21, 'The people of Israel who were present at Jerusalem kept the festival of unleavened bread seven days with great gladness; and the Levites and the priests praised the LORD day by day, accompanied by loud instruments for the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 22, 'Hezekiah spoke encouragingly to all the Levites who showed good skill in the service of the LORD. So the people ate the food of the festival for seven days, sacrificing offerings of well-being and giving thanks to the LORD the God of their ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 23, 'Then the whole assembly agreed together to keep the festival for another seven days; so they kept it for another seven days with gladness.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 24, 'For King Hezekiah of Judah gave the assembly a thousand bulls and seven thousand sheep for offerings, and the officials gave the assembly a thousand bulls and ten thousand sheep. The priests sanctified themselves in great numbers.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 25, 'The whole assembly of Judah, the priests and the Levites, and the whole assembly that came out of Israel, and the resident aliens who came out of the land of Israel, and the resident aliens who lived in Judah, rejoiced.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 26, 'There was great joy in Jerusalem, for since the time of Solomon son of King David of Israel there had been nothing like this in Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 30, 27, 'Then the priests and the Levites stood up and blessed the people, and their voice was heard; their prayer came to his holy dwelling in heaven.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 31, 1, 'Now when all this was finished, all Israel who were present went out to the cities of Judah and broke down the pillars, hewed down the sacred poles, and pulled down the high places and the altars throughout all Judah and Benjamin, and in Ephraim and Manasseh, until they had destroyed them all. Then all the people of Israel returned to their cities, all to their individual properties.', 'en', 'NRSV-CE', 'Pagan Shrines Destroyed'),
(14, '2 Taw', '2 Chronicles', 31, 2, 'Hezekiah appointed the divisions of the priests and of the Levites, division by division, everyone according to his service, the priests and the Levites, for burnt offerings and offerings of well-being, to minister in the gates of the camp of the LORD and to give thanks and praise.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 3, 'The contribution of the king from his own possessions was for the burnt offerings: the burnt offerings of morning and evening, and the burnt offerings for the sabbaths, the new moons, and the appointed festivals, as it is written in the law of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 4, 'He commanded the people who lived in Jerusalem to give the portion due to the priests and the Levites, so that they might devote themselves to the law of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 5, 'As soon as the word spread, the people of Israel gave in abundance the first fruits of grain, wine, oil, honey, and of all the produce of the field; and they brought in abundantly the tithe of everything.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 6, 'The people of Israel and Judah who lived in the cities of Judah also brought in the tithe of cattle and sheep, and the tithe of the dedicated things that had been consecrated to the LORD their God, and laid them in heaps.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 7, 'In the third month they began to pile up the heaps, and finished them in the seventh month.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 8, 'When Hezekiah and the officials came and saw the heaps, they blessed the LORD and his people Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 9, 'Hezekiah questioned the priests and the Levites about the heaps.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 10, 'The chief priest Azariah, who was of the house of Zadok, answered him, "Since they began to bring the contributions into the house of the LORD, we have had enough to eat and have plenty to spare; for the LORD has blessed his people, so that we have this great supply left over."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 11, 'Then Hezekiah commanded them to prepare store-chambers in the house of the LORD; and they prepared them.', 'en', 'NRSV-CE', 'Reorganization of Priests and Levites'),
(14, '2 Taw', '2 Chronicles', 31, 12, 'Faithfully they brought in the contributions, the tithes and the dedicated things. The chief officer in charge of them was Conaniah the Levite, with his brother Shimei as second;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 13, 'while Jehiel, Azaziah, Nahath, Asahel, Jerimoth, Jozabad, Eliel, Ismachiah, Mahath, and Benaiah were overseers assisting Conaniah and his brother Shimei, by the appointment of King Hezekiah and of Azariah the chief officer of the house of God.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 14, 'Kore son of Imnah the Levite, keeper of the east gate, was in charge of the freewill offerings to God, to apportion the contribution reserved for the LORD and the most holy offerings.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 15, 'Eden, Miniamin, Jeshua, Shemaiah, Amariah, and Shecaniah were faithfully assisting him in the cities of the priests, to distribute the portions to their kindred, old and young alike, by divisions,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 16, 'except those enrolled by genealogy, males from three years old and upwards, all who entered the house of the LORD as the duty of each day required, for their service according to their offices, by their divisions.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 17, 'The enrollment of the priests was according to their ancestral houses; that of the Levites from twenty years old and upwards was according to their offices, by their divisions.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 18, 'The priests were enrolled with all their little children, their wives, their sons, and their daughters, the whole multitude; for they were faithful in keeping themselves holy.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 19, 'And for the descendants of Aaron, the priests, who were in the fields of common land belonging to their towns, town by town, the people designated by name were to distribute portions to every male among the priests and to everyone among the Levites who was enrolled.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 20, 'Hezekiah did this throughout all Judah; he did what was good and right and faithful before the LORD his God.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 31, 21, 'And every work that he undertook in the service of the house of God, and in accordance with the law and the commandments, to seek his God, he did with all his heart; and he prospered.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 32, 1, 'After these things and these acts of faithfulness, King Sennacherib of Assyria came and invaded Judah and encamped against the fortified cities, thinking to win them for himself.', 'en', 'NRSV-CE', 'Sennacherib"s Invasion'),
(14, '2 Taw', '2 Chronicles', 32, 2, 'When Hezekiah saw that Sennacherib had come and intended to fight against Jerusalem,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 3, 'he planned with his officers and his warriors to stop the flow of the springs that were outside the city; and they helped him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 4, 'A great many people were gathered, and they stopped all the springs and the wadi that flowed through the land, saying, "Why should the Assyrian kings come and find water in abundance?"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 5, 'Hezekiah set to work resolutely and built up the entire wall that was broken down, and raised towers on it, and outside it he built another wall; he also strengthened the Millo in the city of David, and made weapons and shields in abundance.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 6, 'He appointed combat commanders over the people, and gathered them together to him in the square at the gate of the city and spoke encouragingly to them, saying,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 7, '"Be strong and of good courage. Do not be afraid or dismayed before the king of Assyria and all the horde that is with him; for there is one greater with us than with him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 8, 'With him is an arm of flesh; but with us is the LORD our God, to help us and to fight our battles." The people were encouraged by the words of King Hezekiah of Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 9, 'After this, while King Sennacherib of Assyria was at Lachish with all his forces, he sent his servants to Jerusalem to King Hezekiah of Judah and to all the people of Judah that were in Jerusalem, saying,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 10, '"Thus says King Sennacherib of Assyria: On what are you relying, that you undergo the siege of Jerusalem?', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 11, 'Is not Hezekiah misleading you, handing you over to die by famine and by thirst, when he tells you, "The LORD our God will save us from the hand of the king of Assyria"?', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 12, 'Was it not this same Hezekiah who took away his high places and his altars and commanded Judah and Jerusalem, saying, "Before one altar you shall worship, and upon it you shall make your offerings"?', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 13, 'Do you not know what I and my ancestors have done to all the peoples of other lands? Were the gods of the nations of those lands at all able to save their lands out of my hand?', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 14, 'Who among all the gods of those nations that my ancestors utterly destroyed was able to save his people from my hand, that your God should be able to save you from my hand?', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 15, 'Now therefore do not let Hezekiah deceive you or mislead you in this fashion, and do not believe him, for no god of any nation or kingdom has been able to save his people from my hand or from the hand of my ancestors. How much less will your God save you out of my hand!"', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 16, 'His servants said still more against the Lord God and against his servant Hezekiah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 17, 'He also wrote letters to throw contempt on the LORD the God of Israel and to speak against him, saying, "Just as the gods of the nations in other lands did not rescue their people from my hands, so the God of Hezekiah will not rescue his people from my hand."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 18, 'They shouted it with a loud voice in the language of Judah to the people of Jerusalem who were on the wall, to frighten and terrify them, in order that they might take the city.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 19, 'They spoke of the God of Jerusalem as if he were like the gods of the peoples of the earth, which are the work of human hands.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 20, 'Then King Hezekiah and the prophet Isaiah son of Amoz prayed because of this and cried to heaven.', 'en', 'NRSV-CE', 'Sennacherib"s Defeat and Death'),
(14, '2 Taw', '2 Chronicles', 32, 21, 'And the LORD sent an angel who cut off all the mighty warriors and commanders and officers in the camp of the king of Assyria. So he returned in disgrace to his own land. When he came into the house of his god, some of his own sons struck him down there with the sword.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 22, 'So the LORD saved Hezekiah and the inhabitants of Jerusalem from the hand of King Sennacherib of Assyria and from the hand of all his enemies; he gave them rest on every side.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 23, 'Many brought gifts to the LORD in Jerusalem and precious things to King Hezekiah of Judah, so that he was exalted in the sight of all nations from that time onward.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 24, 'In those days Hezekiah became sick and was at the point of death. He prayed to the LORD, and he answered him and gave him a sign.', 'en', 'NRSV-CE', 'Hezekiah"s Sickness'),
(14, '2 Taw', '2 Chronicles', 32, 25, 'But Hezekiah did not respond according to the benefit done to him, for his heart was proud. Therefore wrath came upon him and upon Judah and Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 26, 'Then Hezekiah humbled himself for the pride of his heart, both he and the inhabitants of Jerusalem, so that the wrath of the LORD did not come upon them in the days of Hezekiah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 27, 'Hezekiah had very great riches and honor; and he made for himself treasuries for silver, for gold, for precious stones, for spices, for shields, and for all kinds of costly objects;', 'en', 'NRSV-CE', 'Hezekiah"s Prosperity and Achievements'),
(14, '2 Taw', '2 Chronicles', 32, 28, 'storehouses also for the yield of grain, wine, and oil; and stalls for all kinds of cattle, and sheepfolds.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 29, 'He likewise provided cities for himself, and flocks and herds in abundance; for God had given him very great possessions.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 30, 'This same Hezekiah closed the upper outlet of the waters of Gihon and directed them down to the west side of the city of David. Hezekiah prospered in all his works.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 31, 'So also in the matter of the envoys of the officials of Babylon, who had been sent to him to inquire about the sign that had been done in the land, God left him to himself, in order to test him and to know all that was in his heart.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 32, 'Now the rest of the acts of Hezekiah, and his good deeds, are written in the vision of the prophet Isaiah son of Amoz in the Book of the Kings of Judah and Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 32, 33, 'Hezekiah slept with his ancestors, and they buried him on the ascent to the tombs of the descendants of David; and all Judah and the inhabitants of Jerusalem did him honor at his death. His son Manasseh succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 33, 1, 'Manasseh was twelve years old when he began to reign; he reigned fifty-five years in Jerusalem.', 'en', 'NRSV-CE', 'Reign of Manasseh'),
(14, '2 Taw', '2 Chronicles', 33, 2, 'He did what was evil in the sight of the LORD, according to the abominable practices of the nations whom the LORD drove out before the people of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 3, 'For he rebuilt the high places that his father Hezekiah had pulled down, and erected altars to the Baals, made sacred poles, worshiped all the host of heaven, and served them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 4, 'He built altars in the house of the LORD, of which the LORD had said, "In Jerusalem shall my name be forever."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 5, 'He built altars for all the host of heaven in the two courts of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 6, 'He made his son pass through fire in the valley of the son of Hinnom, practiced soothsaying and augury and sorcery, and dealt with mediums and with wizards. He did much evil in the sight of the LORD, provoking him to anger.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 7, 'The carved image of the idol that he had made he set in the house of God, of which God said to David and to his son Solomon, "In this house, and in Jerusalem, which I have chosen out of all the tribes of Israel, I will put my name forever;', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 8, 'I will never again remove the feet of Israel from the land that I appointed for your ancestors, if only they will be careful to do all that I have commanded them, all the law, the statutes, and the ordinances given through Moses."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 9, 'Manasseh misled Judah and the inhabitants of Jerusalem, so that they did more evil than the nations whom the LORD had destroyed before the people of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 10, 'The LORD spoke to Manasseh and to his people, but they gave no heed.', 'en', 'NRSV-CE', 'Manasseh Restored after Repentance'),
(14, '2 Taw', '2 Chronicles', 33, 11, 'Therefore the LORD brought against them the commanders of the army of the king of Assyria, who took Manasseh captive in manacles, bound him with fetters, and brought him to Babylon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 12, 'While he was in distress he entreated the favor of the LORD his God and humbled himself greatly before the God of his ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 13, 'He prayed to him, and God received his entreaty, heard his plea, and restored him again to Jerusalem and to his kingdom. Then Manasseh knew that the LORD indeed was God.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 14, 'Afterward he built an outer wall for the city of David west of Gihon, in the valley, reaching the entrance at the Fish Gate; he carried it around Ophel, and raised it to a very great height. He also put commanders of the army in all the fortified cities in Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 15, 'He took away the foreign gods and the idol from the house of the LORD, and all the altars that he had built on the mountain of the house of the LORD and in Jerusalem, and he threw them out of the city.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 16, 'He also restored the altar of the LORD and offered on it sacrifices of well-being and of thanksgiving; and he commanded Judah to serve the LORD the God of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 17, 'The people, however, still sacrificed at the high places, but only to the LORD their God.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 18, 'Now the rest of the acts of Manasseh, his prayer to his God, and the words of the seers who spoke to him in the name of the LORD God of Israel, these are in the Annals of the Kings of Israel.', 'en', 'NRSV-CE', 'Death of Manasseh'),
(14, '2 Taw', '2 Chronicles', 33, 19, 'His prayer, and how God received his entreaty, all his sin and his faithlessness, the sites on which he built high places and set up the sacred poles and the images, before he humbled himself, these are written in the records of the seers.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 20, 'So Manasseh slept with his ancestors, and they buried him in his house. His son Amon succeeded him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 21, 'Amon was twenty-two years old when he began to reign; he reigned two years in Jerusalem.', 'en', 'NRSV-CE', 'Amon"s Reign and Death'),
(14, '2 Taw', '2 Chronicles', 33, 22, 'He did what was evil in the sight of the LORD, as his father Manasseh had done. Amon sacrificed to all the images that his father Manasseh had made, and served them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 23, 'He did not humble himself before the LORD, as his father Manasseh had humbled himself, but this Amon incurred more and more guilt.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 24, 'His servants conspired against him and killed him in his house.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 33, 25, 'But the people of the land killed all those who had conspired against King Amon; and the people of the land made his son Josiah king to succeed him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 34, 1, 'Josiah was eight years old when he began to reign; he reigned thirty-one years in Jerusalem.', 'en', 'NRSV-CE', 'Reign of Josiah'),
(14, '2 Taw', '2 Chronicles', 34, 2, 'He did what was right in the sight of the LORD, and walked in the ways of his ancestor David; he did not turn aside to the right or to the left.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 3, 'For in the eighth year of his reign, while he was still a boy, he began to seek the God of his ancestor David, and in the twelfth year he began to purge Judah and Jerusalem of the high places, the sacred poles, and the carved and the cast images.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 4, 'In his presence they pulled down the altars of the Baals; he demolished the incense altars that stood above them. He broke down the sacred poles and the carved and the cast images; he made dust of them and scattered it over the graves of those who had sacrificed to them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 5, 'He also burned the bones of the priests on their altars, and purged Judah and Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 6, 'In the towns of Manasseh, Ephraim, and Simeon, and as far as Naphtali, in their ruins all around,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 7, 'he broke down the altars, beat the sacred poles and the images into powder, and demolished all the incense altars throughout all the land of Israel. Then he returned to Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 8, 'In the eighteenth year of his reign, when he had purged the land and the house, he sent Shaphan son of Azaliah, Maaseiah the governor of the city, and Joah son of Joahaz, the recorder, to repair the house of the LORD his God.', 'en', 'NRSV-CE', 'Discovery of the Book of the Law'),
(14, '2 Taw', '2 Chronicles', 34, 9, 'They came to the high priest Hilkiah and delivered the money that had been brought into the house of God, which the Levites, the keepers of the threshold, had collected from Manasseh and Ephraim and from all the remnant of Israel and from all Judah and Benjamin and from the inhabitants of Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 10, 'They delivered it to the workers who had the oversight of the house of the LORD, and the workers who were working in the house of the LORD gave it for repairing and restoring the house.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 11, 'They gave it to the carpenters and the builders to buy quarried stone, and timber for binders, and beams for the buildings that the kings of Judah had let go to ruin.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 12, 'The people did the work faithfully. Over them were appointed the Levites Jahath and Obadiah, of the sons of Merari, along with Zechariah and Meshullam, of the sons of the Kohathites, to have oversight. Other Levites, all skillful with instruments of music,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 13, 'were over the burden bearers and directed all who did work in every kind of service; and some of the Levites were scribes, and officials, and gatekeepers.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 14, 'While they were bringing out the money that had been brought into the house of the LORD, the priest Hilkiah found the book of the law of the LORD given through Moses.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 15, 'Hilkiah said to the secretary Shaphan, "I have found the book of the law in the house of the LORD"; and Hilkiah gave the book to Shaphan.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 16, 'Shaphan brought the book to the king, and further reported to the king, "All that was committed to your servants they are doing.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 17, 'They have emptied out the money that was found in the house of the LORD and have delivered it into the hand of the overseers and the workers."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 18, 'The secretary Shaphan informed the king, "The priest Hilkiah has given me a book." Shaphan then read it aloud to the king.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 19, 'When the king heard the words of the law he tore his clothes.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 20, 'Then the king commanded Hilkiah, Ahikam son of Shaphan, Abdon son of Micah, the secretary Shaphan, and the king"s servant Asaiah:', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 21, '"Go, inquire of the LORD for me and for those who are left in Israel and in Judah, concerning the words of the book that has been found; for the wrath of the LORD that is poured out on us is great, because our ancestors did not keep the word of the LORD, to act in accordance with all that is written in this book."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 22, 'So Hilkiah and those whom the king had sent went to the prophet Huldah, the wife of Shallum son of Tokhath son of Hasrah, keeper of the wardrobe (who lived in Jerusalem in the Second Quarter) and spoke to her to that effect.', 'en', 'NRSV-CE', 'The Prophet Huldah Consulted'),
(14, '2 Taw', '2 Chronicles', 34, 23, 'She declared to them, "Thus says the LORD, the God of Israel: Tell the man who sent you to me,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 24, 'Thus says the LORD: I will indeed bring disaster upon this place and upon its inhabitants, all the curses that are written in the book that was read before the king of Judah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 25, 'Because they have forsaken me and have made offerings to other gods, so that they have provoked me to anger with all the works of their hands, my wrath will be poured out on this place and will not be quenched.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 26, 'But as to the king of Judah, who sent you to inquire of the LORD, thus shall you say to him: Thus says the LORD, the God of Israel: Regarding the words that you have heard,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 27, 'because your heart was penitent and you humbled yourself before God when you heard his words against this place and its inhabitants, and you have humbled yourself before me, and have torn your clothes and wept before me, I also have heard you, says the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 28, 'I will gather you to your ancestors and you shall be gathered to your grave in peace; your eyes shall not see all the disaster that I will bring on this place and its inhabitants." They took the message back to the king.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 29, 'Then the king sent word and gathered together all the elders of Judah and Jerusalem.', 'en', 'NRSV-CE', 'The Covenant Renewed'),
(14, '2 Taw', '2 Chronicles', 34, 30, 'The king went up to the house of the LORD, with all the people of Judah, the inhabitants of Jerusalem, the priests and the Levites, all the people both great and small; he read in their hearing all the words of the book of the covenant that had been found in the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 31, 'The king stood in his place and made a covenant before the LORD, to follow the LORD, keeping his commandments, his decrees, and his statutes, with all his heart and all his soul, to perform the words of the covenant that were written in this book.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 32, 'Then he made all who were present in Jerusalem and in Benjamin pledge themselves to it. And the inhabitants of Jerusalem acted according to the covenant of God, the God of their ancestors.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 34, 33, 'Josiah took away all the abominations from all the territory that belonged to the people of Israel, and made all who were in Israel worship the LORD their God. All his days they did not turn away from following the LORD the God of their ancestors.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 35, 1, 'Josiah kept a passover to the LORD in Jerusalem; they slaughtered the passover lamb on the fourteenth day of the first month.', 'en', 'NRSV-CE', 'Celebration of the Passover'),
(14, '2 Taw', '2 Chronicles', 35, 2, 'He appointed the priests to their offices and encouraged them in the service of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 3, 'He said to the Levites who taught all Israel and who were holy to the LORD, "Put the holy ark in the house that Solomon son of David, king of Israel, built; you need no longer carry it on your shoulders. Now serve the LORD your God and his people Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 4, 'Make preparations by your ancestral houses by your divisions, following the written directions of King David of Israel and the written directions of his son Solomon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 5, 'Take position in the holy place according to the groupings of the ancestral houses of your kindred the people, and let there be Levites for each division of an ancestral house.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 6, 'Slaughter the passover lamb, sanctify yourselves, and on behalf of your kindred make preparations, acting according to the word of the LORD by Moses."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 7, 'Then Josiah contributed to the people, as passover offerings for all that were present, lambs and kids from the flock to the number of thirty thousand, and three thousand bulls; these were from the king"s possessions.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 8, 'His officials contributed willingly to the people, to the priests, and to the Levites. Hilkiah, Zechariah, and Jehiel, the chief officers of the house of God, gave to the priests for the passover offerings two thousand six hundred lambs and kids and three hundred bulls.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 9, 'Conaniah also, and his brothers Shemaiah and Nethanel, and Hashabiah and Jeiel and Jozabad, the chiefs of the Levites, gave to the Levites for the passover offerings five thousand lambs and kids and five hundred bulls.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 10, 'When the service had been prepared for, the priests stood in their place, and the Levites in their divisions according to the king"s command.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 11, 'They slaughtered the passover lamb, and the priests dashed the blood that they received from them, while the Levites did the skinning.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 12, 'They set aside the burnt offerings so that they might distribute them according to the groupings of the ancestral houses of the people, to offer to the LORD, as it is written in the book of Moses. And they did the same with the bulls.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 13, 'They roasted the passover lamb with fire according to the ordinance; and they boiled the holy offerings in pots, in caldrons, and in pans, and carried them quickly to all the people.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 14, 'Afterward they made preparations for themselves and for the priests, because the priests the descendants of Aaron were occupied in offering the burnt offerings and the fat parts until night; so the Levites made preparations for themselves and for the priests, the descendants of Aaron.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 15, 'The singers, the descendants of Asaph, were in their place according to the command of David, and Asaph, and Heman, and the king"s seer Jeduthun. The gatekeepers were at each gate; they did not need to interrupt their service, for their kindred the Levites made preparations for them.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 16, 'So all the service of the LORD was prepared that day, to keep the passover and to offer burnt offerings on the altar of the LORD, according to the command of King Josiah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 17, 'The people of Israel who were present kept the passover at that time, and the festival of unleavened bread seven days.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 18, 'No passover like it had been kept in Israel since the days of the prophet Samuel; none of the kings of Israel had kept such a passover as was kept by Josiah, by the priests and the Levites, by all Judah and Israel who were present, and by the inhabitants of Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 19, 'In the eighteenth year of the reign of Josiah this passover was kept.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 20, 'After all this, when Josiah had set the temple in order, King Neco of Egypt went up to fight at Carchemish on the Euphrates, and Josiah went out against him.', 'en', 'NRSV-CE', 'Defeat by Pharaoh Neco and Death of Josiah'),
(14, '2 Taw', '2 Chronicles', 35, 21, 'But Neco sent envoys to him, saying, "What have I to do with you, king of Judah? I am not coming against you today, but against the house with which I am at war; and God has commanded me to hurry. Cease opposing God, who is with me, so that he will not destroy you."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 22, 'But Josiah would not turn away from him, but disguised himself in order to fight with him. He did not listen to the words of Neco from the mouth of God, but joined battle in the plain of Megiddo.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 23, 'The archers shot King Josiah; and the king said to his servants, "Take me away, for I am badly wounded."', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 24, 'So his servants took him out of the chariot and carried him in his second chariot and brought him to Jerusalem. There he died, and was buried in the tombs of his ancestors. All Judah and Jerusalem mourned for Josiah.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 25, 'Jeremiah also uttered a lament for Josiah, and all the singing men and singing women have spoken of Josiah in their laments to this day. They made these a custom in Israel; they are recorded in the Laments.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 26, 'Now the rest of the acts of Josiah and his faithful deeds in accordance with what is written in the law of the LORD,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 35, 27, 'and his acts, first and last, are written in the Book of the Kings of Israel and Judah.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(14, '2 Taw', '2 Chronicles', 36, 1, 'The people of the land took Jehoahaz son of Josiah and made him king to succeed his father in Jerusalem.', 'en', 'NRSV-CE', 'Reign of Jehoahaz'),
(14, '2 Taw', '2 Chronicles', 36, 2, 'Jehoahaz was twenty-three years old when he began to reign; he reigned three months in Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 3, 'Then the king of Egypt deposed him in Jerusalem and laid on the land a tribute of one hundred talents of silver and one talent of gold.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 4, 'The king of Egypt made his brother Eliakim king over Judah and Jerusalem, and changed his name to Jehoiakim; but Neco took his brother Jehoahaz and carried him to Egypt.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 5, 'Jehoiakim was twenty-five years old when he began to reign; he reigned eleven years in Jerusalem. He did what was evil in the sight of the LORD his God.', 'en', 'NRSV-CE', 'Reign and Captivity of Jehoiakim'),
(14, '2 Taw', '2 Chronicles', 36, 6, 'Against him King Nebuchadnezzar of Babylon came up, and bound him with fetters to take him to Babylon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 7, 'Nebuchadnezzar also carried some of the vessels of the house of the LORD to Babylon and put them in his palace in Babylon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 8, 'Now the rest of the acts of Jehoiakim, and the abominations that he did, and what was found against him, are written in the Book of the Kings of Israel and Judah; and his son Jehoiachin succeeded him.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 9, 'Jehoiachin was eight years old when he began to reign; he reigned three months and ten days in Jerusalem. He did what was evil in the sight of the LORD.', 'en', 'NRSV-CE', 'Reign and Captivity of Jehoiachin'),
(14, '2 Taw', '2 Chronicles', 36, 10, 'In the spring of the year King Nebuchadnezzar sent and brought him to Babylon, along with the precious vessels of the house of the LORD, and made his brother Zedekiah king over Judah and Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 11, 'Zedekiah was twenty-one years old when he began to reign; he reigned eleven years in Jerusalem.', 'en', 'NRSV-CE', 'Reign of Zedekiah'),
(14, '2 Taw', '2 Chronicles', 36, 12, 'He did what was evil in the sight of the LORD his God. He did not humble himself before the prophet Jeremiah who spoke from the mouth of the LORD.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 13, 'He also rebelled against King Nebuchadnezzar, who had made him swear by God; he stiffened his neck and hardened his heart against turning to the LORD, the God of Israel.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 14, 'All the leading priests and the people also were exceedingly unfaithful, following all the abominations of the nations; and they polluted the house of the LORD that he had consecrated in Jerusalem.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 15, 'The LORD, the God of their ancestors, sent persistently to them by his messengers, because he had compassion on his people and on his dwelling place;', 'en', 'NRSV-CE', 'The Fall of Jerusalem'),
(14, '2 Taw', '2 Chronicles', 36, 16, 'but they kept mocking the messengers of God, despising his words, and scoffing at his prophets, until the wrath of the LORD against his people became so great that there was no remedy.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 17, 'Therefore he brought up against them the king of the Chaldeans, who killed their youths with the sword in the house of their sanctuary, and had no compassion on young man or young woman, the aged or the feeble; he gave them all into his hand.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 18, 'All the vessels of the house of God, large and small, and the treasures of the house of the LORD, and the treasures of the king and of his officials, all these he brought to Babylon.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 19, 'They burned the house of God, broke down the wall of Jerusalem, burned all its palaces with fire, and destroyed all its precious vessels.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 20, 'He took into exile in Babylon those who had escaped from the sword, and they became servants to him and to his sons until the establishment of the kingdom of Persia,', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 21, 'to fulfill the word of the LORD by the mouth of Jeremiah, until the land had made up for its sabbaths. All the days that it lay desolate it kept sabbath, to fulfill seventy years.', 'en', 'NRSV-CE', NULL),
(14, '2 Taw', '2 Chronicles', 36, 22, 'In the first year of King Cyrus of Persia, in fulfillment of the word of the LORD spoken by Jeremiah, the LORD stirred up the spirit of King Cyrus of Persia so that he sent a herald throughout all his kingdom and also declared in a written edict:', 'en', 'NRSV-CE', 'Cyrus Proclaims Liberty for the Exiles'),
(14, '2 Taw', '2 Chronicles', 36, 23, '"Thus says King Cyrus of Persia: The LORD, the God of heaven, has given me all the kingdoms of the earth, and he has charged me to build him a house at Jerusalem, which is in Judah. Whoever is among you of all his people, may the LORD his God be with him! Let him go up."', 'en', 'NRSV-CE', NULL);
